const double INF = 1e9;

int main()
{
    cout << fixed << setprecision(10);

    vector<L> ys;

    int n;
    cin >> n;
    const int half = ((n * (n - 1) / 2) + 1) / 2;
    rep(i, n)
    {
        int a, b, c;
        cin >> a >> b >> c;
        ys.push_back(make_tuple(a, b, c));
    }

    double result[2];
    rep(i, 2)
    {
        sort(ys.begin(), ys.end(), [](const L& lh, const L& rh) {
            int la, lb, lc, ra, rb, rc;
            tie(la, lb, lc) = lh;
            tie(ra, rb, rc) = rh;

            const double ly = (lc + la * INF) / lb, ry = (rc + ra * INF) / rb;
            return ly < ry;
        });

        double lb = -1e9, ub = 1e9;
        while (ub - lb >= 1e-10) {
            const double mid = ub / 2 + lb / 2;

            vector<P> tmp;
            rep(i, ys.size())
            {
                int a, b, c;
                tie(a, b, c) = ys[i];
                tmp.push_back(make_tuple((c - a * mid) / b, i));
            }
            sort(tmp.begin(), tmp.end());

            int64_t intersection = 0;
            BinaryIndexedTree bit(tmp.size());
            rep(i, tmp.size())
            {
                size_t j;
                tie(ignore, j) = tmp[i];
                intersection += bit.find(tmp.size()) - bit.find(j + 1);
                bit.add(j, 1);
            }

            (intersection >= half ? ub : lb)
                = mid;
        }
        result[i] = ub;

        for (L& l : ys) {
            swap(get<0>(l), get<1>(l));
        }
    }
    cout << result[0] << " " << result[1] << endl;

    return 0;
}

