#include <bits/stdc++.h>
using namespace std;

// zero-based numbering
template<class T> struct Fenwick {
    vector<T> bit; int N;
    Fenwick(int n) : N(n) { bit.assign(n+1, 0); }
    void clear() { bit.assign(N+1, 0); }
    // add w to a
    void add(int a, T w) {
        for (int x = ++a; x <= N; x += x & -x) bit[x] += w;
    }
    // sum [0, a)
    T sum(int a) {
        T ret = 0;
        for (int x = a; x > 0; x -= x & -x) ret += bit[x];
        return ret;
    }
    // sum [a, b)
    T sum(int a, int b) { return sum(b) - sum(a); }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int N; cin >> N;
    using Line = array<double, 2>;
    vector<Line> x, y;
    vector<int> idx;
    for (int i = 0; i < N; i++) {
        double a, b, c; cin >> a >> b >> c;
        x.push_back({-a/b, c/b});
        y.push_back({-b/a, c/a});
        idx.emplace_back(i);
    }
    Fenwick<int> fw(N);
    auto f = [&](auto &v) {
        const int M = (N * (N - 1) / 2) / 2;
        const int C = 60;
        sort(v.begin(), v.end());
        double ok = 1e5, ng = -1e5;
        for (int ci = 0; ci < C; ci++) {
            fw.clear();
            double x = (ok + ng) / 2;
            auto cmp = [&](int &i, int &j) {
                double p = v[i][0] * x + v[i][1];
                double q = v[j][0] * x + v[j][1];
                return (p != q) ? p < q : i > j;
            };
            sort(idx.begin(), idx.end(), cmp);
            int m = 0;
            for (auto &i: idx) {
                m += fw.sum(i, N); fw.add(i, 1);
            }
            if (m <= M) ok = x;
            else ng = x;
        }
        return ok;
    };
    cout << setprecision(12) << f(x) << " " << f(y) << "\n";
    return 0;
}

