public: long long sum(int i) {
      long long s = 0;
      while (i > 0) {
        s += bit[i];
        i -= i & -i;
      }
      return s;
    }

    // bit[i] += x
    BitSum(int n) {
      MAXN = n;
      bit.resize(n+1);
    }

public: void add(int i, long long x) {
      while (i <= MAXN) {
        bit[i] += x;
        i += i & -i;
      }
    }

public: void reset() {
      for(int i=0; i<=MAXN; i++) {
        bit.at(i) = 0;
      }
    }

    // return the smallest i where sum(i) >= val
    // If sum(MAXN) < val, return INT_MAX
public: int lower_bound(long long val) {
      int min = 0;
      int max = MAXN;
      if (sum(max) < val) return INT_MAX;
      if (sum(0) >= val) return 0;
      while(min + 1 < max) {
        int now = (min+max)/2;
        if (sum(now) >= val) {
          max = now;
        } else {
          min = now;
        }
      }
      return max;
    }
};


class ECARtesianCoodinate {
public:

    double calc(vector<int>& a, vector<int>& b, vector<int>& c) {
      int n = a.size();
      double mi = -10000;
      double ma = 10000;
      vector<pair<double, double>> vec(n);
      vector<double> grad(n);
      BitSum bs(n);
      rep(_, 50) {
        auto med = (mi+ma)/2;
        rep(i, n) {
          // ax + by = c;
          // y = (c-ax)/b
          vec[i].first = (c[i] - a[i]*med)/b[i];
          vec[i].second = ((double)-a[i])/b[i];
          grad[i] = vec[i].second;
          debug(vec[i].first, vec[i].second);
        }
        sort(all(vec));
        sort(all(grad));
        map<double, int> mp;
        rep(i, n) {
          mp[grad[i]] = i+1;
        }
        bs.reset();
        ll low = 0;
        ll high = 0;
        rep(i, n) {
          int p = mp[vec[i].second];
          debug(p);
          ll cnt = bs.sum(p);
          high += cnt;
          low += i-cnt;
          bs.add(p, 1);
        }
        debug(med, low, high);
        if (low <= high) {
          ma = med;
        } else {
          mi = med;
        }
      }
      return mi;
    }


