			for(int i = 0; i < n; i++){
				now += query(pos[cid[i]], n);
				add(pos[cid[i]], 1);
			}
			for(int i = 0; i < n; i++) add(pos[cid[i]], -1);
			if(now >= (tot + 1) / 2) hi = mid;
			else lo = mid;
		}
		cout << hi << " ";
