bool eval(double z){
	repp(i,0,N) t[s[i]] = (C[s[i]] - A[s[i]] * z) / B[s[i]];
	sort(u,u+N,[&](const int p , const int q){return t[s[p]] < t[s[q]];});
	int w = 0;
	bit.dft();
	repp(i,0,N){
		w += bit.get(u[i]);
		bit.add(0,1);
		bit.add(u[i]+1,-1);
	}
	return w < (N * (N-1) / 2 + 1) / 2;
}

double BS(double x , double y , int t){
	double z = (x+y)/2;
	if(t == 0) return z;
	return eval(z) ? BS(z,y,t-1) : BS(x,z,t-1);
}

