int mergecount(vector<double> &a) {
    int count = 0;
    int n = a.size();
    if (n > 1) {
        vector<double> b(a.begin(), a.begin() + n/2);
        vector<double> c(a.begin() + n/2, a.end());
        count += mergecount(b);
        count += mergecount(c);
        for (int i = 0, j = 0, k = 0; i < n; ++i)
            if (k == c.size())       a[i] = b[j++];
            else if (j == b.size())  a[i] = c[k++];
            else if (b[j] <= c[k] - EPS)   a[i] = b[j++];
            else                   { a[i] = c[k++]; count += n/2 - j; }
    }
    return count;
}

bool check(const vector<L> &e, double x) {
    vector<double> v;
    REP(i, e.size()) {
        int a, b, c; tie(a, b, c) = e[i];
        double y = (-a * x + c) / b;
        v.emplace_back(y);
    }
    ll pn = (ll)e.size() * ((ll)e.size()-1) / 2;
    ll res = mergecount(v);
    return pn - res <= (pn - 1) / 2;
}

double solve(vector<L> e) {
    sort(e.begin(), e.end(), [](const L &a, const L &b) {
        return get<0>(a) * get<1>(b) > get<0>(b) * get<1>(a);
    });

    double l = - 1e10, r = 1e10;
    REP(_, 300) {
        double x = (l+r) / 2;
        if(!check(e, x)) r = x;
        else l = x;
    }
    return l;
}

