#include <bits/stdc++.h>

using namespace std;
typedef long long ll;
const int MAXN = 100010;
const double EPS = 1e-12;
const double LIM = 1e7;
int _w;

int dcmp( double x ) {
	return fabs(x) < EPS ? 0 : (x < 0 ? -1 : 1);
}

int n, k[MAXN];
double a[MAXN], b[MAXN], c[MAXN];
double p;
int tmp[MAXN];

namespace BIT {
	int c[MAXN];
	int lowbit( int x ) {
		return x & (-x);
	}
	void init() {
		memset(c, 0, sizeof c);
	}
	void add( int p ) {
		for( ; p <= n; p += lowbit(p) )
			++c[p];
	}
	int sum( int p ) {
		int s = 0;
		for( ; p; p -= lowbit(p) )
			s += c[p];
		return s;
	}
	int sum( int l, int r ) {
		return sum(r) - sum(l-1);
	}
}

bool cmpx( int i, int j ) {
	double yi = (c[i] - a[i] * p) / b[i];
	double yj = (c[j] - a[j] * p) / b[j];
	return dcmp(yi - yj) < 0;
}
void checkx( double x, ll &lcnt, ll &rcnt ) {
	for( int i = 0; i < n; ++i ) tmp[i] = i;
	p = x, sort(tmp, tmp+n, cmpx);
	lcnt = 0, rcnt = 0;
	BIT::init();
	for( int i = 0; i < n; ++i ) {
		lcnt += BIT::sum( 1, k[tmp[i]] );
		rcnt += BIT::sum( k[tmp[i]], n );
		BIT::add( k[tmp[i]] );
	}
}
double solvex() {
	ll half = (ll)n*(n-1)/2;
	half = (half>>1) + (half&1);
	double low = -LIM, high = LIM;
	while( dcmp(high-low) ) {
		double mid = (low+high)/2;
		ll lcnt, rcnt;
		checkx(mid, lcnt, rcnt);
		if( lcnt >= half ) high = mid;
		else low = mid;
	}
	return low;
}

bool cmpy( int i, int j ) {
	double xi = (c[i] - b[i] * p) / a[i];
	double xj = (c[j] - b[j] * p) / a[j];
	return dcmp(xi - xj) < 0;
}
void checky( double y, ll &lcnt, ll &rcnt ) {
	for( int i = 0; i < n; ++i ) tmp[i] = i;
	p = y, sort(tmp, tmp+n, cmpy);
	lcnt = rcnt = 0;
	BIT::init();
	for( int i = 0; i < n; ++i ) {
		rcnt += BIT::sum( k[tmp[i]], n );
		lcnt += BIT::sum( 1, k[tmp[i]] );
		BIT::add( k[tmp[i]] );
	}
}
double solvey() {
	ll half = (ll)n*(n-1)/2;
	half = (half>>1) + (half&1);
	double low = -LIM, high = LIM;
	while( dcmp(high-low) ) {
		double mid = (low+high)/2;
		ll lcnt, rcnt;
		checky(mid, lcnt, rcnt);
		if( lcnt >= half ) high = mid;
		else low = mid;
	}
	return low;
}

bool cmpkx( int i, int j ) {
	double ki = -a[i] / b[i];
	double kj = -a[j] / b[j];
	return dcmp(ki - kj) < 0;
}
bool cmpky( int i, int j ) {
	double ki = -b[i] / a[i];
	double kj = -b[j] / a[j];
	return dcmp(ki - kj) < 0;
}

