struct BIT {
    BIT(int n) : s(n + 1), n(n) {}
    int sum(int k) {
        int r = 0;
        for (; k > 0; k -= k & -k) r += s[k];
        return r;
    }
    void add(int i, int v) {
        for (int k = i + 1; k <= n; k += k & -k) s[k] += v;
    }
    vector<int> s;
    int n;
};

struct Line {
    bool operator<(const Line& l) {
        return t < l.t;
    }
    double t, r;
    int16_t a, b, c;
    uint16_t j;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<Line> l(n);
    for (int i = 0; i < n; i++) {
        cin >> l[i].a >> l[i].b >> l[i].c;
    }

    BIT b(n);
    int m = (n - 1) * n / 2;
    int h = (m + 1) / 2;

    for (int u = 0; u < 2; u++) {
        for (int i = 0; i < n; i++) {
            l[i].t = (double)l[i].a / l[i].b;
        }
        sort(l.begin(), l.end());

        for (int i = 0; i < n; i++) {
            l[i].r = 1.0 / l[i].b;
            l[i].j = i;
        }

        double x, x1 = 2e+8, x0 = -x1;
        while (1) {
            x = (x0 + x1) * 0.5;
            if (x1 - x0 < 1.6e-9 * max(abs(x), 1.0)) break;

            for (int i = 0; i < n; i++) {
                l[i].t = (l[i].c - l[i].a * x) * l[i].r;
            }
            sort(l.begin(), l.end());

            fill(b.s.begin(), b.s.end(), 0);

            int k = m;
            for (int i = 0; i < n; i++) {
                int j = l[i].j;
                k -= b.sum(j);
                b.add(j, 1);
            }
            if (k < h) x0 = x; else x1 = x;
        }

        cout << fixed << setprecision(12) << x << " \n"[u];

        if (u == 1) break;

        for (int i = 0; i < n; i++) {
            swap(l[i].a, l[i].b);
        }
    }

    return 0;
}

