int countRev(const vector<int> &v) {
    Segtree<int> st = Segtree<int>(vector<int>(v.size()));
  int ret = 0;

  for (int i = 0; i < v.size(); ++i) {
    const int c = v[i];
    st.update(c, 1);
    ret += st.query(c + 1, v.size());
  }

  return ret;
}
int countSmall(double x) {
  // calc point
  for (int i = 0; i < N; ++i) {
    xp[i].first = (C[i] - double(A[i]) * x) / B[i];
    xp[i].second = i;
  }

  vector<int> rank1(N);
  vector<int> rank2(N);

  sort(xp, xp + N);
  for (int i = 0; i < N; ++i) {
    rank1[kp[i].second] = i;
    rank2[xp[i].second] = i;
  }

  vector<int> rank3(N);
  for (int i = 0; i < N; ++i) {
    rank3[rank2[kp[i].second]] = i;
  }

  return countRev(rank3);
}

double sol() {
  for (int i = 0; i < N; ++i) {
    kp[i].first = 1.0 * A[i] / B[i];
    kp[i].second = i;
  }

  // cout << endl;
  sort(kp, kp + N);
  double l = -1E9;
  double r = 1E9;
  double ret = r;
  const int k = (N * (N - 1) / 2 + 1) / 2;
  while (r - l > 1E-9) {
    double x = l + (r - l) / 2;
    // cout << "x: " << x << "  =========" << endl;
    if (countSmall(x) >= k) {
      ret = x;
      r = x - eps;
    } else {
      l = x + eps;
    }
  }
  return ret;
}
