			long double px = (c[x] + a[x] * 20000) * 1. / b[x];
			long double py = (c[y] + a[y] * 20000) * 1. / b[y];
			if(px == py) return x < y;
			return px < py;
		});
		for(int i = 0; i < n; i++) pos[id[i]] = i;
		long double lo = -1e4 -100, hi = 1e4 + 100;
		int tot = n * (n - 1) / 2;
