				long double y = (c[x] - a[x] * mid) / b[x];
				return y;
			};
			sort(cid, cid + n, [&](int x, int y){
				long double px = get_y(x), py = get_y(y);
				if(px == py) return pos[x] > pos[y];
				return px < py;
			});
			int now = 0;
			fenwick_tree<int> fw(n + 10, 1);
