		l = -1, r = dat.size();
		while (l + 1 < r) {
			int m = (l + r) / 2;
			if (query(m) >= x) r = m;
			else l = m;
		}
		return (r);
	}
};

//0-indexed
long long invNum(vector<int> &perm) {
	long long ans = 0;
	int n = perm.size();
	BIT<int> tree(n);
	for (int j = 0; j < n; j++) {
		ans += j-tree.query(perm[j]);
		tree.add(perm[j], 1);
	}
	return (ans);
}

