struct BIT
{
	// [0,size)
	vector<int> tree;
	int size;
	BIT(int s){
		size=s;
		tree.resize(size+1);
	}
	void init(int s){
		size=s;
		tree.clear();
		tree.resize(size+1);
	}
	void add(int i,int v){
		i++;
		while(i<=size){
			tree[i]+=v;
			i+=(i&-i);
		}
	}

	// [0,i)
	int collect(int i){
		int r=0;
		while(i>0){
			r+=tree[i];
			i-=(i&-i);
		}
		return r;
	}

	// [a,b)
	int collect(int a, int b){
		return collect(b)-collect(a);
	}
};



