class BIT
{
public:
	ll bit[SIZE + 1];
	void init()
	{
		fill(bit, bit + SIZE + 1, 0);
	}
	void add(int a, ll b)
	{
		a++;
		for (;;)
		{
			bit[a] += b;
			a += a&-a;
			if (a > SIZE)return;
		}
	}
	ll get(int a)
	{
		a++;
		ll ret = 0;
		for (;;)
		{
			ret += bit[a];
			a -= a&-a;
			if (a == 0)return ret;
		}
