                else neg0.add0(cX[i]+1,1),++sum;
            }
            (cnt>=half?ub:lb)=mid;
        }
        ans[_]=ub;
        for (int i=0;i<N;++i) swap(ls[i].A,ls[i].B);
    }
    cout << fixed << setprecision(15);
    cout << ans[0] << ' ' << ans[1] << '\n';
}

