template<typename T>
struct BIT {
	ll n;
	vector<T> bt;
	ll sz;

	BIT(ll n0) {
		n = n0;
		sz = 1;
		while (sz < n) { sz *= 2; }
		bt.assign(sz + 1, 0);
	}

	ll sum(ll i) {
		T ret = 0;
		for (ll x = i; x >0; x -= x & (-x)) {
			ret += bt[x];
		}
		return ret;
	}

	void add(ll i, ll w) {
		for (ll x = i; x <=sz; x += x & (-x)) {
			bt[x] += w;
		}
		return;
	}
};



template <typename T>
ll tento(ll N, vector<T> A) {
	vector<pair<T, ll>> p(N + 1);

	repn(i, N) p[i] = { A[i],i };
	sort(++p.begin(), p.end());

	BIT<T> bit(N);
	ll ret = 0;

	repn(i, N) {
		ll t = p[i].second;
		ret += bit.sum(t);
		bit.add(t, 1);
	}

	ret = N * (N - 1) / 2 - ret;
	return ret;
}


ll num(vector<double> A, vector<double> B, vector<double> C, ll N, double X) {
	vector<pair<double,double>> isc(N + 1);

	repn(i, N) {
		isc[i].first = (C[i] - A[i] * X) / B[i];
		isc[i].second = -A[i] / B[i];
	}

	sort(++isc.begin(), isc.end());

	vector<double> D(N + 1);
	repn(i, N) D[i] = isc[i].second;

	ll ret = tento(N, D);

	return ret;

}


