int pos[N];
int bit[N], bitsize;
int n;

int get(int x) {
    int res = 0;
    while (x >= 0) {
        res += bit[x];
        x -= ~x & (x + 1);
    }
    return res;
}

void update(int x, int delta) {
    while (x < bitsize) {
        bit[x] += delta;
        x |= x + 1;
    }
}

int count(double x) {
    for (int i = 0; i < n; ++i) {
        val[i] = make_pair(-(d[i].c - x * d[i].a) / d[i].b, i);
    }
    sort(val, val + n);
    int npos = 0;
    for (int i = 0; i < n; ) {
        int j = i + 1;
        while (j < n && abs(val[i].first - val[j].first) < EPS) ++j;
        for (int k = i; k < j; ++k) pos[val[k].second] = npos;
        ++npos;
        i = j;
    }
    bitsize = npos;
    fill_n(bit, bitsize, 0);
    int res = 0;
    for (int i = 0; i < n; ++i) {
        res += get(pos[i]);
        update(pos[i], 1);
    }
    return res;
}

