int sum (int r)
{
	int result = 0;
	for (; r >= 0; r = (r & (r+1)) - 1)
		result += t[r];
	return result;
}

void inc (int i, int delta)
{
	for (; i < N; i = (i | (i+1)))
		t[i] += delta;
}
bool cmp(pair < pair < int, int >, pair < int, int > > x, pair < pair < int, int >, pair < int, int > > y){
    double v1 = (x.S.F - p * x.F.F) * y.F.S;
    double v2 = (y.S.F - p * y.F.F) * x.F.S;
    return (v1 < v2);
}
bool cmp2(int i, int j){
    if (a[i].F.F < 0 && a[j].F.F > 0) return 1;
    if (a[i].F.F > 0 && a[j].F.F < 0) return 0;
    if (a[i].F.F > 0 && a[j].F.F > 0) return a[i].F.F * a[i].F.F * (a[j].F.F * a[j].F.F + a[j].F.S * a[j].F.S) < a[j].F.F * a[j].F.F * (a[i].F.F * a[i].F.F + a[i].F.S * a[i].F.S);
    if (a[i].F.F < 0 && a[j].F.F < 0) return a[i].F.F * a[i].F.F * (a[j].F.F * a[j].F.F + a[j].F.S * a[j].F.S) > a[j].F.F * a[j].F.F * (a[i].F.F * a[i].F.F + a[i].F.S * a[i].F.S);
}
double solve(int n){
    double l = -1e10;
    double r = 1e10;
    for (int i = 1; i <= n; i++){
        q[i] = i;
    }
    sort(q + 1, q + n + 1, cmp2);
    for (int i = 1; i <= n; i++) d[q[i]] = i;
    while(r - l > 1e-12){
        double mid = (r + l) / 2;
        p = mid;
        sort(a + 1, a + n + 1, cmp);;
        int c = 0;
        for (int i = 0; i < N; i++) t[i] = 0;
        for (int i = 1; i <= n; i++){
            c += sum(d[a[i].S .S]);
            inc(d[a[i].S.S], 1);
        }
        if (4 * c > n * (n - 1)) l = mid; else r = mid;
    }
    return l;
}
