il int gi(){
  RG int x=0,q=1; RG char ch=getchar();
  while ((ch<'0' || ch>'9') && ch!='-') ch=getchar();
  if (ch=='-') q=-1,ch=getchar();
  while (ch>='0' && ch<='9') x=x*10+ch-48,ch=getchar();
  return q*x;
}

il int cmpk(const data &a,const data &b){ return a.k<b.k; }

il int cmp(const double &a,const double &b){ return fabs(a-b)<eps; }

il void add(RG int x){ for (;x<=n;x+=lb(x)) ++c[x]; return; }

il int query(RG int x){
  RG int res=0; for (;x;x^=lb(x)) res+=c[x]; return res;
}

il int check(RG double key){
  RG int tot=0,res=0;
  for (RG int i=1;i<=n;++i)
    p[i].k=-l[i].a/l[i].b,p[i].y=(l[i].c-l[i].a*key)/l[i].b,hsh[++tot]=p[i].y;
  sort(p+1,p+n+1,cmpk),sort(hsh+1,hsh+tot+1),tot=unique(hsh+1,hsh+tot+1,cmp)-hsh-1;
  for (RG int i=1;i<=n;++i) c[i]=0,p[i].i=lower_bound(hsh+1,hsh+tot+1,p[i].y)-hsh;
  for (RG int i=1;i<=n;++i) res+=query(p[i].i),add(p[i].i); return res>=k;
}

int main(){
  n=gi(),k=((n*(n-1)>>1)+1)>>1;
  for (RG int i=1;i<=n;++i)
    l[i].a=gi(),l[i].b=gi(),l[i].c=gi();
  L=-1e9,R=1e9;
  while (R-L>eps)
    mid=(L+R)/2,check(mid)?(X=mid,R=mid):L=mid;
  for (RG int i=1;i<=n;++i) swap(l[i].a,l[i].b);
  L=-1e9,R=1e9;
  while (R-L>eps)
    mid=(L+R)/2,check(mid)?(Y=mid,R=mid):L=mid;
