using VP = vector<P>;
const ld eps = 1e-8, pi = acos(-1.0);

#define EQ(a,b) (abs((a)-(b))<eps)

ld dot (P a, P b) { return real(conj(a) * b); }
ld cross (P a, P b) { return imag(conj(a) * b); }

namespace std {
  bool operator<(const P &lhs, const P &rhs) {
    return lhs.real() == rhs.real() ? lhs.imag() < rhs.imag()
                                    : lhs.real() < rhs.real();
  }
}

struct L{ P a, b; };
struct C { P p; ld r; };

// counter clockwise
int ccw (P a, P b, P c) {
  b -= a; c -= a;
  if (cross(b, c) > eps) return 1;   // counter clockwise
  if (cross(b, c) < -eps) return -1; // clockwise
  if (dot(b, c) < 0) return 2;       // c--a--b on line
  if (norm(b) < norm(c)) return -2;  // a--b--c on line
  return 0;                          // a--c--b on line
}

bool isis_ll(L l, L m) {
  return abs(cross(l.b - l.a, m.b - m.a)) > eps;
}

P is_ll(L s, L t){
  P sv = s.b - s.a, tv = t.b - t.a;
  return s.a + sv * cross(tv, t.a - s.a) / cross(tv, sv);
}

L make_line(ld a, ld b, ld c) {
  P p1, p2;
  if (abs(a) < eps) {
    if (abs(b) < eps) {
      if (c < 0) return (L){P(1e9, 0), P(1e9, 1e9)};
      return (L){P(1e9, 1e9), P(1e9, 0)};
    }
    p1 = P(0, -c/b); p2 = P(1, -c/b);
  }
  else {
    p1 = P(-c/a, 0); p2 = P((-b-c)/a, 1);
  }
  P p = (p2 - p1) * P(0, 1) + p1;
  ld x = real(p), y = imag(p);
  if (a * x + b * y + c < 0) return (L){p1, p2};
  else return (L){p2, p1};
}

int n;
vector<ld> a, b, c;

// vector<L> ls;
vector<P> ps;

vector<ld> xs, ys;

P solve() {
    xs.clear();
    ys.clear();
    rep(i, n) rep(j, i) {
        L l = make_line(a[i], b[i], -c[i]);
        L m = make_line(a[j], b[j], -c[j]);
        P p = is_ll(l, m);
        xs.push_back(p.real());
        ys.push_back(p.imag());
    }

    int m = xs.size();
    sort(all(xs));
    sort(all(ys));

    return P(xs[(m-1) / 2], ys[(m-1) / 2]);
}

