// 1-indexed BIT (i : [1, len])
template<typename T, int len>
struct BIT
{
    array<T, len + 1> val;
    BIT() { val.fill(0); }
    void add(int pos, T v)
    {
        while (pos > 0 && pos <= len)
        {
            val[pos] += v;
            pos += pos & -pos;
        }
    }
    T sum(int pos)
    {
        T res = 0;
        while (pos > 0)
        {
            res += val[pos];
            pos -= pos & -pos;
        }
        return res;
    }
};


int cnt(const vector<double> &vec)
{
    vector<double> vec_sorted = vec;
    sort(vec_sorted.begin(), vec_sorted.end());

    map<double, int> ma;
    REP(i, vec_sorted.size()) ma[vec_sorted[i]] = i + 1;

    BIT<int, 40001> bit;
    int ans = 0;
    for (auto v : vec)
    {
        ans += bit.sum(ma[v]);
        bit.add(ma[v], 1);
    }
    return ans;
}

double solve(const vector<int> &A, const vector<int> &B, const vector<int> &C)
{
    using p = pair<double, double>;
    vector<p> info(N);
    REP(i, N) info[i] = p((double)A[i] / B[i], (double)C[i] / B[i]);
    sort(info.begin(), info.end());

    double l = -2E8, r = 2E8;
    while (r - l > 1E-10 and (r - l) > (abs(l) + abs(r)) * 1E-10)
    {
        double c = (l + r) / 2;
        vector<double> vec(N);
        REP(i, N) vec[i] = info[i].second - info[i].first * c;
        if (cnt(vec) > N * (N - 1) / 2 / 2) l = c;
        else r = c;
    }
    return l;
}

