typedef pair<pair<int, int>, int> line;

inline pair<double, double> cross(const line& l1, const line& l2)
{
    int a1 = l1.first.first;
    int b1 = l1.first.second;
    int c1 = l1.second;

    int a2 = l2.first.first;
    int b2 = l2.first.second;
    int c2 = l2.second;

    double x = (double)(c1 * b2 - c2 * b1) / (a1 * b2 - a2 * b1);
    double y = (double)(c1 * a2 - c2 * a1) / (b1 * a2 - b2 * a1);

    return make_pair(x, y);
}

int main()
{
    cin.tie(0);
    int n;
    cin >> n;

    vector<line> vs(n);

    for (auto& p : vs) {
        cin >> p.first.first >> p.first.second >> p.second;
    }

    int th = (n * (n - 1) / 2 + 1) / 2;

    double lo_x = -1e9, hi_x = 1e9;
    double lo_y = -1e9, hi_y = 1e9;

    for (int t = 0; t < 70; t++) {
        double mi_x = (lo_x + hi_x) / 2;
        double mi_y = (lo_y + hi_y) / 2;

        int cnt_x = 0;
        int cnt_y = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                auto c = cross(vs[i], vs[j]);

                // cout << c.first << ", " << c.second << endl;
                if (c.first < mi_x) {
                    cnt_x++;
                }
                if (c.second < mi_y) {
                    cnt_y++;
                }
            }
        }

        if (cnt_x < th) {
            lo_x = mi_x;
        } else {
            hi_x = mi_x;
        }
        if (cnt_y < th) {
            lo_y = mi_y;
        } else {
            hi_y = mi_y;
        }
    }

    printf("%.12f %.12f\n", (lo_x + hi_x) / 2, (lo_y + hi_y) / 2);

    return 0;
}

