template <class T>
class bit {
    public:
    bit(int n);
    ~bit();
    void clear();
    void add(int x, T value);
    T get(int x) const; // [0, x]

    private:
    int size;
    T* data;
};

template <class T> bit<T>::bit(int n) : size(n + 1) {
    data = (T *)calloc(size, sizeof(T));
}

template <class T> bit<T>::~bit() {
    free(data);
}

template <class T> void bit<T>::clear() {
    for (int i = 0; i < size; i++) data[i] = 0;
}

template <class T> void bit<T>::add(int x, T value) {
    for (x++; x < size; x += x & -x) data[x] += value;
}

template <class T> T bit<T>::get(int x) const {
    T value = 0;
    for (x++; x > 0; x -= x & -x) value += data[x];
    return value;
}

