        yLine[i].k = (double)(-b[i])/(double)a[i];
        yLine[i].b = (double)c[i]/(double)a[i];
    }
    std::sort(xLine+1,xLine+1+n,[&](Line& u,Line& v){ return u.k<v.k; });
    std::sort(yLine+1,yLine+1+n,[&](Line& u,Line& v){ return u.k<v.k; });
    //yLine sort...
    printf("%.12f %.12f\n",getAnswer(xLine,n),getAnswer(yLine,n));
    return 0;
}

