ll merge_sort(int l, int r) {
	int m = (l + r) / 2;
	ll ret = 0;
	if (l + 1 < m)	ret += merge_sort(l, m);
	if (m + 1 < r)	ret += merge_sort(m, r);
	int als = 0, ars = 0;
	srep(i, l, m)	al[als++] = pos[i];
	srep(i, m, r)	ar[ars++] = pos[i];
	int s = 0, t = 0;
	srep(i, l, r) {
		if (s == als)	pos[i] = ar[t++];
		else if (t == ars)	pos[i] = al[s++];
		else if (al[s] > ar[t]) {
			pos[i] = ar[t++];
			ret += als - s;
		}
		else	pos[i] = al[s++];
	}
	return ret;
}

