	rep(j, n)	pos[j] = (ld)-(c[j] - a[j] * mid) / b[j];
	ll rightp = merge_sort(0, n);
	if (line != inf) {
		if (line < mid)	leftp += n;
		else if (mid < line)	rightp += n;
	}
	return leftp - rightp;
}

