        f[i] = std::make_pair(-a[i] / b[i], (c[i] - a[i] * mid) / b[i]);
        v[i] = f[i].second;
    }
    sv = Umr(v, v + n);
    bit.clear();
    std::sort(f, f + n);
    LL ret = 0;
    for (int i = 0; i < n; ++ i) {
        ret += bit.query(sv.get(f[i].second));
        bit.modify(sv.get(f[i].second), 1);
    }
    return ret;
}

