int id1[111111], ord[111111];
double dir[111111];
bool cmp1(int x,int y){
	return dir[x] > dir[y];
}
bool cmp2(int x,int y){
	return dir[x] < dir[y];
}

int lowbit(int x){return x&-x;}
int bit[111111];
void add(int x){
	while(x<=n){
		bit[x]++;
		x+=lowbit(x);
	}
}
int query(int x){
	int res=0;
	while(x){
		res += bit[x];
		x-=lowbit(x);
	}
	return res;
}

double process(){
	for(int i=0; i<n; i++){
		id1[i] = i;
		dir[i] = ((double)(-a[i]))/b[i];
	}
	sort(id1, id1 + n, cmp1);
	for(int i=0; i<n; i++)
		ord[id1[i]] = i;
	long long int AA = (n * (n-1LL)/2 + 1)/2;

	double lo = -2e9, hi = 2e9;
	for(int run = 0; run < 80; run++){
		double mi = (lo + hi)/2;
		for(int i=0; i<n; i++){
			id1[i] = i;
			dir[i] = (c[i] - a[i] * mi)/b[i];
		}
		sort(id1, id1+n, cmp2);

		memset(bit,0,sizeof(bit));
		long long int BB = 0;
		for(int i=n-1; i>=0; i--){
			int x = ord[id1[i]] + 1;
			BB += query(x);
			add(x);
		}
		if(BB < AA)
			lo = mi;
		else
			hi = mi;
	}
	return lo;
}
