pair<llint,deque<lldo>> tensort(const deque<lldo>& in,int hi,int mg){//転倒数を計算しながらソートします
	if(hi+1==mg){
		deque<lldo>iti;
		iti.pub(in[hi]);
		return mp((llint)0,iti);
	}
	int mid=(hi+mg)/2;
	auto hso=tensort(in,hi,mid);
	auto mso=tensort(in,mid,mg);
	llint ans=hso.fir+mso.fir;
	deque<lldo>iti;
	while(hso.sec.size()!=0||mso.sec.size()!=0){
		if(hso.sec.empty()){iti.pub(mso.sec.front());mso.sec.pof();}
		else if(mso.sec.empty()){iti.pub(hso.sec.front());hso.sec.pof();}
		else if(hso.sec.front()<mso.sec.front()){iti.pub(hso.sec.front());hso.sec.pof();}
		else{iti.pub(mso.sec.front());mso.sec.pof();ans+=hso.sec.size();}
	}
	return mp(ans,iti);
}
lldo solve(vector<tuple<int,int,int>> a){
	int n,i;n=a.size();
	vector<tuple<lldo,lldo,int>>car(n);//y=ax+b
	for(i=0;i<n;i++){
		get<0>(car[i])=(lldo)-get<0>(a[i])/(lldo)get<1>(a[i]);
		get<1>(car[i])=(lldo)get<2>(a[i])/(lldo)get<1>(a[i]);
		get<2>(car[i])=i;
	}
	sort(car.begin(),car.end());//xを無限大に飛ばしたときの車の配置
	lldo bmax=big,bmin=-big;
	for(int q=0;q<100;q++){
		lldo gen=(bmax+bmin)/2;
		deque<lldo> ima(n);
		for(i=0;i<n;i++){ima[i]=get<0>(car[i])*gen+get<1>(car[i]);}
		llint beet=tensort(ima,0,n).fir;
		if(beet<=(n*(n-1)/4)){bmax=gen;}
		else{bmin=gen;}

	}
	return bmin;
}
