	for(i=0;i<n;i++){cin>>get<0>(a[i])>>get<1>(a[i])>>get<2>(a[i]);}
	cout<<setprecision(20)<<solve(a);
	for(i=0;i<n;i++){swap(get<0>(a[i]),get<1>(a[i]));}
	cout<<" "<<solve(a)<<endl;
	return 0;
}

