struct bit {
    int n;
    int* dat;

    bit(int _n) {
        n = 1;
        while(n < _n) n *= 2;
        dat = new int[n + 1];
        fill(dat + 1, dat + n + 1, 0);
    }

    void update(int i, int x) {
        while(i <= n) {
            dat[i] += x;
            i += i & -i;
        }
    }

    int query(int i) {
        int res = 0;
        while(i > 0) {
            res += dat[i];
            i -= i & -i;
        }
        return res;
    }
};

struct line {
    double a, b, c;

    bool operator<(const line& rhs) const {
        return a / b < rhs.a / rhs.b;
    }
};

signed main() {
