    bit bt(n);

    sort(lines, lines + n);

    double left = -1e8*2, right = 1e8*2;
    while(right - left > EPS) {
        double mid = (left + right) / 2;
        DIP* dip = new DIP[n];
        rep(i, n) {
            line l = lines[i];
            dip[i] = DIP(-l.a / l.b * mid + l.c / l.b, i);
        }
        sort(dip, dip + n);

        fill(bt.dat + 1, bt.dat + bt.n + 1, 0);
        ll res = 0;
        rep(i, n) {
            res += i - bt.query(dip[i].second + 1);
            bt.update(dip[i].second + 1, 1);
        }

        if(res >= ((ll)n * (n - 1) + 2) / 4) right = mid;
        else left = mid;
    }
    double x = left;

    rep(i, n) lines[i] = {lines[i].b, lines[i].a, lines[i].c};
    sort(lines, lines + n);

    left = -1e8*2, right = 1e8*2;
    while(right - left > EPS) {
        double mid = (left + right) / 2;
        DIP* dip = new DIP[n];
        rep(i, n) {
            line l = lines[i];
            dip[i] = DIP(-l.a / l.b * mid + l.c / l.b, i);
        }
