class BinaryIndexedTree
{
public:
  int n;
  vector<int> tree;

  BinaryIndexedTree(int N)
    : n(N), tree(vector<int>(n + 1, 0))
  {}

  void add(int a, int w) {
    for (int x = a; x <= n; x += (x & -x)) {
      tree[x] += w;
    }
  }

  int sum(int a) {
    int s = 0;
    for (int x = a; x > 0; x -= (x & -x)) {
      s += tree[x];
    }
    return s;
  }
};


int count_inv(int N, int * l) {
  BinaryIndexedTree bit(N);
  int ans = 0;
  REP(j, N) {
    ans += j - bit.sum(l[j]);
    bit.add(l[j], 1);
  }
  return ans;
}


int count_crossed_lines(int N, int * A, int * B, int * C, int * s, double x) {
  vector< pair<double, int> > Y;
  int li;
  REP(i, N) {
    li = s[i];
    Y.push_back(make_pair((-A[li] * x + C[li]) / B[li], i+1));
  }
  sort(Y.begin(), Y.end());
  int y_argsort[N];
  REP(i, N) {
    y_argsort[i] = Y.at(i).second;
  }
  return count_inv(N, y_argsort);
}


void sort_lines(int N, int * A, int * B, int * C, int * s) {
  vector< pair<double, int> > angles;
  REP(i, N) {
    angles.push_back(make_pair(double(A[i]) / B[i], i));
  }
  sort(angles.begin(), angles.end());
  REP(i, N) {
    s[i] = angles.at(i).second;
  }
}


double find_coord(int N, int * A, int * B, int * C) {
  int med_v = ceil(N * (N-1) / 4.0);
  int lines_sorted[N];
  sort_lines(N, A, B, C, lines_sorted);
  // bin-search
  double rg[2] = {-INF, INF};
  double d, m = (rg[0] + rg[1]) / 2;
  do {
    int cl = count_crossed_lines(N, A, B, C, lines_sorted, m);
    if (cl < med_v) rg[0] = m;
    else rg[1] = m;
    d = rg[1] - rg[0];
    m = (rg[0] + rg[1]) / 2;
  } while (d > 1e-9);

  return m;
}

int main(void)
{
  cin.tie(0);
  ios::sync_with_stdio(false);

  int N;
  cin >> N;
  int A[N], B[N], C[N];
  REP(i, N) {
    cin >> A[i] >> B[i] >> C[i];
  }
  cout << setprecision(12) << find_coord(N, A, B, C) << " " << find_coord(N, B, A, C) << "\n";
  return 0;
}

