template <typename T>
using F2 = std::function<T(T,T)>;

template <typename T, int N, typename F = std::plus<T> >
struct SegmentTree{
    SegmentTree(T u, F f = F()){
        size = 1;
        while(size < N){
            size <<= 1;
        }

        unit = u;
        func = f;

        init();
    }
    void init(){
        for(int i=1;i<2*size;++i){
            data[i] = unit;
        }
    }
    void update(int k, T v){
        k += size;
        data[k] = v;

        while(k > 1){
            k >>= 1;
            data[k] = func(data[k*2], data[k*2+1]);
        }
    }
    inline T query(int l, int r){
        return _query(l, r, 1, 0, size);
    }
    T _query(int a, int b, int k, int l, int r){
        if(b <= l || r <= a){return unit;}
        if(a <= l && r <= b){return data[k];}
        int mid = (l + r) >> 1;
        return func(_query(a, b,   2*k,   l, mid),
                    _query(a, b, 2*k+1, mid, r  ));
    }

    T unit, data[N*4];
    int size;
    F func;
};

SegmentTree<ll, 10100> segtree(0);

template <typename F>
double middle(F f){
    double lb = 1e10, ub = -1e10;

    for(int t=0;t<100;++t){
        vector<tuple<double, int> > v;

        double mid = (lb + ub) / 2;
        for(int i=0;i<N;++i){
            double value = f(mid, ls[i]);
            v.emplace_back(value, i);
        }

        std::sort(v.begin(), v.end());
        v.erase(std::unique(v.begin(), v.end()), v.end());

        segtree.init();

        ll tento = 0;
        for(int i=0;i<N;++i){
            tento += segtree.query(0, N) - segtree.query(0, snd(v[i]));
            segtree.update(snd(v[i]), 1);
        }

        if(tento >= ((1ll * N * (N - 1) / 2) + 1) / 2){
            lb = mid;
        }else{
            ub = mid;
        }
    }

    return lb;
}

