struct BIT{
    vector<ll> bt;
    size_t n,m;
    explicit BIT(size_t n):n(n),m(1){
        while(m<=n) m<<=1u;
        m>>=1u;
        bt.resize(n+1);
    }
    ll sum(ll i){//sum of [1,i](1-index)
        if(!i) return 0;
        ll tmp{};
        for(size_t k=i;k;k-=k&-k) tmp+=bt[k];
        return tmp;
    }
    void ad(ll i,ll x){//add to i(1-index)
        for(size_t k=i;k<=n;k+=k&-k) bt[k]+=x;
    }
    ll lb(ll k){//if sum(i)<k and sum(i) >= k, return i
        ll x=0;
        for(size_t i=m;i>0;i>>=1u){
            if(x+i<=n&&bt[x+i]<k) {
                k-=bt[x+i];
                x+=i;
            }
        }
        return x+1;
    }
};

