using namespace std;

const int N = 100010;
const double eps = 1e-10;
const double oo = 1e8;

struct Line{
	int A, B, C;
}L[N];

inline bool cmpx(const Line& u, const Line &v){
	return double(u.A) / u.B > double(v.A) / v.B;
}

inline bool cmpy(const Line& u, const Line &v){
	return double(u.B) / u.A > double(v.B) / v.A;
}

double P, val[N];

inline bool cmp(int u, int v){
	return val[u] < val[v];
}

int rk[N], n;

int c[N];

inline int lowbit(int x){
	return x & (-x);
}

inline void add(int x){
	while(x <= n){
		c[x]++;
		x += lowbit(x);
	}
}

inline int sum(int x){
	int ret = 0;
	while(x){
		ret += c[x];
		x -= lowbit(x);
	}
	return ret;
}

bool checkx(double x){
	P = x;
	For(i, 1, n) val[i] = (L[i].C - P * L[i].A) / L[i].B, rk[i] = i, c[i] = 0;
	sort(rk + 1, rk + n + 1, cmp);
	long long ret = 0;
	Forr(i, n, 1) ret += sum(rk[i]), add(rk[i]);
	return ret * 4 <= 1LL * n * (n - 1);
}

bool checky(double x){
	P = x;
	For(i, 1, n) val[i] = (L[i].C - P * L[i].B) / L[i].A, rk[i] = i, c[i] = 0;
	sort(rk + 1, rk + n + 1, cmp);
	long long ret = 0;
	Forr(i, n, 1) ret += sum(rk[i]), add(rk[i]);
	return ret * 4 <= 1LL * n * (n - 1);
}

int main(){
	scanf("%d", &n);
	For(i, 1, n) scanf("%d%d%d", &L[i].A, &L[i].B, &L[i].C);

	sort(L + 1, L + n + 1, cmpx);	
	double l = -oo, r = oo;
	while(r - l > eps){
		double mid = (l + r) / 2.0;
		if(checkx(mid)) r = mid;
		else l = mid;
	}

	printf("%.10lf ", l);


	sort(L + 1, L + n + 1, cmpy);
	l = -oo, r = oo;
	while(r - l > eps){
		double mid = (l + r) / 2.0;
		if(checky(mid)) r = mid;
		else l = mid;
	}

	printf("%.10lf\n", l);


	return 0;
}

