    int center = (cross - 1) / 2;

    auto fx = [&](double x){
        vector<pair<double, double>> p;
        for(int i = 0; i < n; ++i){
            double kat = -1.0 * a[i] / b[i];
            double y_pos= 1.0 * (c[i] - a[i] * x) / b[i];
            p.emplace_back(y_pos, kat);
        }
        sort(p.begin(), p.end());
        int cou = 0;
        multiset<double> s;
        for(auto& q : p){
            auto it = s.lower_bound(q.second);
            cou += distance(s.begin(), it);
            s.insert(q.second);
        }
        return cou > center;
    };

    auto fy = [&](double y){
        vector<pair<double, double>> p;
        for(int i = 0; i < n; ++i){
            double kat = -1.0 * b[i] / a[i];
            double y_pos= 1.0 * (c[i] - b[i] * y) / a[i];
            p.emplace_back(y_pos, kat);
        }
        sort(p.begin(), p.end());
        int cou = 0;
        multiset<double> s;
        for(auto& q : p){
            auto it = s.lower_bound(q.second);
            cou += distance(s.begin(), it);
            s.insert(q.second);
        }
        return cou > center;
    };

    double st_x = -1e9;
    double en_x = 1e9;
    for(int i = 0; i < 64; ++i){
        double cent = (st_x + en_x) / 2;
