	if (l>=r)return 0;
	int mid=(l+r)>>1;ll ans=0;
	ans+=work(l,mid);
	ans+=work(mid+1,r);
	int i1=l,i2=mid+1;
	for (int i=l;i<=r;i++){
		if (i1<=mid&&(i2>r||q[i1]<q[i2])) p[i]=q[i1++];
