            return bias > 0 ? ans < -EPS : ans > EPS;
        });
        int sect = 0;
        rep (i, 0, n) {
            int id = nums[i].second;
            update(tree, id + 1, 1);
            int inter = read(tree, id + 1);
            sect += i + 1 - inter;

        }
        if (sect >= median) {
            r = x;
        } else {
            l = x;
        }

    }
    cout << fixed;
    cout << setprecision(15) << l << " ";
    sort(lines, lines + n, [](line a, line b) {
             ll q = (1ll * a.b * b.a) - (1ll * b.b * a.a);
             return 1ll * b.a * a.a > 0 ? q < 0 : q > 0;

         }

    );
    rep (i, 0, n)lines[i].id = i;
    l = -INF * 1.000, r = INF * 1.000;
    while (r - l > EPS) {
        double x = (l + r) / 2;
        int tree[n + 1] = {0};
        pair<line, int> nums[n];
        rep (i, 0, n) {
             nums[i].first = {lines[i].a, lines[i].b, lines[i].c};
            nums[i].second = lines[i].id;
        }
        sort(nums, nums + n, [x](pair<line, int> l1, pair<line, int> l2) {
            line ln1 = l1.first;
            line ln2 = l2.first;
            ll p1 = 1ll * ln2.b * ln1.a - 1ll * ln2.a * ln1.b;
            ll p2 =  1ll *ln2.c * ln1.a- ln2.a * ln1.c;
            ll bias = 1ll*ln1.a*ln2.a;
            double ans = p1*x - p2;
            if (abs(ans)<EPS) return l1.second > l2.second;

            return bias > 0 ? ans < -EPS : ans > EPS;
        });
        int sect = 0;
        rep (i, 0, n) {
            int id = nums[i].second;
            update(tree, id + 1, 1);
            int inter = read(tree, id + 1);
            sect += i + 1 - inter;

        }
        if (sect >= median) {
            r = x;
        } else {
            l = x;
        }

    }
    cout << setprecision(15) << l << " ";
    return 0;
}

