template<typename T, size_t N>
struct fenwick {
  T c[N];
  void clear() {
    fill(c + 1, c + N, 0);
  }
  void add(int x, T y) {
    for (; x < N; x += x & -x) {
      c[x] += y;
    }
  }
  T sum(int x) {
    T ret = 0;
    for (; x; x -= x & -x) {
      ret += c[x];
    }
    return ret;
  }
  T query(int L, int R) {
    return sum(R) - sum(L - 1);
  }
};

