#define For(i, j, k) for(int i = j; i <= k; i++)
#define Forr(i, j, k) for(int i = j; i >= k; i--)
#define pb push_back

using namespace std;

const int N = 100010;
const double eps = 1e-10;
const double oo = 1e12;

struct Line{
	int A, B, C;
}L[N];

bool cmpx(const Line& u, const Line &v){
	return double(u.A) / u.B > double(v.A) / v.B;
}

bool cmpy(const Line& u, const Line &v){
	return double(u.B) / u.A > double(v.B) / v.A;
}

double P;

bool cmpxval(int u, int v){
	return (L[u].C - P * L[u].A) / L[u].B < (L[v].C - P * L[v].A) / L[v].B;
}

bool cmpyval(int u, int v){
	return (L[u].C - P * L[u].B) / L[u].A < (L[v].C - P * L[v].B) / L[v].A;
}

int rk[N], n;

int c[N];

int lowbit(int x){
	return x & (-x);
}

void add(int x){
	while(x <= n){
		c[x]++;
		x += lowbit(x);
	}
}

int sum(int x){
	int ret = 0;
	while(x){
		ret += c[x];
		x -= lowbit(x);
	}
	return ret;
}

bool checkx(double x){
	P = x;
	For(i, 1, n) rk[i] = i, c[i] = 0;
	sort(rk + 1, rk + n + 1, cmpxval);
	long long ret = 0;
	Forr(i, n, 1) ret += sum(rk[i]), add(rk[i]);
	return ret * 4 <= 1LL * n * (n - 1);
}

bool checky(double x){
	P = x;
	For(i, 1, n) rk[i] = i, c[i] = 0;
	sort(rk + 1, rk + n + 1, cmpyval);
	long long ret = 0;
	Forr(i, n, 1) ret += sum(rk[i]), add(rk[i]);
	return ret * 4 <= 1LL * n * (n - 1);
}

int main(){
	scanf("%d", &n);
	For(i, 1, n) scanf("%d%d%d", &L[i].A, &L[i].B, &L[i].C);

	sort(L + 1, L + n + 1, cmpx);	
	double l = -oo, r = oo;
	while(r - l > eps){
		double mid = (l + r) / 2.0;
		if(checkx(mid)) r = mid;
