template<typename T>
struct Segment_Tree {
	typedef function<T(T, T)> F;

	ll n;
	F f;//モノイドとしての演算(最小値、和　など)
	T unit;//単位元

	ll size;
	vector<T> seg;

	Segment_Tree(ll n0, F f0, T unit0) {
		n = n0;
		f = f0;
		unit = unit0;

		size = 1;
		while (size < n) {
			size *= 2;
		}
		seg.assign(2 * size, unit);
	}


	void update(ll k, T x) {//k番目の要素をxに更新
		k += size - 1;
		seg[k] = x;
		while (k > 1) {
			k /= 2;
			seg[k] = f(seg[2 * k], seg[2 * k + 1]);
		}
	}



	T query_prep(ll a, ll b, ll k, ll l, ll r) {//[a,b)とkに対応する区間[l,r)の共通部分でクエリ
		if (b <= l || a >= r) { return unit; }
		if (a <= l && r <= b) { return seg[k]; }

		T v1 = query_prep(a, b, 2 * k, l, (l + r) / 2);
		T v2 = query_prep(a, b, 2 * k + 1, (l + r) / 2, r);
		return f(v1, v2);

	}

	T query(ll a, ll b) {
		return query_prep(a, b, 1, 1, size + 1);
	}

};

ll tento(ll N, vector<double> A) {
	vector<pair<double, ll>> p(N + 1);
	repn(i, N) p[i] = { A[i],i };
	sort(++p.begin(), p.end());

	Segment_Tree<ll> sg(N, [](ll a, ll b) {return a + b; }, 0);
	ll ret = 0;

	repn(i, N) {
		ll t = p[i].second;
		ret += sg.query(1, t);
		sg.update(t, 1);
	}

	ret = N * (N - 1) / 2 - ret;
	return ret;
}


ll num(vector<double> A, vector<double> B, vector<double> C, ll N, double x) {
	vector<pair<double,double>> isc(N + 1);

	repn(i, N) {
		isc[i].first = (C[i] - A[i] * x) / B[i];
		isc[i].second = -A[i] / B[i];
	}

	sort(++isc.begin(), isc.end());

	vector<double> D(N + 1);
	repn(i, N) D[i] = isc[i].second;

	ll ret = tento(N, D);

	return ret;

}


