const int depth = 16;
class Segtree {
	int data[1 << (depth + 1)];
public:

	void init() { for (int i = 0; i < (1 << (depth + 1)); i++) data[i] = 0; }

	//区間[l, r)にvを足す
	void add(int l, int r, int v, int a = 0, int b = (1 << depth), int id = 0) {
		if (l >= b || r <= a) return;
		if (l <= a && b <= r) { data[id] += v; return; }
		add(l, r, v, a, a + (b - a) / 2, id * 2 + 1);
		add(l, r, v, a + (b - a) / 2, b, id * 2 + 2);
	}

	//要素posの値
	int getNum(int pos) {
		pos = (1 << depth) - 1 + pos;
		int ret = data[pos];
		while (pos > 0) {
			pos = (pos - 1) / 2;
			ret += data[pos];
		}
		return ret;
	}
};

Segtree seg;

int getHanten(vector<double> a) {
	map<int, int> pos;
	int i;
	int n = a.size();

	for (i = 0; i < n; i++) {
		pos[a[i]] = i;
	}
	for (i = 0; i < n; i++) seg.add(i, i + 1, i);

	sort(a.begin(), a.end());

	int ans = 0;
	for (i = 0; i < n; i++) {
		ans += seg.getNum(pos[a[i]]);
		seg.add(pos[a[i]] + 1, n, -1);
	}
	return ans;
}

