pair<llint,deque<lldo>> tensort(const deque<lldo>& in,int hi,int mg){//転倒数を計算しながらソートします
	if(hi+1==mg){
		deque<lldo>iti;
		iti.pub(in[hi]);
		return mp((llint)0,iti);
	}
	int mid=(hi+mg)/2;
	auto hso=tensort(in,hi,mid);
	auto mso=tensort(in,mid,mg);
	llint ans=hso.fir+mso.fir;
	deque<lldo>iti;
	while(hso.sec.size()!=0||mso.sec.size()!=0){
		if(hso.sec.empty()){iti.pub(mso.sec.front());mso.sec.pof();}
		else if(mso.sec.empty()){iti.pub(hso.sec.front());hso.sec.pof();}
		else if(hso.sec.front()<mso.sec.front()){iti.pub(hso.sec.front());hso.sec.pof();}
		else{iti.pub(mso.sec.front());mso.sec.pof();ans+=hso.sec.size();}
	}
	return mp(ans,iti);
}
