struct fenwick {
    fenwick(int n) : size(n), v(n,0) {}
    void add(int n, int x){for(;n<size;n|=n+1)v[n]+=x;}
    int sum(int n){int s=0;while(n>=0){s+=v[n];n=(n&(n+1))-1;} return s;}
    int size;
    vi v;
};

struct line {
    int a,b,c;
};

double intersect(line& l, double x){
    return (-x*l.a+l.c)/l.b;
}

long long count_left(vector<line>& v, double x){
    int cnt = 0;
    vector<pair<double,int>> vec;
    vec.reserve(v.size());
    for(auto& l : v)
        vec.emplace_back(intersect(l,x), cnt++);
    sort(ALL(vec));
    fenwick f(v.size());
    long long ans = 0;
    for(auto& p : vec){
        ans += f.sum(p.second);
        f.add(p.second, 1);
    }
    return ans;
}

double medianx(vector<line>&v){
    long long n = v.size();
    long long tot = n*(n-1)/2;
    tot = (tot+1)/2;
    double l=-1e9,r=1e9;
    for(int i=0;i<90;++i){
        double m=(l+r)/2;
        if(count_left(v,m) < tot)
            l=m;
        else
            r=m;
    }
    return (l+r)/2;
}

void solve(){
    int n;
    cin>>n;
    vector<line> v(n);
    REP(i,n){
        cin>>v[i].a>>v[i].b>>v[i].c;
        if(v[i].b < 0){
            v[i].a = -v[i].a;
            v[i].b = -v[i].b;
            v[i].c = -v[i].c;
        }
    }
    sort(ALL(v), [](line&a, line&b){return a.a*b.b>a.b*b.a;});
    double x = medianx(v);
    for(auto& p : v)
        swap(p.a, p.b);
    REP(i,n)
        if(v[i].b < 0){
            v[i].a = -v[i].a;
            v[i].b = -v[i].b;
            v[i].c = -v[i].c;
        }
    sort(ALL(v), [](line&a, line&b){return a.a*b.b>a.b*b.a;});
    double y = medianx(v);
    cout<<setprecision(15)<<fixed<<x<<' '<<y<<'\n';
}

