#include<bits/stdc++.h>

using namespace std;

#define X   first
#define Y   second
#define ld  double

const int   N   = 4e4 + 5;
const ld    eps = 1e-12;

typedef pair<ld,ld> ii;
typedef pair<ii,ld> pii;

int n, t[N];

vector<pii> Line;

int fix(pii &p) {
    if (p.X.X < 0)
        p.X.X = -p.X.X,
        p.X.Y = -p.X.Y,
        p.Y = -p.Y;
}
int chk(ld  M)  {
    vector<ld>  vv;
    map<ld,int> mp;
    for(pii l : Line)
        vv.push_back((l.Y - M * l.X.Y) / l.X.X),
        mp[vv.back()] = 0;

    int tot = 0;
    int ans = 0;
    for(auto &it : mp)  it.Y = ++tot;

    for(int i = 1 ; i <= n ; ++i)   t[i] = 0;
    for(ld  x : vv) {
        for(int k = mp[x] ; k <= n ; k += k & -k)   ans += t[k];
        for(int k = mp[x] ; k >= 1 ; k -= k & -k)   t[k]++;
    }
    return  4 * ans >= n * n - n;
}
ld  work()  {
    for(pii &l : Line)  fix(l);
    sort(Line.begin(),Line.end(),[](pii &a,pii &b)  {
        return  a.X.X * b.X.Y > a.X.Y * b.X.X;
    });
    ld  L = -1e8;
    ld  R =  1e8;
    while (L + eps <= R)    {
        ld M = (L + R) / 2;
        if (chk(M))
            R = M;
        else
            L = M;
    }
    for(pii &l : Line)  swap(l.X.X,l.X.Y);
    return  abs(L) > eps ? L : 0;
}

int main()  {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    cin >> n;

    for(int i = 1 ; i <= n ; ++i)   {
        ld  a;  cin >> a;
        ld  b;  cin >> b;
        ld  c;  cin >> c;
        Line.push_back(pii({a,b},c));
    }

    ld  Y = work();
    ld  X = work();

    cout << fixed << setprecision(10) << X << " " << Y;
}

