#include <bits/stdc++.h>

#define EPSILON 1e-9

using namespace std;

struct pt {
  double x, y;
};

struct line {
  double a, b, c;
};

vector<line> lines;
vector<double> x, y;

line pointsToLine(pt p1, pt p2) {
  line l;
  if (abs(p1.x - p2.x) < EPSILON) {
    l.a = 1; l.b = 0.0; l.c = -p1.x;
  } else {
    l.a = -(double)(p1.y - p2.y) / (p1.x - p2.x);
    l.b = 1.0;
    l.c = -(double)(l.a * p1.x) - p1.y;
  }
  return l;
}

bool areIntersect(line l1, line l2, pt &p) {
  p.x = (l2.b * l1.c - l1.b * l2.c) / (l2.a * l1.b - l1.a * l2.b);
  if (abs(l1.b) > EPSILON) p.y = -(l1.a * p.x + l1.c);
  else p.y = -(l2.a * p.x + l2.c);
  return true;
}

double median(vector<double> &v) {
  nth_element(v.begin(), v.begin() + ((v.size() - 1) / 2), v.end());
  return v[(v.size() - 1) / 2];
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    double a, b, c;
    scanf("%lf %lf %lf", &a, &b, &c);
    if (b < 0) {
      a *= -1;
      b *= -1;
      c *= -1;
    }
    a /= b;
    c /= -b;
    b = 1;
    lines.push_back(line {a, b, c});
  }

  for (int i = 0; i < (int)lines.size(); i++) {
    for (int j = i + 1; j < (int)lines.size(); j++) {
      pt intersection;
      areIntersect(lines[i], lines[j], intersection);
      x.push_back(intersection.x);
      y.push_back(intersection.y);
    }
  }

  // for (double d : x) cout << d << " "; cout << endl;
  // for (double d : y) cout << d << " "; cout << endl;

  printf("%.10lf %.10lf\n", median(x), median(y));
  return 0;
}

