int cntinv(vector<int>v) {
	int N = v.size();
	fenwick_tree<int>BIT(N+1);
	int ans = 0;
	REP(i, N) {
		ans += BIT.sum(v[i],N);
		BIT.add(v[i], 1);
	}
	return ans;
}

void solve() {
	int N; cin >> N;
	vector<int>A(N), B(N), C(N);
	REP(i, N) {
		cin >> A[i] >> B[i] >> C[i];
	}
	//xを求める
	ld ok = -MAXD, ng = MAXD;
	int cnt = N * (N - 1) / 2;
	vector<int>idx(N);
	REP(_, 200) {
		ld mid = (ok + ng) / 2;
		//midの左側に交点がcnt/2個以下ならok
		ld l = -MAXD*2;
		vector<pair<ld, int>>v(N);
		REP(i, N) {
			ld ly = calcy(A[i], B[i], C[i],l);
			v[i] = { ly,i };
		}
		VSORT(v);
		REP(i, N)idx[v[i].second] = i;
		vector<pdi>v2(N);
		REP(i, N) {
			ld ry = calcy(A[i], B[i], C[i], mid);
			v2[i] = { ry,i };
		}
		VSORT(v2);
		vector<int>v3(N);
		REP(i, N)v3[i] = idx[v2[i].second];
		int res = cntinv(v3);
		//print_space(v3);
		//DEBUG(res);
		if (res <= cnt / 2)ok = mid;
		else ng = mid;
	}
	ld ansX = ok;

	//yを求める
	ok = -MAXD, ng = MAXD;
	cnt = N * (N - 1) / 2;
	REP(_, 200) {
		ld mid = (ok + ng) / 2;
		//DEBUG(mid);
		//midの左側に交点がcnt/2個以下ならok
		ld l = -MAXD*2;
		vector<pair<ld, int>>v(N);
		REP(i, N) {
			ld lx = calcx(A[i], B[i], C[i], l);
			v[i] = { lx,i };
		}
		VSORT(v);
		REP(i, N)idx[v[i].second] = i;
		vector<pdi>v2(N);
		REP(i, N) {
			ld rx = calcx(A[i], B[i], C[i], mid);
			v2[i] = { rx,i };
		}
		VSORT(v2);
		vector<int>v3(N);
