VI compress_coordinate(VD x){
    int n = x.size();
    VD xc;
    REP(i,n) xc.push_back(x[i]);
    sort(ALL(xc));
    REP(i,n-1){
        if (xc[i+1] - xc[i] < EPS) xc[i+1] = xc[i];
    }
    xc.erase(unique(ALL(xc)), xc.end());
    VI ret(n);
    REP(i,n) ret[i] = lower_bound(ALL(xc), x[i] - EPS) - xc.begin();
    return ret;
}

double calc(VD a, VD b, VD c, ll k){
    int n = a.size();
    vector<pair<double, double> > line(n);
    REP(i,n){
        line[i].first =  - a[i] / b[i];
        line[i].second = c[i] / b[i];
    }
    sort(ALL(line));

    double le = -1e9, ri = 1e9;
    REP(_,100){
        double mi = (le + ri) / 2.0;
        VD c(n);
        REP(i,n) c[i] = line[i].second + line[i].first * mi;
        VI p = compress_coordinate(c);
        BIT bit(n);
        ll tmp = 0;
        REP(i,n){
            tmp += bit.sum(p[i]);
            bit.add(p[i],1);
        }
        if (tmp >= k) ri = mi;
        else le = mi;
    }
    return ri;
}

