int lowbit(int x) {
	return x & (-x);
}
void Insert(int x) {
	while(x <= N) {
		tr[x]++;
		x += lowbit(x);
	}
}
int Query(int x) {
	int res = 0;
	while(x > 0) {
		res += tr[x];
		x -= lowbit(x);
	}
	return res;
