void Calc_y() {
	for(int i = 1 ; i <= N ; ++i) {
		t[i] = mp(atan2(-A[i],B[i]),i);
		if(t[i].fi < 0) t[i].fi += PI;
	}
	sort(t + 1,t + N + 1);
	for(int i = 1 ; i <= N ; ++i) id[t[i].se] = i;
	db L = -1e9,R = 1e9;
	int cnt = 150;
	while(cnt--) {
		db mid = (L + R) * 0.5;
		int64 res = 0;
		for(int i = 1 ; i <= N ; ++i) {
			t[i] = mp((C[i] - B[i] * mid) / A[i],id[i]);
		}
		sort(t + 1,t + N + 1);
		int p = N + 1;
		memset(tr,0,sizeof(tr));
		for(int i = N ; i >= 1 ; --i) {
			if(i != N && !dcmp(t[i + 1].fi,t[i].fi)) {
				res += 1LL * (p - i - 1) * (p - i - 2) / 2;
				for(int j = p - 1 ; j >= i + 1; --j) {
					Insert(t[j].se);
				}
				p = i + 1;
			}
			res += Query(t[i].se - 1);
		}
		res += 1LL * (p - 1) * (p - 2) / 2;
		if(res >= (ALL + 1) / 2) R = mid;
		else L = mid;
	}
	printf("%.10lf",R);
}
void Calc_x() {
	for(int i = 1 ; i <= N ; ++i) {
		t[i] = mp(atan2(-A[i],B[i]),i);
		if(t[i].fi < 0) t[i].fi += PI;
		if(t[i].fi * 2 > PI) t[i].fi -= PI;
	}
	sort(t + 1,t + N + 1);
	for(int i = 1 ; i <= N ; ++i) id[t[i].se] = i;
	db L = -1e9,R = 1e9;
	int cnt = 150;
