		db mid = (L + R) * 0.5;
		int64 res = 0;
		for(int i = 1 ; i <= N ; ++i) {
			t[i] = mp((C[i] - A[i] * mid) / B[i],id[i]);
		}
		sort(t + 1,t + N + 1);
		int p = 0;
		memset(tr,0,sizeof(tr));
		for(int i = 1 ; i <= N ; ++i) {
			if(i != 1 && !dcmp(t[i - 1].fi,t[i].fi)) {
				res += 1LL * (i - 1 - p) * (i - 1 - p - 1) / 2;
				for(int j = p + 1 ; j <= i - 1 ; ++j) {
					Insert(t[j].se);
				}
				p = i - 1;
			}
			res += Query(t[i].se - 1);
		}
		res += 1LL * (N - p) * (N - p - 1) / 2;
		if(res >= (ALL + 1) / 2) R = mid;
		else L = mid;
	}
	printf("%.10lf",R);
}
