        vector<pair<long double,int>> ys1,ys2;

        rep(i,0,N) ys1.push_back(make_pair((-A[i]*x+C[i])/B[i],i));
        sort(ys1.begin(),ys1.end());

        rep(i,0,N) ys2.push_back(make_pair(A[i]/B[i],i));
        sort(ys2.begin(),ys2.end());

        vector<int> ord(N);
        rep(i,0,N) ord[ys1[i].second]=i;

        vector<int> arr(N+1);
        rep(i,0,N) arr[i]=ord[ys2[i].second];

        i64 cnt=0;
        segtree<i64,sum> seg(N,0,0);
        rep(i,0,N){
            cnt+=seg.query(arr[i],N);
            seg.update(arr[i],1);
        }

        print(x);
        print(cnt);

        return cnt>=(N*(N-1)/2+1)/2;
    };

    auto ok_y=[&](long double y){
