        vector<int> arr(N+1);
        rep(i,0,N) arr[i]=ord[xs2[i].second];

        i64 cnt=0;
        segtree<i64,sum> seg(N,0,0);
        rep(i,0,N){
            cnt+=seg.query(arr[i],N);
            seg.update(arr[i],1);
        }

        return cnt>=(N*(N-1)/2+1)/2;
    };

    long double ans_x,ans_y;

    {
        long double lb=-inf,ub=inf;
        rep(i,0,64){
            auto mid=(lb+ub)/2;
            if(ok_x(mid)) ub=mid;
            else lb=mid;
        }
        ans_x=ub;
