template<typename T, size_t N>
struct fenwick {
  T c[N];
  void clear() {
    fill(c + 1, c + N, 0);
  }
  void add(int x, T y) {
    for (; x < N; x += x & -x) {
      c[x] += y;
    }
  }
  T sum(int x) {
    T ret = 0;
    for (; x; x -= x & -x) {
      ret += c[x];
    }
    return ret;
  }
  T query(int L, int R) {
    return sum(R) - sum(L - 1);
  }
};

const int N = 1e4 + 10;
fenwick<int, N> A;

double solve(vector<Line>& a) {
  int n = SZ(a);
  sort(a.begin(), a.end(),
       [](const Line& u, const Line& v) {
         return -1.0 * u.a / u.b > -1.0 * v.a / v.b;
       });
  int64 m = 1LL * n * (n - 1) / 2;
  m = (m + 1) / 2;
  double low = -1e10, high = 1e10;
  trace(m, a);
  for (int k = 0; k < 100; ++k) {
    double mid = (low + high) / 2;
    vector<pair<double, int>> p(n);
    for (int i = 0; i < n; ++i) {
      p[i].first = (a[i].c - a[i].a * mid) / a[i].b;
      p[i].second = i;
    }
    sort(p.begin(), p.end());
    A.clear();
    int64 cnt = 0;
    for (int i = 0; i < n; ++i) {
      cnt += A.sum(n - p[i].second);
      A.add(n - p[i].second, 1);
    }
    // trace(mid, cnt);
    if (cnt < m) {
      low = mid;
    } else {
      high = mid;
    }
  }
  return high;
}

