typedef pair<pair<int, int>, int> line;

pair<double, double> cross(const line& l1, const line& l2)
{
    const int a1 = l1.first.first;
    const int b1 = l1.first.second;
    const int c1 = l1.second;

    const int a2 = l2.first.first;
    const int b2 = l2.first.second;
    const int c2 = l2.second;

    const double x = (double)(c1 * b2 - c2 * b1) / (a1 * b2 - a2 * b1);
    const double y = (double)(c1 * a2 - c2 * a1) / (b1 * a2 - b2 * a1);

    return make_pair(x, y);
}

vector<double> rxs, rys;

int main()
{
    cin.tie(0);
    int n;
    cin >> n;

    vector<line> vs(n);
    for (auto& p : vs) {
        cin >> p.first.first >> p.first.second >> p.second;
    }

    mt19937 rng(time(nullptr));
    uniform_int_distribution<int> dist(0, n - 1);

    vector<double> xs, ys;
    const int SAMPLES = 1000000;

    for (int t = 0; t < SAMPLES; t++) {
    _rep:
        int i = dist(rng);
        int j = dist(rng);
        if (i == j)
            goto _rep;

        auto p = cross(vs[i], vs[j]);
        xs.push_back(p.first);
        ys.push_back(p.second);
    }

    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());

    double lo_x = xs[SAMPLES / 2 - SAMPLES / 1000];
    double hi_x = xs[SAMPLES / 2 + SAMPLES / 1000];
    double lo_y = ys[SAMPLES / 2 - SAMPLES / 1000];
    double hi_y = ys[SAMPLES / 2 + SAMPLES / 1000];

    if (n < 1000) {
        lo_x = xs.front();
        hi_x = xs.back();
        lo_y = ys.front();
        hi_y = ys.back();
    }
    // cerr << lo_x << ", " << hi_x << endl;
    // cerr << lo_y << ", " << hi_y << endl;

    int lo_cnt_x = 0;
    int lo_cnt_y = 0;

    static int fs[40000];
    for (int i = 0; i < n; i++) {

#pragma clang loop vectorize(enable) interleave(enable)
        for (int j = i + 1; j < n; j++) {
            const auto p = cross(vs[i], vs[j]);

            if (p.first < lo_x)
                lo_cnt_x++;
            if (p.second < lo_y)
                lo_cnt_y++;

            fs[j] = (lo_x < p.first && p.first < hi_x ? 1 : 0) + (lo_y < p.second && p.second < hi_y ? 2 : 0);
        }

        for (int j = i + 1; j < n; j++) {
            if (fs[j] & 1) {
                rxs.push_back(cross(vs[i], vs[j]).first);
            }
            if (fs[j] & 2) {
                rys.push_back(cross(vs[i], vs[j]).second);
            }
        }
    }

    int nn = (n * (n - 1) / 2 + 1) / 2;
    // cerr << lo_cnt_x << " + " << rxs.size() << " = " << lo_cnt_x + rxs.size() << " ~ " << nn << endl;
    // cerr << lo_cnt_y << " + " << rys.size() << " = " << lo_cnt_y + rys.size() << " ~ " << nn << endl;

    assert(lo_cnt_x < nn && lo_cnt_x + rxs.size() >= nn);
    assert(lo_cnt_y < nn && lo_cnt_y + rys.size() >= nn);

    sort(rxs.begin(), rxs.end());
    sort(rys.begin(), rys.end());

    printf("%.12f %.12f\n", rxs[nn - 1 - lo_cnt_x], rys[nn - 1 - lo_cnt_y]);

    return 0;
}

