struct line {
	double m,c;
	int id;
	double eval (double x) const {
		return m*x+c;
	}
};

bool operator< (const line &a, const line &b) {
	return a.m<b.m;
}

vector<line> tbl;
vector<line> tbl2;

double xx;
bool cmp(const line &a, const line &b) {
	double aa=a.eval(xx);
	double bb=b.eval(xx);
	if (aa!=bb) return aa>bb;
	return a.id>b.id;
}

int bit[10100];

void add(int idx,int val) {
	while (idx<10100) {
		bit[idx]+=val;
		idx+=(idx&-idx);
	}
}

int get(int idx) {
	int sum=0;
	while (idx) {
		sum+=bit[idx];
		idx-=(idx&-idx);
	}
	return sum;
}

vector<line> tmp;
int inter(double x) {
	xx=x;
	for (int i=0;i<(int)tbl.size();i++) {
		tmp[i]=tbl[i];
	}
	//sort(tmp.begin(),tmp.end(),cmp);
	memset(bit,0,sizeof(bit));
	int cnt=0;
	for (int i=(int)tmp.size()-1;i>=0;i--) {
		//printf("%d,%f ",tmp[i].id,tmp[i].eval(x));
		cnt+=get(tmp[i].id);
		add(tmp[i].id,1);
	}
	return cnt;
}

