signed main() {
	INIT;
	VAR(int, n);
	VEC_ROW(int, n, a, b, c);
	struct LINE { int a, b, c, i; };
	std::vector<LINE> L(n);
	REP(i, n) {
		L[i] = LINE{ a[i], b[i], c[i], i };
	}
	ld x, y;
	{ // x
		std::sort(ALL(L), [&](LINE l, LINE r) {
			if (l.b * r.b < 0) {
				return l.a * r.b > r.a * l.b;
			}
			return l.a * r.b < r.a * l.b;
		});
		REP(i, n) {
			L[i].i = i;
		}
		ld l = -10000000, r = 10000000;
		auto check = [&](ld x) {
			using P = std::multimap<ld, int>;
			P map;
			REP(i, n) {
				map.insert(P::value_type((ld)(-L[i].a*x + L[i].c) / L[i].b, L[i].i));
			}
			std::vector<int> a;
			a.reserve(n);
			for (auto p : map) {
				a.emplace_back(p.second);
			}
			int t = 0;
			ST st(n, SUM);
			REP(i, n) {
				t += i - st.query(0, a[i]);
				st.add(a[i], 1);
			}
			if ((n*(n - 1) / 2) % 2 == 0) {
				return t < n * (n - 1) / 4;
			}
			else {
				return t <= n * (n - 1) / 4;
			}
		};
		x = bisectionDouble(l, r, 70, check);
	}
	{ // y
		std::sort(ALL(L), [&](LINE l, LINE r) {
			if (l.a * r.a < 0) {
				return l.b * r.a > r.b * l.a;
			}
			return l.b * r.a < r.b * l.a;
		});
		REP(i, n) {
			L[i].i = i;
		}
		ld l = -10000000, r = 10000000;
		auto check = [&](ld y) {
			using P = std::multimap<ld, int>;
			P map;
			REP(i, n) {
				map.insert(P::value_type((ld)(-L[i].b*y + L[i].c) / L[i].a, L[i].i));
			}
			std::vector<int> a;
			a.reserve(n);
			for (auto p : map) {
				a.emplace_back(p.second);
			}
			int t = 0;
			ST st(n, SUM);
			REP(i, n) {
				t += i - st.query(0, a[i]);
				st.add(a[i], 1);
			}
			if ((n*(n - 1) / 2) % 2 == 0) {
				return t < n * (n - 1) / 4;
			}
			else {
				return t <= n * (n - 1) / 4;
			}
		};
		y = bisectionDouble(l, r, 70, check);
	}
	FOUT(12, x)SP FOUT(12, y)BR;
	return 0;
}

