template< class T >
struct BinaryIndexedTree
{
	vector< T > data;

	BinaryIndexedTree(int sz)
	{
		data.assign(++sz, 0);
	}

	T sum(int k)
	{
		T ret = 0;
		for (; k > 0; k -= k & -k) ret += data[k];
		return (ret);
	}

	void add(int k, T x)
	{
		for (++k; k < data.size(); k += k & -k) data[k] += x;
	}
};


struct line
{
	LL A, B, C;
};


const LD EPS = 1e-10;
vector<line>plane;
LL getDrop(LD X)
{
	vector<pair<LD, int>>cash;
	for (int i = 0; i < N; ++i)
	{
		const auto& lin = plane[i];
		LD Y = lin.C - lin.A * X;
		Y /= lin.B;
		cash.push_back({ Y,i });
	}
	sort(cash.rbegin(), cash.rend());
	BinaryIndexedTree<LL>bit(N);
	LL ret = 0;
	for (int i = 0; i < N; ++i)
	{
		ret += bit.sum(cash[i].second);
		bit.add(cash[i].second, 1);
	}
	return ret;
}
LD getMedian()
{
	LD lo = -1e12, hi = 1e12;
	while (hi - lo > EPS)
	{
		LD mid = (lo + hi) / 2;
		LL res = getDrop(mid);
		if (res * 2 < M)
		{
			lo = mid;
		}
		else
		{
			hi = mid;
		}
	}
	return hi;
}

int main(void)
{
	cin >> N;
	M = (N - 1) * (N) / 2;
	for (int i = 0; i < N; ++i)
	{
		int a, b, c;
		cin >> a >> b >> c;
		plane.push_back({ a,b,c });
	}
	sort(plane.begin(), plane.end(), [](const line& l1, const line& l2)
	{
		return (LD)l1.A / l1.B < (LD)l2.A / l2.B;
	});
	LD xMedian = getMedian();
	for (int i = 0; i < N; ++i)
	{
		swap(plane[i].A, plane[i].B);
	}
	sort(plane.begin(), plane.end(), [](const line& l1, const line& l2)
	{
		return (LD)l1.A / l1.B < (LD)l2.A / l2.B;
	});
	LD yMedian = getMedian();
	cout.precision(15);
	cout << xMedian << " " << yMedian << endl;
	return 0;
}

