  ios::sync_with_stdio(false);
  cin >> N;
  for (int i = 0; i < N; ++i) {
    cin >> A[i] >> B[i] >> C[i];
    int g = gcd(A[i], B[i]);
    if (C[i]) g = gcd(g, C[i]);
    A[i] /= g;
    B[i] /= g;
    C[i] /= g;
  }
  double x = sol();
  for (int i = 0; i < N; ++i) {
    swap(A[i], B[i]);
  }
  double y = sol();
  cout << setprecision(11) << fixed << x << ' ' << setprecision(11) << fixed
       << y << endl;
}

