template <typename T>
using F2 = std::function<T(T,T)>;

template <typename T, int N, typename F = std::plus<T> >
struct SegmentTree{
    SegmentTree(T u, F f = F()){
        size = 1;
        while(size < N){
            size <<= 1;
        }

        unit = u;
        func = f;

        init();
    }
    void init(){
        for(int i=1;i<2*size;++i){
            data[i] = unit;
        }
    }
    void update(int k, T v){
        k += size;
        data[k] = v;

        while(k > 1){
            k >>= 1;
            data[k] = func(data[k*2], data[k*2+1]);
        }
    }
    inline T query(int l, int r){
        return _query(l, r, 1, 0, size);
    }
    T _query(int a, int b, int k, int l, int r){
        if(b <= l || r <= a){return unit;}
        if(a <= l && r <= b){return data[k];}
        int mid = (l + r) >> 1;
        return func(_query(a, b,   2*k,   l, mid),
                    _query(a, b, 2*k+1, mid, r  ));
    }

    T unit, data[N*4];
    int size;
    F func;
};

SegmentTree<ll, 40100> segtree(0);

bool can(double x, function<double(double, P3)> f){
    vector<tuple<double, int> > v;

    for(int i=0;i<N;++i){
        double value = f(x, ls[i]);
        v.emplace_back(value, i);
    }

    std::sort(v.begin(), v.end());

    segtree.init();

    ll tento = 0;
    for(int i=0;i<N;++i){
        tento += segtree.query(0, N) - segtree.query(0, snd(v[i]));
        segtree.update(snd(v[i]), 1);
    }

    return tento >= ((1ll * N * (N - 1) / 2) + 1) / 2;
}

double middle(function<double(double, P3)> f){
    double lb = 1e20, ub = -1e20;

    for(int t=0;t<150;++t){
        double mid = (lb + ub) / 2;

        if(can(mid, f)){
            lb = mid;
        }else{
            ub = mid;
        }
    }

    return lb;
}

