const int N = 100000;

int n, a[N], b[N], c[N], order[N], fw[N];
std::pair<double, int> order2[N];

bool by_slope(int i, int j)
{
    return a[i] * b[j] < a[j] * b[i];
}

long long count(double x)
{
    for (int i_ = 0; i_ < n; ++ i_) {
        int i = order[i_];
        order2[i] = {(c[i] - a[i] * x) / b[i], i_};
    }
    std::sort(order2, order2 + n);
    memset(fw, 0, sizeof(*fw) * n);
    long long result = 0;
    for (int i = 0; i < n; ++ i) {
        for (int k = order2[i].second; k < n; k += ~k & k + 1) {
            result += fw[k];
        }
        for (int k = order2[i].second; k >= 0; k -= ~k & k + 1) {
            fw[k] ++;
        }
    }
    return result;
}

double solve()
{
    for (int i = 0; i < n; ++ i) {
        if (b[i] < 0) {
            a[i] *= -1;
            b[i] *= -1;
            c[i] *= -1;
        }
    }
    std::sort(order, order + n, by_slope);
    auto need = (1LL * n * (n - 1) >> 1) + 1 >> 1;
    double x_min = -2e8;
    double x_max = +2e8;
    for (int _ = 0; _ < 70; ++ _) {
        double x = 0.5 * (x_min + x_max);
        if (count(x) >= need) {
            x_max = x;
        } else {
            x_min = x;
        }
    }
    return 0.5 * (x_min + x_min);
}

