    }
} base;

struct Line2D {
    vec2 a, b;

    Line2D() {}
    Line2D(vec2 a, vec2 b) : a(a), b(b) {}

    int getIntersection(Line2D &line, vec2 &p) {
        if (fabs((a - b) ^ (line.a - line.b)) < eps) {
            if (fabs((a - line.a) ^ (b - line.b)) < eps &&
                fabs((a - line.b) ^ (b - line.a)) < eps) return -1;
            else return 1;
        }
        double t = ((line.b - line.a) ^ (a - line.a)) / ((b - a) ^ (line.b - line.a));
        p = a + (b - a).scale(t);
        return 0;
    }
