class BIT{
    //index : 1-based
    public:
        vector<ll> bit;
        ll M;

        BIT(ll M):
            bit(vector<ll>(M + 1, 0)), M(M) {}
        ll sum(ll i){
            if (!i) return 0;
            return bit[i] + sum(i - (i & -i));
        }

        void add(ll i, ll x){
            if (i > M) return;
            bit[i] += x;
            add(i + (i & -i), x);
        }
};  

const ll MAX_N = 4e4;
ll N;
struct line{
    double A, B, C;
    double grad1() {return - (A / B);} //y = px + qの形に書いた時の傾き
    double grad2() {return - (B / A);} // x = py + qの形に書いた時の傾き
};
struct line L[MAX_N];

vector<double> at_x(double x){
    //values Y at X = x
    vector<double> v;
    REP(i, N) v.pb((L[i].C - L[i].A * x) / L[i].B);
    return v;
}

vector<double> at_y(double y){
    //values X at Y = y
    vector<double> v;
    REP(i, N) v.pb((L[i].C - L[i].B * y) / L[i].A);
    return v;
}


ll inversion(vector<double> x){
    //vector xの転倒数を求める
    BIT t(N);
    vector<pair<double, ll>> y;
    ll ans = 0;
    REP(i, x.size()){
        y.pb(mp(x[i], i));        
