int cnt_lef(double X) {
	b.resize(n+1);
	mp.clear();
	for (int i = 0; i < n; i++) {
		mp[A[i] * X + B[i]].push_back(ord[i]);
	}
	int same = 0;
	int rig = 0;
	for (auto it = mp.rbegin(); it != mp.rend(); it++) {
		same += (*it).second.size()*((*it).second.size() - 1) / 2;
		vector<double> &V = (*it).second;
		for (auto a : V) {
			rig += b.sum(a-1);
			b.add(a,1);
		}
	}
	int lef = n*(n - 1) / 2 - same - rig;
	return rig - lef;
}

double solve() {
	mpp.clear();
	for (int i = 0; i < n; i++) {
		mpp[A[i]] = 0;
	}
	int cc = 0;
	for (auto it = mpp.begin(); it != mpp.end(); it++) {
		(*it).second = cc;
		cc++;
	}
	for (int i = 0; i < n; i++) {
		ord[i] = mpp[A[i]];
	}
	double mint = -19999;
	double maxt = 19999;
	double EP = 1e-11;
	while (mint + EP < maxt) {
			double mid = (mint + maxt) / 2.0;
			int flag = cnt_lef(mid);
			if (flag <= 0) {
				maxt = mid;
			}
			else {
				mint = mid;
			}
	}
	return mint;
}
