typedef long long ll;
typedef long double ld;
typedef pair <ll, ll> ll2;
typedef pair <ld, ld> ldld;

const ll lim = 20000000000ll;
const int Maxn = 100005;

int n;
int A[Maxn], B[Maxn], C[Maxn];

bool Less(const ldld &a, const ldld &b)
{
	if (a.first != b.first) return a.first < b.first;
	return a.second > b.second;
}

ll getInvs(vector <ldld> &seq, int l, int r)
{
	if (l == r) return 0;
	else {
		ll res = 0;
		int m = l + r >> 1;
		vector <ldld> seq1, seq2;
		for (int i = l; i <= m; i++)
			seq1.push_back(seq[i]);
		for (int i = m + 1; i <= r; i++)
			seq2.push_back(seq[i]);
		res += getInvs(seq1, 0, int(seq1.size()) - 1) + getInvs(seq2, 0, int(seq2.size()) - 1);
		seq.clear();
		int i = 0, j = 0;
		while (i < seq1.size() || j < seq2.size())
			if (i < seq1.size() && (j >= seq2.size() || seq1[i].second > seq2[j].second)) seq.push_back(seq1[i++]);
			else { res += int(seq1.size()) - i; seq.push_back(seq2[j++]); }
		return res;
	}
}

ll Solve(vector <ldld> &seq)
{
	sort(seq.begin(), seq.end(), Less);
	return getInvs(seq, 0, int(seq.size()) - 1);
}

ll GetX(ld x)
{
	vector <ldld> seq;
	for (int i = 0; i < n; i++) {
		ld myC = C[i] - x * A[i];
		seq.push_back(ldld(ld(myC) / B[i], -ld(A[i]) / ld(B[i])));
	}
	/*if (x == 0) {
		for (int i = 0; i < seq.size(); i++)
			printf("seq[%d] = (%lld, %lld) %lf\n", i, seq[i].first.first, seq[i].first.second, double(seq[i].second));
		printf("r = %lld, s = %lld\n", res, Solve(seq));
	}*/
	return Solve(seq);
}

ll GetY(ld y)
{
	vector <ldld> seq;
	for (int i = 0; i < n; i++) {
		ld myC = C[i] - y * B[i];
		seq.push_back(ldld(ld(myC) / A[i], -ld(B[i]) / ld(A[i])));
	}
	return Solve(seq);
}

int main()
{
	scanf("%d", &n);
	for (int i = 0; i < n; i++)
		scanf("%d %d %d", &A[i], &B[i], &C[i]);
	ll nd = (ld(n) * (n - 1) / 2 - 1) / 2;
	ld lef = -lim, rig = lim;
	for (int i = 0; i < 80; i++) {
		ld mid = (lef + rig) / 2;
		if (GetX(mid) <= nd) lef = mid;
		else rig = mid; 
	}
	cout << fixed << setprecision(15) << lef << " ";
	lef = -lim, rig = lim;
	for (int i = 0; i < 80; i++) {
