}
point gaisin(point a,point b,point c) {
    return intersection(line(a,b).vertical_bisector(),line(b,c).vertical_bisector());
}
struct circle {
    point o;
    double r;
    inline circle(point o,double r):o(o),r(r) {}
};
vector<point> intersection(circle a,circle b) {
    double d = dist(a.o,b.o);
    if(eq(a.r+b.r,d)) return {a.o+(b.o-a.o)*a.r/d};
    if(eq(a.r-b.r,d)) return {a.o+(b.o-a.o)*a.r/d};
    if(eq(b.r-a.r,d)) return {b.o+(a.o-b.o)*b.r/d};
    if(abs(a.r-b.r)+eps > d || d+eps > a.r+b.r) return {};
    double x = (pow(a.r,2.0)+pow(d,2.0)-pow(b.r,2.0))/(2*d);
    double y = sqrt(pow(a.r,2.0)-pow(x,2.0));
    point p = (b.o-a.o).rot90()*y/d;
    point tomid = a.o+(b.o-a.o)*x/d;
    return {tomid+p,tomid-p};
}

