struct Line {
    ll a, b, c;

    Line () {}
    Line (ll _a, ll _b, ll _c) : a(_a), b(_b), c(_c) {}

    ld val(ld x) {
        return (c - a * x) / b;
    }
};

const int N = 1e5 + 10;
Line ls[N];

struct Cmp {
    Cmp () {}

    bool operator() (const int& x, const int& y) const{
        return (ls[x].a * ls[y].b < ls[x].b * ls[y].a) ^ (ls[x].b < 0) ^ (ls[y].b < 0);
    }
};
using ordered_set = tree<int,null_type,Cmp,rb_tree_tag,tree_order_statistics_node_update>;

ld solve(int n) {
    vector<int> ix(n);
    forn(i, 0, n) ix[i] = i;
    ld l = -1e9, r = 1e9;
    ll cnt = 1ll * n * (n - 1) / 2;
    while (l < r - eps) {
        ld m = (l + r) / 2;
        //cerr << l << ' ' << r  << '\n';
        //cerr << m << ' ';
        auto cmp = [&](int x, int y) {
            return ls[x].val(m) < ls[y].val(m);
        };
        sort(all(ix), cmp);
        ll rgt = 0;
        ordered_set a;
        //cerr << "lines:\n";
        for (int i : ix) {
            //cerr << i << ' ' << a.order_of_key(i) << '\n';
            rgt += a.order_of_key(i);
            a.insert(i);
        }
        if (rgt > cnt / 2) l = m;
        else r = m;
    }
    return (l + r) / 2;
}

