template <typename T> struct BIT {
  private:
    int n;
    vector<T> dat; // 1-indexed

  public:
    BIT(vector<T> v) : n(v.size() - 1) {
        dat = v;
        for(int i = 1; i < n; i++)
            if(i + (i & -i) <= n) dat[i + (i & -i)] += dat[i];
    }
    BIT(int n) : n(n) { dat.assign(n + 1, 0); }
    void add(int k, T a) {
        while(k <= n) {
            dat[k] += a;
            k += k & -k;
        }
    }
    T sum(int a) {
        T ret = 0;
        while(a) {
            ret += dat[a];
            a -= a & -a;
        }
        return ret;
    }
    T sum(int a, int b) { return sum(b) - sum(a - 1); }
    int lowerBound(int w) {
        if(w <= 0) return 0;
        int x = 0;
        for(int k = 1 << int(log2(n)); k; k /= 2) {
            if(x + k <= n && dat[x + k] < w) {
                x += k;
                w -= dat[x];
            }
        }
        return x + 1;
    }
};

struct Line {
    int a, b, c;
};

int n;
vector<Line> vec;

ll x;

bool fx(double mid) {
    vector<double> v;
    for(auto &&d : vec)
        v.push_back((-d.a * mid + d.c) / d.b);
    vector<double> z = v;
    sort(ALL(z));
    BIT<int> bit(n + 10);
    ll cnt = 0;
    for(auto &&d : v) {
        int a = lower_bound(ALL(z), d) - z.begin();
        cnt += a - bit.sum(a + 1);
        bit.add(a + 1, 1);
    }
    return cnt < x;
}

bool fy(double mid) {
    vector<double> v;
    for(auto &&d : vec)
        v.push_back((-d.b * mid + d.c) / d.a);
    vector<double> z = v;
    sort(ALL(z));
    BIT<int> bit(n + 10);
    ll cnt = 0;
    for(auto &&d : v) {
        int a = lower_bound(ALL(z), d) - z.begin();
        cnt += a - bit.sum(a + 1);
        bit.add(a + 1, 1);
    }
    return cnt < x;
}

