template<class T> struct FenwickTree {
  const int n;
  V<T> t;
  FenwickTree(int n) : n(n), t(n + 1) {}
  void add(int i, T x) { for (++i; i <= n; i += i & -i) t[i] += x; }
  T sum(int i) const {
    T s = 0;
    for (; i; i -= i & -i) s += t[i];
    return s;
  }
  T sum(int l, int r) const { return sum(r) - sum(l); }
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int n; cin >> n;
  int m = n * (n - 1) / 2;
  V<double> a(n), b(n), c(n); for (int i = 0; i < n; ++i) cin >> a[i] >> b[i] >> c[i];
  auto fn = [&]() -> double {
    V<> idx(n);
    iota(begin(idx), end(idx), 0);
    sort(begin(idx), end(idx), [&](int i, int j) { return -a[i] / b[i] < -a[j] / b[j]; });
    V<> ord(n);
    for (int i = 0; i < n; ++i) {
      ord[idx[i]] = i;
    }
    auto chk = [&](double x) -> bool {
      sort(begin(idx), end(idx), [&](int i, int j) { return (c[i] - a[i] * x) / b[i] + 1e-10 < (c[j] - a[j] * x) / b[j]; });
      FenwickTree<int> ft(n);
      int k = 0;
      for (int i : idx) {
        k += ft.sum(ord[i]);
        ft.add(ord[i], 1);
      }
      return k >= m + 1 >> 1;
    };
    double ng = -1e10, ok = 1e10;
    for (int _ = 0; _ < 100; ++_) {
      double mid = (ng + ok) / 2;
      (chk(mid) ? ok : ng) = mid;
    }
    return ok;
  };
  cout << fixed << setprecision(15) << fn() << ' ';
  swap(a, b);
  cout << fn() << '\n';
}

