using namespace std;
using pdd = pair<double, double>;

template <typename T, typename F = std::plus<T>>
class fenwick_tree {
public:
	using value_type = T;
private:
	std::vector<T> m_data;
	F m_func;
public:
	fenwick_tree()
		: m_data(1)
		, m_func()
	{ }
	explicit fenwick_tree(
		size_t n,
		const value_type& x = value_type(),
		const F& f = F())
		: m_data(n + 1)
		, m_func(f)
	{
		m_data[0] = value_type();
		for(size_t i = 1; i <= n; ++i){
			m_data[i] = x;
			for(size_t j = i; (j & 1) == 0u; j >>= 1){
				m_data[i] = m_func(m_data[j], m_data[i]);
			}
		}
	}
	size_t size() const {
		return m_data.size() - 1;
	}
	value_type query(size_t i) const {
		value_type s = m_data[i];
		for(i -= i & -i; i > 0; i -= i & -i){
			s = m_func(m_data[i], s);
		}
		return s;
	}
	void modify(size_t i, const value_type& x){
		const auto n = m_data.size();
		for(++i; i < n; i += i & -i){
			m_data[i] = m_func(m_data[i], x);
		}
	}
};

int count_inversion(const std::vector<double>& a){
	const int n = a.size();
	vector<double> b(a);
	sort(b.begin(), b.end());
	b.erase(unique(b.begin(), b.end()), b.end());
	fenwick_tree<int> ft(b.size());
	int answer = 0;
	for(int i = 0; i < n; ++i){
		const int k = lower_bound(b.begin(), b.end(), a[i]) - b.begin();
		answer += i - ft.query(k);
		ft.modify(k, 1);
	}
	return answer;
}

double solve(
	const vector<double>& a,
	const vector<double>& b,
	const vector<double>& c)
{
	const int n = a.size();
	const int nc = n * (n - 1) / 2;
	vector<double> ca(n), ba(n);
	for(int i = 0; i < n; ++i){
		ca[i] = c[i] / a[i];
		ba[i] = b[i] / a[i];
	}
	double ly = -1e9, ry = 1e9;
	for(int iter = 0; iter < 200; ++iter){
		const double y = (ly + ry) * 0.5;
		vector<pdd> v(n);
		for(int i = 0; i < n; ++i){
			const double x = ca[i] - ba[i] * y; //(c[i] - b[i] * y) / a[i];
			const double t = -ba[i]; //-b[i] / a[i];
			v[i] = pdd(x, t);
		}
		sort(v.begin(), v.end());
		vector<double> w(n);
		for(int i = 0; i < n; ++i){ w[i] = v[i].second; }
		const int inv = count_inversion(w);
		if(inv > nc / 2){
			ly = y;
		}else{
			ry = y;
		}
	}
	return ly;
}

int main(){
	ios_base::sync_with_stdio(false);
	cout << setiosflags(ios::fixed) << setprecision(10);
	int n;
	cin >> n;
	vector<double> a(n), b(n), c(n);
	for(int i = 0; i < n; ++i){
		cin >> a[i] >> b[i] >> c[i];
	}
	const double y = solve(a, b, c);
	const double x = solve(b, a, c);
	cout << x << " " << y << endl;
	return 0;
}

