int get(int r)
{
    int res = 0;
    for (; r >= 0; r = (r & (r+1)) - 1)
		res += tree[r];
	return res;
}

void add(int p)
{
    for (; p < n; p = (p | (p + 1)))
		tree[p]++;
}

int calc(vector<int> perm)
{
    vector<int> pos(perm.size());
    for (int i = 0; i < perm.size(); i++)
    {
        pos[perm[i]] = i;
    }
    fill(tree, tree + perm.size(), 0);
    int res = 0;
    for (int i = pos.size() - 1; i >= 0; i--)
    {
        res += get(pos[i] - 1);
        add(pos[i]);
    }
    return res;
}

