    for (int i = 0; i < n; i++)
    {
        double xs = -1e9;
        double xf = X;
        double ys = (c[i] - a[i] * xs) / b[i];
        double yf = (c[i] - a[i] * xf) / b[i];
        s.push_back({ys, i});
        f.push_back({yf, i});
