        f.push_back({yf, i});
    }
    vector<int> pos(n);
    sort(all(s));
    sort(all(f));
    for (int i = 0; i < n; i++) pos[s[i].second] = i;
    vector<int> perm;
    for (int i = 0; i < n; i++)
    {
        int ps = pos[f[i].second];
        perm.push_back(ps);
    }
    return calc(perm);
}

