template< class T >
struct BinaryIndexedTree
{
	vector< T > data;

	BinaryIndexedTree(int sz)
	{
		data.assign(++sz, 0);
	}

	void init()
	{
		for (T& t : data)t = T();
	}

	T sum(int k)
	{
		T ret = 0;
		for (; k > 0; k -= k & -k) ret += data[k];
		return (ret);
	}

	void add(int k, T x)
	{
		for (++k; k < data.size(); k += k & -k) data[k] += x;
	}
};


struct line
{
	LL A, B, C;
};


const LD EPS = 1e-11;
vector<line>plane;
LL getDrop(LD X, BinaryIndexedTree<LL>& bit)
{
	bit.init();
	vector<pair<LD, int>>cash;
	for (int i = 0; i < N; ++i)
	{
		const auto& lin = plane[i];
		LD Y = lin.C - lin.A * X;
		Y /= lin.B;
		cash.push_back({ Y,i });
	}
	sort(cash.rbegin(), cash.rend());
	LL ret = 0;
	for (int i = 0; i < N; ++i)
	{
		ret += bit.sum(cash[i].second);
		bit.add(cash[i].second, 1);
	}
	return ret;
}
LD getMedian()
{
	BinaryIndexedTree<LL>bit(N);
	LD lo = -1e12, hi = 1e12;
	while (hi - lo > EPS)
	{
		LD mid = (lo + hi) / 2;
		LL res = getDrop(mid, bit);
		if (res * 2 < M)
		{
			lo = mid;
		}
		else
		{
			hi = mid;
		}
	}
	return hi;
}

