const int MAXN = 100005;

struct Line
{
	long double k, b;
	bool operator < (const Line &b) const { return k < b.k; }
} l[MAXN];

int n, A[MAXN], B[MAXN], C[MAXN];
long double d[MAXN], e[MAXN];
LL lim, ans;

inline void Solve(int l, int r)
{
	if (l == r)
		return ;
	int mid = l + r >> 1, ql = l, qr = mid + 1, cur = l;
	Solve(l, mid), Solve(mid + 1, r);
	while (ql <= mid && qr <= r)
		if (d[ql] < d[qr])
			e[cur ++] = d[ql ++], ans += r - qr + 1;
		else
			e[cur ++] = d[qr ++];
	while (ql <= mid)
		e[cur ++] = d[ql ++];
	while (qr <= r)
		e[cur ++] = d[qr ++];
	for (int i = l; i <= r; i ++)
		d[i] = e[i];
}

inline bool Chk(long double x)
{
	for (int i = 1; i <= n; i ++)
		d[i] = l[i].k * x + l[i].b;
	ans = 0;
	Solve(1, n);
	return ans >= lim;
}

