int get(int x) {
    int res = 0;
    while (x >= 0) {
        res += bit[x];
        x -= ~x & (x + 1);
    }
    return res;
}

void update(int x, int delta) {
    while (x < bitsize) {
        bit[x] += delta;
        x |= x + 1;
    }
}

