            P[++nr].y=(V[i].a*V[j].c-V[j].a*V[i].c)/(V[j].a*V[i].b-V[i].a*V[j].b);
            P[nr].x=(V[j].c*V[i].b-V[i].c*V[j].b)/(V[i].a*V[j].b-V[j].a*V[i].b);
        }
    }
    N=nr;
    punct a={0,0};
    sort(P+1,P+1+N,cmp1);
    a.x=P[N/2+N%2].x;
    sort(P+1,P+1+N,cmp2);
    a.y=P[N/2+N%2].y;
    cout<<fixed<<setprecision(10)<<a.x<<" "<<a.y;
    return 0;
}

