// How many ints in the left side of X = x?
LL Count(double x) {
	LL total = 0;

	vector<pair<double, int>> V;
	for (int i = 0; i < N; i++) {
		double d = L[i].retCompute(x);
		V.push_back({ d, i });
	}

	sort(V.begin(), V.end(), cmp);
	for (int i = N - 1; i >= 0; i--) {
		total += read(V[i].second + 1);
		update(V[i].second + 1, 1);
	}
	for (int i = 0; i < N; i++) {
		update(V[i].second + 1, -1);
	}
	return total;
}

