struct BIT{
  ll M=1;
  vector<ll> dat;
  BIT(ll N){
    while(N>M) M*=2;
    dat.resize(M*2-1, 0);
  }
  void update(ll x, ll k){
    for(int i=k+1;i<=M;i+=(i&(-i))){
      dat[i] += x;
    }
  }
  ll sum(ll r){
    ll ret = 0;
    for(int k=r;k>0;k-=(k&(-k))) ret += dat[k];
    return ret;
  }

  ll query(ll l, ll r){
    return sum(r) - sum(l);
  }
};

ll n;

ld calc(vvl d){
  sort(all(d), [](vll a, vll b){
    return fraction(-a[0], a[1]) < fraction(-b[0], b[1]);
  });

  //for(int i=0;i<n;i++) println(fraction(-d[i][0], d[i][1]));
  ll inter = (n*(n-1))/2;

  //check x
  ld l = -100000, r = 100000;
  for(int i=0;i<200;i++){
    ld mid = (l+r)/2;
    ll ret = 0;
    BIT bt(n+1);

    map<ld, ll> mp;
    vector<ld> C(n, 0);

    for(int j=0;j<n;j++) {
      ld a = d[j][0], b = d[j][1], c = d[j][2];
      C[j] = (-a*mid+c)/b;
      mp.emplace(C[j], 0);
    }

    ll cnt = 0;
    for(auto itr = mp.begin();itr!=mp.end();itr++, cnt++) (*itr).second = cnt;

    for(int j=0;j<n;j++){
      ll num = mp.at(C[j]);
      ret += bt.query(0, num+1);
      bt.update(1, num);
    }
    if(ret >= (inter/2 + inter%2)) r = mid;
    else l = mid;
  }

  return r;
}

