	for( int i = 0; i < n; ++i ) {
		rcnt += BIT::sum( k[tmp[i]], n );
		lcnt += BIT::sum( 1, k[tmp[i]] );
		BIT::add( k[tmp[i]] );
	}
}
double solvey() {
	ll half = (ll)n*(n-1)/2;
	half = (half>>1) + (half&1);
	double low = -1e9, high = 1e9;
	while( dcmp(high-low) ) {
		double mid = (low+high)/2;
		ll lcnt, rcnt;
		checky(mid, lcnt, rcnt);
		if( lcnt >= half ) high = mid;
		else low = mid;
	}
	return low;
}

bool cmpkx( int i, int j ) {
