        std::vector<int> ind(N);
        std::iota(ind.begin(), ind.end(), 0);
        std::sort(ind.begin(), ind.end(), [&](const int i, const int j) { return (C[i] - A[i] * inf) / B[i] < (C[j] - A[j] * inf) / B[j]; });
