	}

	void init()
	{
		for (T& t : data)t = T();
	}

	T sum(int k)
	{
		T ret = 0;
		for (; k > 0; k -= k & -k) ret += data[k];
		return (ret);
	}

	void add(int k, T x)
	{
		for (++k; k < data.size(); k += k & -k) data[k] += x;
	}
};


