int doubleComp(double a, double b){
	double d = b - a;
	double r = EPS * max(abs(a), abs(b));
	if(abs(d) < r) return 0;
	return d>0 ? 1 : -1;
}

bool secondComp(DI a, DI b){
	return a.second < b.second;
}

bool revComp(DI a, DI b){
	// a.first < b.first
	int dc = doubleComp(a.first, b.first);
	if(dc == 0) return a.second > b.second; // if equal, reverse
	return dc==1;
}

// 分割統治で求める
int mergeCount(vector<DI> &v, int b, int e){
	if(e-b==1)return 0;
	int m = (e+b)/2;
	int l = mergeCount(v, b, m);
	int r = mergeCount(v, m, e);

	int res = l + r;
	int last = 0;
	vector<DI> narr;
	FOR(i, b, m){
		int f = lower_bound(v.begin() + m, v.begin() + e, v[i], secondComp)
					- v.begin() - m;
		res += (f - last)*(m-i);
		narr.insert(narr.end(), v.begin() + m + last, v.begin() + m + f);
		last = f;
		narr.PB(v[i]);
	}
	narr.insert(narr.end(), v.begin() + m + last, v.begin() + e);

	FOR(i, b, e){
		v[i] = narr[i - b];
	}

	return res;
}

