void update(int pos){
	for(int i=pos;i<=n;i+=i&(-i)) bit[i]++;
}
int get(int pos){
	int ret=0;
	for(int i=pos;i>=1;i-=i&-(i)) ret+=bit[i];
	return ret;
}
bool cmp(int x,int y){
	return ((-a[x]/b[x]<-a[y]/b[y]) || (-a[x]/b[x]==-a[y]/b[y] && c[x]/b[x]>c[y]/b[y]));
}
bool cmp2(int x,int y){
	return ((sv[x]>sv[y]) || (sv[x]==sv[y] && x>y));
}
double solve(){
	for(int i=1;i<=n;i++) id[i]=i;
	sort(id+1,id+1+n,cmp);
	//for(int i=1;i<=n;i++) cout<<id[i]<<"\n";
	double l=-1e9,r=1e9;
	double mid=(l+r)/2.0;
	for(int t=1;t<=90;t++){
		for(int i=1;i<=n;i++){
			int x=id[i];
			idx[i]=i;
			bit[i]=0;
			sv[i]=(-a[x]/b[x])*mid+c[x]/b[x];
		}
		sort(idx+1,idx+1+n,cmp2);
		int cur=0;
		for(int i=1;i<=n;i++){
			cur+=(i-1)-get(idx[i]);
			update(idx[i]);
		}
		//cout<<cur<<endl;
		if(cur<=n*(n-1)/2/2) l=mid;
		else r=mid;
		mid=(l+r)/2.0;
	}
	return mid;
}
