  auto fn = [&]() -> double {
    V<> idx(n);
    iota(begin(idx), end(idx), 0);
    sort(begin(idx), end(idx), [&](int i, int j) { return -a[i] / b[i] < -a[j] / b[j]; });
    V<> ord(n);
    for (int i = 0; i < n; ++i) {
      ord[idx[i]] = i;
