	X.clear();
	Y.clear();
	k.clear();
	FOR (i, N) {
		X.pb(A[i]);
		Y.pb(B[i]);
		k.pb(C[i]);
	}

	printf("%.10lf ", solve(X, Y, k));
	printf("%.10lf\n", solve(Y, X, k));
	return 0;
}

