    }
};
inline bool cmp1 (line &n1, line &n2) {
    return n1.slope() > n2.slope();
}
inline bool cmp2 (line &n1, line &n2) {
    return n1.slope() < n2.slope();
}
vector <line> AL;
int N;
double K;
int bit[MAXN];
void update(int x, int v) {
    for (int a = x; a <= N; a += (a & -a))
        bit[a] += v;
}
int query(int x) {
    int sum = 0;
    for (int a = x; a > 0; a -= (a & -a))
        sum += bit[a];
    return sum;
}
set <double> inter;
double seq[MAXN];
int P[MAXN];
unordered_map <double, int> MP;
int cnt;
double findans(int mode) {
    double left = -INF, rght = INF;
    if (!mode) {
        sort(AL.begin(), AL.end(), cmp2);
    } else {
        for (auto &i : AL) {
            swap(i.a, i.b);
        }
        sort(AL.begin(), AL.end(), cmp2);
    }
    while (fabs(rght - left) > EPS) {
        cnt = 1;
//        memset(bit, 0, sizeof bit);
        for (int i = 0; i <= N; i++)
            bit[i] = 0;
        inter.clear();
        MP.clear();
        double mid = (rght + left) / 2;
        for (line i : AL) {
            double a = i.gety(mid);
            inter.insert(a);
            seq[cnt++] = a;
        }
        cnt = 1;
        for (auto i : inter) {
            MP[i] = cnt++;
        }
        for (int i = 1; i <= N; i++) {
            P[i] = MP[seq[i]];
        }
        cnt = 0;
        for (int i = 1; i <= N; i++) {
            cnt += query(P[i]);
            update(P[i], 1);
        }
        if (cnt < K / 2.0) {
            left = mid + EPS;
        } else {
            rght = mid - EPS;
        }
    }
    return left;
}
