	  return (c[i]-a[i]*x)*b[j] < (c[j]-a[j]*x)*b[i];
	return (c[i]-a[i]*x)*b[j] > (c[j]-a[j]*x)*b[i];});
    //    for(int i:ind)out(i,a[i],b[i],c[i],(c[i]-a[i]*x)/b[i],1);
    SET<double> st;
    ll cnt=0;
