            int p2 =   ln2.c * ln1.a- ln2.a * ln1.c;
            int bias = ln1.a*ln2.a;
            double ans = p1*x - p2;
            if (abs(ans)<EPS) return l1.second > l2.second;

            return bias > 0 ? ans < -EPS : ans > EPS;
        });
        int sect = 0;
        rep (i, 0, n) {
            int id = nums[i].second;
            update(tree, id + 1, 1);
            int inter = read(tree, id + 1);
            sect += i + 1 - inter;

        }
        if (sect >= median) {
            r = x;
        } else {
            l = x;
        }

    }
    cout << setprecision(15) << l << " ";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int tree[2 * 40005];
template <class T>
struct Segtree {
  // vector<T> tree;
  int n;
  Segtree() = default;
  Segtree(int N) {
    n = N;
    memset(tree, 0, sizeof(int) * 2 * n);
  }
  void update(int i, T val) {
    int p = i + n;
    const T diff = val - tree[p];
    while (p) {
      tree[p] += diff;
      p /= 2;
    }
  }

  T query(int start, int end) {
    int l = n + start;
    int r = n + end - 1;
    T ret = 0;
    while (l <= r) {
      if (l & 1) {
        ret += tree[l];
        l++;
      }

      if ((r & 1) == 0) {
        ret += tree[r];
        r--;
      }
      l /= 2;
      r /= 2;
    }
    return ret;
  }
};
constexpr double eps = numeric_limits<double>::epsilon();
int gcd(int a, int b) {
  while (b) {
    int tmp = b;
    b = a % b;
    a = tmp;
  }
  return a < 0 ? -a : a;
}

int N;
int A[40005];
int B[40005];
int C[40005];
int rank2[40005];
int rank3[40005];

pair<double, int> kp[40005];
pair<double, int> xp[40005];

int countRev() {
  Segtree<int> st = Segtree<int>(N);
  int ret = 0;
  int *v = rank3;
  for (int i = 0; i < N; ++i) {
    const int c = v[i];
    st.update(c, 1);
    ret += st.query(c + 1, N);
  }

  return ret;
}
int countSmall(double x) {
  // calc point
  for (int i = 0; i < N; ++i) {
    xp[i].first = (C[i] - double(A[i]) * x) / B[i];
    xp[i].second = i;
  }

  sort(xp, xp + N);
  for (int i = 0; i < N; ++i) {
    rank2[xp[i].second] = i;
  }

  for (int i = 0; i < N; ++i) {
    rank3[rank2[kp[i].second]] = i;
  }

  return countRev();
}

double sol() {
  for (int i = 0; i < N; ++i) {
    kp[i].first = 1.0 * A[i] / B[i];
    kp[i].second = i;
  }

  // cout << endl;
  sort(kp, kp + N);
  double l = -1E9;
  double r = 1E9;
  double ret = r;
  const int k = (N * (N - 1) / 2 + 1) / 2;
  while (1) {
    double x = l + (r - l) / 2;
    // cout << "x: " << x << "  =========" << endl;
    if (countSmall(x) >= k) {
      ret = x;
      r = x - eps;
    } else {
      l = x + eps;
    }

    double diff = r - l;
    if (diff < 1E-9 || abs(diff / l) < 1E-9) break;
  }
  return ret;
}
int main() {
  // // cout << countRev({4, 3, 2, 1, 0}) << endl;
  ios::sync_with_stdio(false);
  cin >> N;
  for (int i = 0; i < N; ++i) {
    cin >> A[i] >> B[i] >> C[i];
    int g = gcd(A[i], B[i]);
    if (C[i]) g = gcd(g, C[i]);
    A[i] /= g;
    B[i] /= g;
    C[i] /= g;
  }
  double x = sol();
  for (int i = 0; i < N; ++i) {
    swap(A[i], B[i]);
  }
  double y = sol();
  cout << setprecision(11) << fixed << x << ' ' << setprecision(11) << fixed
       << y << endl;
}

