#include <bits/stdc++.h>
using namespace std;

struct BIT {
    long long n;
    vector<long long> dat;

    void initialize(long long n_input){
        n = n_input + 1;
        dat.resize(n+1);
        for(int i = 0; i<=n; i++) dat[i] = 0;
    }

    long long sum(long long i){
        long long s = 0;
        while(i >= 0){
            s += dat[i];
            i = (i & (i+1)) - 1;
        }
        return s;
    }

    void add(long long i, long long x){
        while(i <= n){
            dat[i] += x;
            i |= i+1;
        }
    }
};

int inversion(const vector<int> arr){
    BIT bit;
    bit.initialize(arr.size());
    int ret = 0;
    for(int i=0; i<arr.size(); i++){
        ret += i - bit.sum(arr[i]);
        bit.add(arr[i], 1);
    }
    return ret;
}

