Int cntbit(Int x){
	x++;
	Int res = 0;
	while(x){
		res += bit[x];
		x -= x & -x;
	}
	return res;
}

void addbit(Int x){
	x++;
	while(x < 108000){
		bit[x]++;
		x += x & -x;
	}
}

Int cnt(double p){
	vector<double>poInts;
	vector<double> query;
	for(Int i = 0;i < n;i++){
		bit[i+1] = 0;
		double a = lines[i].first;
		double b = lines[i].second.first;
		double c = lines[i].second.second;
		double y0 = (c - a*p) / b;
		poInts.push_back(y0);
