	}
	sort(poInts.begin(), poInts.end());
	poInts.erase(unique(poInts.begin(), poInts.end()), poInts.end());
	Int res = 0;
	for(Int i = 0;i < n;i++){
		Int pos = lower_bound(poInts.begin(), poInts.end(), query[i]) - poInts.begin();
		res += cntbit(pos);
		addbit(pos);
	}
	return res;
}

