}

int count_left(vector<line>& v, double x){
    int cnt = 0;
    vector<pair<double,int>> vec;
    vec.reserve(v.size());
    for(auto& l : v)
        vec.emplace_back(intersect(l,x), cnt++);
    sort(ALL(vec));
    fenwick f(v.size());
    int ans = 0;
    for(auto& p : vec){
        ans += f.sum(p.second);
        f.add(p.second, 1);
    }
    return ans;
}

