class BIT{
    //index : 1-based
    public:
        vector<ll> bit;
        ll M;

        BIT(ll M):
            bit(vector<ll>(M + 1, 0)), M(M) {}
        ll sum(ll i){
            if (!i) return 0;
            return bit[i] + sum(i - (i & -i));
        }

        void add(ll i, ll x){
            if (i > M) return;
            bit[i] += x;
            add(i + (i & -i), x);
        }
};  

ll inversion(vector<double> x){
    //vector xの転倒数を求める
    BIT t(N);
    vector<pair<double, ll>> y;
    ll ans = 0;
    REP(i, x.size()){
        y.pb(mp(x[i], i));        
    }
    SORT(y);
    REP(i, x.size()){
        ans += y[i].second - t.sum(y[i].second + 1);
        t.add(y[i].second + 1, 1);
    }
    return ans;
}

ll search_x(double x){
    vector<pair<double, double>> ys;
    REP(i, N){
        ys.pb(mp(-A[i] / B[i], (C[i] - A[i] * x) / B[i]));
    }
    SORT(ys);
    vector<double> y;
    REP(i, N){
        y.pb(ys[i].second);
    }
    return inversion(y);
}

ll search_y(double y){
    vector<pair<double, double>> xs;
    REP(i, N){
        xs.pb(mp(-B[i] / A[i], (C[i] - B[i] * y) / A[i]));
    }
    SORT(xs);
    vector<double> x;
    REP(i, N){
        x.pb(xs[i].second);
    }
    return inversion(x);
}


