const int N = 4e4 + 5;
const double eps = 1e-10;
int n, a[N], b[N], c[N];
map<double, int> id;

struct Line {
    double A, B;
    Line(double A = 0, double B = 0) : A(A), B(B) {}
    bool operator< (const Line& rhs) const { return A == rhs.A ? B < rhs.B : A < rhs.A; }
} line[2][N];

struct Bit {
    int a[N];
    Bit() { memset(a, 0, sizeof a); }
    void update(int pos, int val) {
        for (; pos < N; pos += pos & -pos) a[pos] += val;
    }
    int get(int pos) {
        int ret = 0;
        for (; pos > 0; pos -= pos & -pos) ret += a[pos];
        return ret;
    }
} bit;

void solve(bool type) {
    sort(line[type] + 1, line[type] + n + 1);
    double l = -1e9, r = 1e9;
    while(r - l > eps) {
        double mid = (l + r) / 2;
        id.clear();
        for (int i = 1; i <= n; ++i) id[mid * line[type][i].A + line[type][i].B];
        int curId = 0;
        for (auto i : id) id[i.fi] = ++curId;
        bit = Bit();
        int cnt = 0;
        for (int i = 1; i <= n; ++i) {
            cnt += bit.get(id[mid * line[type][i].A + line[type][i].B]);
            bit.update(id[mid * line[type][i].A + line[type][i].B], 1);
        }
        int nn = n * (n - 1) / 2;
        if(cnt >= (nn + 1) / 2) r = mid;
        else l = mid;
    }
    cout << fixed << setprecision(15) << l;
}

