inline bool cmpx(const Line& u, const Line &v){
	return double(u.A) / u.B > double(v.A) / v.B;
}

inline bool cmpy(const Line& u, const Line &v){
	return double(u.B) / u.A > double(v.B) / v.A;
}

long double P, val[N];

inline bool cmp(int u, int v){
	return val[u] < val[v];
}

