int c[N];

inline int lowbit(int x){
	return x & (-x);
}

inline void add(int x){
	while(x <= n){
		c[x]++;
		x += lowbit(x);
	}
}

inline int sum(int x){
	int ret = 0;
	while(x){
		ret += c[x];
		x -= lowbit(x);
	}
	return ret;
}

bool checkx(double x){
	P = x;
	For(i, 1, n) val[i] = (L[i].C - P * L[i].A) / L[i].B, rk[i] = i, c[i] = 0;
	sort(rk + 1, rk + n + 1, cmp);
	long long ret = 0;
	Forr(i, n, 1) ret += sum(rk[i]), add(rk[i]);
	return ret * 4 <= 1LL * n * (n - 1);
}

bool checky(double x){
	P = x;
	For(i, 1, n) val[i] = (L[i].C - P * L[i].B) / L[i].A, rk[i] = i, c[i] = 0;
	sort(rk + 1, rk + n + 1, cmp);
	long long ret = 0;
	Forr(i, n, 1) ret += sum(rk[i]), add(rk[i]);
	return ret * 4 <= 1LL * n * (n - 1);
}

