const int N = 40005;
const long double eps = 1e-12;

bool eq(long double a, long double b) { return abs(a - b) <= eps; }

struct line {
	long double a; long double b; long double c; // ax + by = c
	line(long double a = 0.0, long double b = 0.0, long double c = 0.0):
		a(a), b (b), c(c) {}
	long double intersectY(line d) {
		long double inter = (long double)(d.c * a - c * d.a) / (d.b * a - b * d.a);
		if (eq(inter, 0.0)) return 0.0; return inter;
	}
	bool operator < (const line &d) { return a / b > d.a / d.b; }
} l[N];

int n;
long long tot;

int T[N];
void upd(int x) { for (; x < N; x += x & -x) T[x]++; } 
int get(int x) { int res = 0; for (; x > 0; x -= x & -x) res += T[x]; return res; }

long long check(double val) {
	line med = {1, 0, val};
	vector< pair<long double, int> > coor;
	for (int i = 1; i <= n; ++i) {
		coor.push_back(make_pair(med.intersectY(l[i]), i));
	}
	sort(coor.begin(), coor.end());
	memset(T, 0, sizeof T);

	long long ans = 0;
	for (auto &cur : coor) {
		int pos = cur.second; ans += get(pos); upd(pos);
	}
	return ans;
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	cin >> n;
	tot = 1LL * n * (n - 1) / 2;
