	}
	double X = lo;

	// find Y
	for (int i = 1; i <= n; ++i) l[i] = line(-l[i].b, l[i].a, l[i].c);
	sort(l + 1, l + n + 1);
	lo = -1e9, hi = 1e9;
	for (int i = 1; i <= 70; ++i) {
		long double mid = (lo + hi) * 0.5;
