            auto p = crs(a[i], b[i], c[i], a[j], b[j], c[j]);

            x.push_back(p.first);
            y.push_back(p.second);
        }

    SORT(x);
    SORT(y);

    cout << setprecision(20) << x[x.size() / 2 - (1 - x.size() % 2)] << " " << y[y.size() / 2 - (1 - y.size() % 2)] << endl;

    return 0;
}

