P solve() {
    xs.clear();
    ys.clear();
    rep(i, n) rep(j, i) {
        ld x, y;
        if ((a[i] == 0 && a[j] == 0) || (b[i] == 0 && b[j] == 0)) {
            x = y = 0;
        } else {
            ld xu = det(c[i], b[i], c[j], b[j]);
            ld xd = det(a[i], b[i], a[j], b[j]);
            ld yu = det(a[i], c[i], a[j], c[j]);
            ld yd = det(a[i], b[i], a[j], b[j]);
            x = xu / xd;
            y = yu / yd;
        }
        xs.push_back(x);
        ys.push_back(y);
    }

    int m = xs.size();
    sort(all(xs));
    sort(all(ys));

    return P(xs[(m-1) / 2], ys[(m-1) / 2]);
}

