double INF = 100000000000000;
long long inversion_number(vector<int> p){
  int N = p.size();
  long long ans = 0;
  vector<int> BIT(N + 1, 0);
  for (int i = 0; i < N; i++){
    ans += i;
    int x;
    x = p[i] + 1;
    while (x > 0){
      ans -= BIT[x];
      x -= x & -x;
    }
    x = p[i] + 1;
    while (x <= N){
      BIT[x]++;
      x += x & -x;
    }
  }
  return ans;
}
long long inversion_count(vector<int> A, vector<int> B){
  int N = A.size();
  vector<int> p(N);
  for (int i = 0; i < N; i++){
    p[A[i]] = i;
  }
  for (int i = 0; i < N; i++){
    B[i] = p[B[i]];
  }
  return inversion_number(B);
}
