struct AIB {
    int aib[100 * 1000 + 5];
    int n;

    AIB(int n) {
        this->n = n;
        memset(aib, 0, sizeof(aib));
    }

    void insert(int val) {
        while(val <= n) {
            aib[val] += 1;
            val += (val & (-val));
        }
    }

    int count(int val) {
        int ans = 0;
        while(val > 0) {
            ans += aib[val];
            val -= (val & (-val));
        }   
        return ans;
    }
};

vector<int> getOrder(vector<int> a, vector<int> b, vector<int> c, double x) {
    int n = a.size();
    vector<double> y(n, 0);

    for(int i = 0; i < n; ++i) {
        y[i] = (-c[i] - a[i] * x + 0.0) / b[i];
    }   

    vector<int> p;
    for(int i = 0; i < n; ++i)
        p.push_back(i);

    sort(p.begin(), p.end(), [&] (int a, int b) {
        return y[a] < y[b];
    });

    return p;
}

long long getInversions(vector<int> a, vector<int> p) {
    vector<int> aa = a;
    int n = a.size();
    vector<int> place(n, 0);
    for(int i = 0; i < n; ++i) {
        place[p[i]] = i;
    }
    for(int i = 0; i < n; ++i) {
        aa[i] = place[a[i]];
    }

    AIB T(n + 1);
    long long ans = 0;

    for(int i = 0; i < n; ++i) {
        ans += i - T.count(aa[i] + 1);
        T.insert(aa[i] + 1);
    }

    return ans;
}

