    for(int it = 0; it < 2; ++it) {
        double ans = 0, lf = -1e9, rt = 1e9, mid = 0;
        for(int cnt = 0; cnt < 85; ++cnt) {
            mid = (lf + rt) * 0.5;
            auto now = getOrder(a, b, c, mid);
            long long many = getInversions(now, original);
            if(many <= total / 2) {
                ans = mid;
                lf = mid;
            } else {
                rt = mid;
            }
        }
        cout << -ans << " ";
        for(int i = 0; i < n; ++i) {
            swap(a[i], b[i]);
        }
        original = getOrder(a, b, c, -1e11);
    }
}

