struct idn
{
	double val;
	int typ, t;
};

class cp
{
public:
	inline bool operator() (const idn &a, const idn &b) const
	{
		return a.val > b.val;
	}
};

priority_queue<idn, vector<idn>, cp> pq;

int cnt[2];
pair<double, int> h[100001];
int pos[100001];
int tree[2][100001];

inline int get(int typ, int x)
{
	int ret = 0;
	for (; x <= n; x += x&-x) ret += tree[typ][x];
	return ret;
}

inline void update(int typ, int x, int val)
{
	for (; x; x -= x&-x) tree[typ][x] += val;
}

inline long long checkx(double x)
{
	long long ret = 0;
	for (int i = 1; i <= n; i++)
	{
		double L = (1e18*a[i] + c[i]) / b[i], R = (-x*a[i] + c[i]) / b[i];
		comp[i] = { min(L,R),max(L,R),L < R };
	}
	sort(comp + 1, comp + n + 1);
	for (int i = 1; i <= n; i++)
		h[i] = { comp[i].r,i };
	sort(h + 1, h + n + 1);
	for (int i = 1; i <= n; i++)
		pos[h[i].second] = i;
	while (!pq.empty()) pq.pop();
	cnt[0] = cnt[1] = 0;
	memset(tree, 0, sizeof tree);
	for (int i = 1; i <= n; i++)
	{
		while (!pq.empty() && comp[i].l - pq.top().val > 1e-15)
		{
			cnt[pq.top().typ]--;
			update(pq.top().typ, pq.top().t, -1);
			pq.pop();
		}
		ret += cnt[!comp[i].typ];
		int t = pos[i];
		ret += get(comp[i].typ, t);
		update(comp[i].typ, t, 1);
		pq.push({ comp[i].r,comp[i].typ,t });
		cnt[comp[i].typ]++;
	}
	return ret;
}

inline long long checky(double x)
{
