using namespace std;
using LL = long long;
using LD = long double;

LL N;
LL M;

template<typename T>
class BIT {
private:
	vector<T>arr;
	int siz;
public:
	BIT(int n) :siz(1) {
		while (siz < n)siz *= 2;
		arr.resize(siz + 1);
	}
	//[0,x)までの和を取得する
	T query(int x) {
		T s = 0;
		while (x > 0) {
			s += arr[x];
			x -= (x & -x);
		}
		return s;
	}
	//xに値kを加算する
	void add(int x, const T& k) {
		++x;
		while (x <= siz) {
			arr[x] += k;
			x += (x & -x);
		}
	}
};
#define BinaryIndexedTree BIT


struct line
{
	LL A, B, C;
};


const LD EPS = 1e-9;
vector<line>plane;

LL getDrop(LD X, BinaryIndexedTree<LL>& bit)
{
	vector<pair<LD, int>>cash;
	for (int i = 0; i < N; ++i)
	{
		const auto& lin = plane[i];
		LD Y = lin.C - lin.A * X;
		Y /= lin.B;
		cash.push_back({ Y,i });
	}
	sort(cash.rbegin(), cash.rend());
	LL ret = 0;
	for (int i = 0; i < N; ++i)
	{
		ret += bit.query(cash[i].second);
		bit.add(cash[i].second, 1);
	}
	return ret;
}
LD getMedian()
{
	LD lo = -1e10, hi = 1e10;
	while (hi - lo > EPS)
	{
		BinaryIndexedTree<LL>bit(N);
		LD mid = (lo + hi) / 2;
		LL res = getDrop(mid, bit);
		if (res * 2 < M)
		{
			lo = mid;
		}
		else
		{
			hi = mid;
		}
	}
	return hi;
}

int main(void)
{
	cin >> N;
	M = (N - 1) * (N) / 2;
	for (int i = 0; i < N; ++i)
	{
		int a, b, c;
		cin >> a >> b >> c;
		plane.push_back({ a,b,c });
	}
	sort(plane.begin(), plane.end(), [](const line& l1, const line& l2)
	{
		return (LD)l1.A / l1.B < (LD)l2.A / l2.B;
	});
	LD xMedian = getMedian();
	for (int i = 0; i < N; ++i)
	{
		swap(plane[i].A, plane[i].B);
	}
	sort(plane.begin(), plane.end(), [](const line& l1, const line& l2)
	{
		return (LD)l1.A / l1.B < (LD)l2.A / l2.B;
	});
	LD yMedian = getMedian();
	cout.precision(15);
	cout << xMedian << " " << yMedian << endl;
	return 0;
}

