struct bit {
    vector<ll> v; // 部分和をbitで管理 仮想配列はa[1...n]
    bit(int n){ // bit(int n) : v(n + 1) {}
        v.resize(n + 1);
    }

    ll sum(int i){ // 仮想配列a[1]~a[i]の和を求める
        ll ret = 0;
        for(; i > 0; i -= i & -i){ // i & -i: iの1が立っている最高位bitをの2^を返す
            ret += v[i];
        }
        return ret;
    }

    void add(int i, ll w) { // index:iにwを加える
        for (; i < v.size(); i += i & -i) {
            v[i] += w;
        }
    }
};

ll swaps(vector<int> &A){
    int N = (int)A.size();
    bit B(N);

    ll ans = 0;
    rep(i, N){
        ans += i - B.sum(A[i]);
        B.add(A[i], 1);
    }
    return ans;
}

ll swapss(vector<int> &A, vector<int> &C) {
    map<int, int> M;
    int N = (int)A.size();
    rep(i, N){
        M[A[i]] = i + 1;
    }
    vector<int> AA(N);
    rep(i, C.size()){
        AA[i] = M[C[i]];
    }
    return swaps(AA);
}

