    ([&]{
      std::sort(L, L + N, [&](line l, line m){
        return l.val(md) < m.val(md);
      });
      fenwick_tree<int> fen(N);
      int now = 0;
      rep (i, N) {
        now += fen.get(L[i].id);
        fen.modify(L[i].id, 1);
      }
      return now >= count;
    }() ? ok : ng) = md;
  }
  return ok;
}

void sort() {
