struct Line {
    int a, b, c, rank;
    Line(int a, int b, int c) : a(a), b(b), c(c) {}
    double eval(double x) { return -(a * x + c) / b; }
};

double search(vector<Line> &lines) {
    double lb = -1e9, ub = 1e9;
    const int n = lines.size();
    sort(lines.begin(), lines.end(), [](Line lhs, Line rhs) {
            return lhs.b * rhs.a < lhs.a * rhs.b;
        });
    for (int i = 0; i < n; i++) lines[i].rank = i + 1;
    while (ub - lb > 1e-10 && (ub - lb) / max(abs(lb), abs(ub)) > 1e-10) {
        double m = (ub + lb) / 2;
        sort(lines.begin(), lines.end(), [m](Line lhs, Line rhs) {
                return lhs.eval(m) < rhs.eval(m);
            });
        int bit[n+2];
        fill(bit, bit+n+2, 0);
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            Line l = lines[i];
            for (int j = l.rank; j > 0; j -= j&-j) cnt += bit[j];
            for (int j = l.rank; j <= n; j += j&-j) bit[j]++;
        }
        // cerr << m << " " << cnt << endl;
        if (cnt * 2LL >= n * (n - 1) / 2) ub = m;
        else lb = m;
    }
    return (ub + lb) / 2;
}

pair<double, double> bruteforce(vector<Line> &lines) {
    const int n = lines.size();
    vector<double> xs, ys;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            Line l = lines[i], m = lines[j];
            double det = - (l.a * m.b - l.b * m.a),
                x = (m.b * l.c - l.b * m.c) / det,
                y = (l.a * m.c - l.c * m.a) / det;
            xs.push_back(x);
            ys.push_back(y);
        }
    }
    const int i = (xs.size() - 1) / 2;
    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());
    return {xs[i], ys[i]};
}

