void solve(long long N, vector<rn> A, vector<rn> B, vector<rn> C){
	function<int(double)> calc = [&](double x){
		vector<pair<double,double> > y_slope;
		REP(i,N){
			rn y = (C[i] - A[i]*x)/B[i];
			y_slope.push_back(make_pair(y,-A[i]/B[i]));
		}
		sort(ALL(y_slope));
		set<double> s;
		Int ans = 0;
		REP(i,y_slope.size()){
			ans+=distance(s.begin(),s.lower_bound(y_slope[i].second));
			s.insert(y_slope[i].second);
		}
		return ans;
	};
	Int D = N*(N-1)/2;
	Int num = (D+1)/2;
	function<double()> bs = [&](){
		rn l = -1e+9L, r = +1e+9L;
		while(r-l>1e-10){
			rn m = (l+r)*0.5L;
			if(calc(m)<num)l = m;
			else r = m;
		}
		return l;
	};
	rn s = bs();
	swap(A,B);
	rn t = bs();
	fout<<s<<" "<<t<<endl;
}

