double solve(const V<t3> &abclist, ll n, ll isy)
{
    double left = -1e18-1.0;
    double right = 1e18+1.0;
    double now = 0.0;
    ll count = 0;

    for ( ; left <= right; now = (left + right) / 2.0) {

        debug_printf("xx0\n");

        double minval = left;
        double maxval = right;
        double leftn = left;
        double rightn = right;
        ll leftcount = 0LL;
        ll rightcount = 0LL;

        rep (i, n) {

            debug_printf("xx1\n");

            ll a1 = get<0>(abclist[i]);
            ll b1 = get<1>(abclist[i]);
            ll c1 = get<2>(abclist[i]);
            srep (j, i+1, n) {
                ll a2 = get<0>(abclist[j]);
                ll b2 = get<1>(abclist[j]);
                ll c2 = get<2>(abclist[j]);

                double val;
                if (!isy) {
                    val = (double)(b2 * c1 - b1 * c2);
                    val /= (double)(a1 * b2 - a2 * b1);
                }
                else {
                    val = (double)(a2 * c1 - a1 * c2);
                    val /= (double)(b1 * a2 - b2 * a1);
                }

                minval = min(minval, val);
                maxval = max(maxval, val);
                if (val < now) {
                    leftcount++;
                    debug_printf("xx1 %f %f\n",
                                 abs(now - val), abs(now - leftn));
                    if (abs(now - val) < abs(now - leftn)) leftn = val;
                }
                else {
                    debug_printf("xx2 %f %f\n",
                                 abs(now - val), abs(now - rightn));
                    rightcount++;
                    if (abs(now - val) < abs(now - rightn)) rightn = val;
                }
            }
        }

        if (leftcount == rightcount || leftcount == rightcount + 1LL) {
            return leftn;
        }
        if (leftcount + 1LL == rightcount) {
            return rightn;
        }

        if (left < -1e18) left = minval;
        if (right > 1e18) right = maxval;
        if (leftcount < rightcount) left = now;
        if (rightcount < leftcount) right = now;

        count++;
        debug_printf("---- count=%lld\n", count);

        return 0.0;
    }
}

