using namespace std;

const int MAXN = 100000 + 10;
const int Epsilon = 1e-8;

int N, K;
int A[MAXN], B[MAXN], C[MAXN];
int Order[MAXN];

bool Cmp(const int& i, const int& j)
{
	return A[i] * B[j] < A[j] * B[i];
}

double a[MAXN], b[MAXN], c[MAXN], d[MAXN];

bool Cmp2(const int& i, const int& j)
{
	if (fabs(d[i] * b[j] - d[j] * b[i]) > Epsilon)
		return d[i] * b[j] < d[j] * b[i];
	return i > j;
}

long long ans;
int tmp[MAXN];

void Merge(int l, int m, int r)
{
	int i = l;
	int j = m + 1;
	int k = l;
	while (i <= m && j <= r)
	{
		if (Order[i] > Order[j])
        {
			tmp[k ++] = Order[j ++];
			ans += (long long) (m - i + 1);
		}
		else
			tmp[k ++] = Order[i ++];
    }
    while (i <= m) tmp[k ++] = Order[i ++];
    while (j <= r) tmp[k ++] = Order[j ++];
	for (int i = l; i <= r; i ++) Order[i] = tmp[i];
}

void Merge_sort(int l, int r)
{
	if (l < r)
	{
		int m = (l + r) >> 1;
		Merge_sort(l, m);
		Merge_sort(m + 1, r);
		Merge(l, m, r);
    }
}

double GetOptimalPosition()
{
	double Left = -1e10, Right = 1e10;
	sort(Order, Order + N, Cmp);
	for (int i = 0; i < N; i ++)
	{
		a[i] = A[Order[i]];
		b[i] = B[Order[i]];
		c[i] = C[Order[i]];
	}
	long long Tot = N * (N - 1) / 2;
	for (int rep = 0; rep < 200; rep ++)
	{
		double Mid = (Left + Right) * 0.5;
		for (int i = 0; i < N; i ++) d[i] = c[i] - a[i] * Mid;
		sort(Order, Order + N, Cmp2);

		ans = 0;
		Merge_sort(0, N - 1);

		if (Tot % 2 == 1)
		{
			if (ans <= Tot / 2)
				Left = Mid;
			else
				Right = Mid;
		}
		else
		{
			if (ans < Tot / 2)
				Left = Mid;
			else
				Right = Mid;
		}
	}
	return Left;
}

void Work()
{
	scanf("%d", &N);
	for (int i = 0; i < N; i ++)
		scanf("%d%d%d", &A[i], &B[i], &C[i]);

	for (int i = 0; i < N; i ++)
		Order[i] = i;

	for (int i = 0; i < N; i ++)
		if (B[i] < 0)
		{
			A[i] *= -1;
			B[i] *= -1;
			C[i] *= -1;
		}
	double Ans1 = GetOptimalPosition();
	for (int i = 0; i < N; i ++)
		swap(A[i], B[i]);
	for (int i = 0; i < N; i ++)
		if (B[i] < 0)
		{
			A[i] *= -1;
			B[i] *= -1;
			C[i] *= -1;
		}
	double Ans2 = GetOptimalPosition();
	printf("%.10lf %.10lf\n", Ans1, Ans2);
}

int main()
{
	Work();
	return 0;
}

