template <typename T>
class SegmentTree {
public:
  using F = function<T(T&, T&)>;
  int n;
  vector<T > dat;
  T e; // 単位元
  F query_func;
  F update_func;

  SegmentTree(vector<T> a, F query_func, F update_func, T e) :n(a.size()), query_func(query_func), update_func(update_func), e(e) {
    dat.resize(4 * n);
    init(0, 0, n, a);
  }

  void init(int k, int l, int r, vector<T> &a) {
    if (r - l == 1) {
      dat[k] = a[l];
    }
    else {
      int lch = 2 * k + 1, rch = 2 * k + 2;
      init(lch, l, (l + r) / 2, a);
      init(rch, (l + r) / 2, r, a);
      dat[k] = query_func(dat[lch], dat[rch]);
    }
  }

  //k番目の値をaに変更
  void update(int k, T a, int v, int l, int r) {
    if (r - l == 1) {
      dat[v] = update_func(dat[v], a);
    }
    else {
      if (k < (l + r) / 2)
        update(k, a, 2 * v + 1, l, (l + r) / 2);
      else {
        update(k, a, 2 * v + 2, (l + r) / 2, r);
      }
      dat[v] = query_func(dat[v * 2 + 1], dat[v * 2 + 2]);
    }
  }


  //[a,b)の最小値を求める
  //後ろのほうの引数は計算の簡単のための引数
  //kは接点の番号,l,rはその接点が[l,r)に対応していることを表す
  //従って、外からはquery(a,b,0,0,n)としてよぶ
  T query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) {
      return e;
    }
    if (a <= l && r <= b) {
      return dat[k];
    }
    else {
      T ul = query(a, b, k * 2 + 1, l, (l + r) / 2);
      T ur = query(a, b, k * 2 + 2, (l + r) / 2, r);
      return query_func(ul, ur);
    }
  }
};


bool cmp(pair<pii, int> a, pair<pii, int> b) {
  return (double)a.first.first / a.first.second < (double)b.first.first / b.first.second;
}

int f1(int a, int b) {
  return a + b;
}
int f2(int a, int b) {
  return a + b;
}

double solve(int n, vi a, vi b, vi c) {
  rep (i, n) {
    if (b[i] < 0) {
      a[i] *= -1;
      b[i] *= -1;
      c[i] *= -1;
    }
  }

  vector<pair<pii, int>> abc(n);
  rep (i, n) {
    abc[i].first.first = a[i];
    abc[i].first.second = b[i];
    abc[i].second = c[i];
  }
  sort(all(abc), cmp);
  //DEBUG_VEC(abc);
  rep (i, n) {
    a[i] = abc[i].first.first;
    b[i] = abc[i].first.second;
    c[i] = abc[i].second;
  }

  /*
  DEBUG_VEC(a);
  DEBUG_VEC(b);
  DEBUG_VEC(c);
  //*/

  double ng = -inf * 10.0, ok = inf * 10.0;
  int threshold = ((n * (n - 1) / 2) + 1) / 2;
  //DEBUG(threshold);
  rep (_, 100) {
    double mid = (ng + ok) / 2;
    vector<double> value(n);
    set<double> st;
    rep (i, n) {
      value[i] = (double)(c[i] - mid*a[i]) / b[i];
      st.insert(value[i]);
    }
    map<double, int> mp;
    int cnt = 0;
    for (auto itr = st.begin(); itr != st.end(); itr++) {
      mp[*itr] = cnt++;
    }

    vi value_int(n);
    vi num(cnt);
    rep (i, n) {
      value_int[i] = mp[value[i]];
      num[value_int[i]]++;
    }

    //DEBUG_VEC(value);
    //DEBUG_VEC(value_int);
    SegmentTree<int> big(num, f1, f2, 0), small(vi(cnt), f1, f2, 0);
    int smaller = 0;
    rep (i, n) {
      int x = value_int[i];
      big.update(x, -1, 0, 0, big.n);

      /*
      rep (i, cnt) {
        cout << big.query(i, i + 1, 0, 0, big.n) << " ";
      }
      cout << endl;
      rep (i, cnt) {
        cout << small.query(i, i + 1, 0, 0, small.n) << " ";
      }
      cout << endl;
      //*/

      smaller += big.query(0, x + 1, 0, 0, big.n);
      smaller += small.query(x, small.n, 0, 0, small.n);
      small.update(x, 1, 0, 0, small.n);
      //DEBUG(smaller);
    }
    assert(smaller % 2 == 0);
    smaller /= 2;
    //DEBUG(mid);
    //DEBUG(smaller);
    if (smaller >= threshold) {
      ok = mid;
    }
    else {
      ng = mid;
    }
  }
  return ok;
}

