        double p = (double)(c - a * (-1e12)) / (double)b;
        pabclist.pb(dlll(p, a, b, c));
    }

    sort(pabclist);

    double left = -1e12;
    double right = 1e12;
    double ans = 1e12;
    ll border = combination(n, 2LL);
    border = border / 2LL + (border & 1LL);

    S BIT tree(40005, 0);

    rep (xxx, 100) {
        double now = (left + right) / 2.;
        debug_printf("------ now = %lf\n", now);

        V<dl> xilist;
        rep (i, n) {
            auto pabc = pabclist[i];
            ll a = get<1>(pabc);
            ll b = get<2>(pabc);
            ll c = get<3>(pabc);
            double x = ((double)c - (double)a * now) / (double)b;
            xilist.pb(dl(x, i));
        }

        sort(xilist);

        tree.init(0LL);
        ll total = 0LL;
        for (auto xi : xilist) {
            ll i = get<1>(xi);
            debug_printf("i=%lld\n", i);
            ll cnt = tree.sum(40005) - tree.sum(i+1);
            total += cnt;
            tree.add(i+1, 1LL);
        }

        debug_printf("total = %lld border = %lld\n", total, border);

        if (total >= border) {
            ans = min(ans, now);
            right = now;
        }
        else {
