struct BIT{
  using T = ll;
  vector<T> dat;
  T UNIT;
  int n;

  BIT(int n,T a) : n(n), UNIT(a){
    dat.resize(n+1,UNIT);
  }

  T sum (int i){
    int s = 0;
    while(i > 0){
      s += dat[i];
      i -= i & -i;
    }
    return s;
  }

  void add(int i, T x){
    while(i <= n){
      dat[i] += x;
      i += i & -i;
    }
  }
  T rgget(int r, int l){
    return sum(r) - sum(l-1);
  }

};

