int N;
int A[40000];
int B[40000];
int C[40000];

vector<double> vx;
vector<double> vy;

signed main()
{
	cin >> N;
	REP(i, N) cin >> A[i] >> B[i] >> C[i];

	for (int i = 0; i < N; i++)
	{
		for (int j = i + 1; j < N; j++)
		{
			double y = (A[j] * C[i] - A[i] * C[j]) / (double)(A[j] * B[i] - A[i] * B[j]);
			double x = (C[i] - B[i] * y) / (double)A[i];
			vx.push_back(x);
			vy.push_back(y);
		}
	}

	SORT(vx);
	SORT(vy);

	int V = vx.size();
	double ax = 0.0;
	double ay = 0.0;
	for (int i = 0; i < V - 1; i++)
	{
		ax += vx[i + 1] - vx[0];
		ay += vy[i + 1] - vy[0];
	}

	double ans_x = vx[0];
	double ans_y = vy[0];
	double min_x = ax;
	double min_y = ay;
	for (int i = 1; i < V; i++)
	{
		double s = vx[i] - vx[i - 1];
		ax = ax - (V - i) * s + i * s;
		if (ax < min_x)
		{
			min_x = ax;
			ans_x = vx[i];
		}
	}
	for (int i = 1; i < V; i++)
	{
		double s = vy[i] - vy[i - 1];
		ay = ay - (V - i) * s + i * s;
		if (ay < min_y)
		{
			min_y = ay;
			ans_y = vy[i];
		}
	}
	cout << fixed << setprecision(10);
