LL N;
struct Line {
	int A, B, C;
	double val;

	void compute(double x) {
		val = (-A * x + C) / B;
	}

	double retCompute(double x) {
		return (-A * x + C) / B;
	}
} L[100005];
double eps = 1e-11;

bool operator<(Line P, Line Q) {
	return P.val < Q.val;
}

int tree[100005];

//return cf[idx]
int read(int idx)
{
	int sum = 0;

	while (idx > 0)
	{
		sum += tree[idx];
		idx -= (idx & -idx);
	}

	return sum;
}

//add val to f[idx].
//MaxVal = Just max value of index
void update(int idx, int val)
{
	while (idx <= 100004)
	{
		tree[idx] += val;
		idx += (idx & -idx);
	}
}

bool cmp(pair<double, int> A, pair<double, int> B) {
	if (fabs(A.first - B.first) < eps) {
		return A.second > B.second;
	}
	return A.first < B.first;
}

// How many ints in the left side of X = x?
LL Count(double x) {
	LL total = 0;

	vector<pair<double, int>> V;
	for (int i = 0; i < N; i++) {
		double d = L[i].retCompute(x);
		V.push_back({ d, i });
	}

	sort(V.begin(), V.end(), cmp);
	for (int i = N - 1; i >= 0; i--) {
		total += read(V[i].second + 1);
		update(V[i].second + 1, 1);
	}
	for (int i = 0; i < N; i++) {
		update(V[i].second + 1, -1);
	}
	return total;
}

double solve() {
	sort(L, L + N);

	double lo = -1e12;
	double hi = 1e12;
	LL total = (N)*(N - 1) / 2;
	LL at = (total + 1) / 2;
	for (int i = 1; i <= 200; i++) {
//		if (fabs(hi - lo) < eps) break;
//		if (fabs((hi - lo) / lo) < eps) break;
		double mid = (lo + hi) / 2;
		if (Count(mid) >= at) {
			hi = mid;
		}
		else {
			lo = mid;
		}
	}
	return (lo + hi) / 2;
}

