	}

	double x = solve();
	for (int i = 0; i < N; i++) {
		swap(L[i].A, L[i].B);
		L[i].compute(-1e10);
	}
	double y = solve();

	printf("%.12lf %.12lf\n", x, y);
	return 0;
}

