    else return -l1.a*l2.b > -l2.a*l1.b;
}

bool comp2(line& l1,line& l2){
    if(l2.a*l1.a>0) return -l1.b*l2.a < -l2.b*l1.a;
    else return -l1.b*l2.a > -l2.b*l1.a;
}


struct BIT{
