void update(int i, int j, int sidx, int idx, int val, int stree[])
{
	stree[sidx] += val;
	if(i >= j)
		return;
	int m = (i + j) >> 1;
	if(idx <= m)
		update(i, m, sidx * 2, idx, val, stree);
	else
		update(m + 1, j, sidx * 2 + 1, idx, val, stree);
}

int query(int i, int j, int sidx, int ql, int qr, int stree[])
{
	// trace(i, j, ql, qr);
	if(i > qr or j < ql)
		return 0;
	if(i >= ql and j <= qr)
		return stree[sidx];
	int m = (i + j) >> 1;
	return query(i, m, sidx * 2, ql, qr, stree) + query(m + 1, j, sidx * 2 + 1, ql, qr, stree);
}

ll count_inversions(long double val[], int N)
{
	pair <long double, int> A[N + 1];
	for(int i = 1; i <= N; i++)
	{
		A[i].F = val[i];
		A[i].S = i;
	}
	sort(A + 1, A + N + 1);

	int stree[N * 4];
	make0(stree);
	ll ans = 0;
	for(int i = N; i >= 1; i--)
	{
		// trace(i, A[i].S);
		int s = query(1, N, 1, 1, A[i].S - 1, stree);
		update(1, N, 1, A[i].S, 1, stree);
		ans += s * 1ll;
		// trace(s);
	}
	return ans;
}

long double check_x(line a[], int n, long double mid)
{
	long double val[n + 1];
	for(int i = 1; i <= n; i++)
		val[i] = (a[i].c - a[i].a * mid) / a[i].b;
	// trace("here");
	ll inversions = count_inversions(val, n);
	return inversions;
}

long double check_y(line a[], int n, long double mid)
{
	long double val[n + 1];
	for(int i = 1; i <= n; i++)
		val[i] = (a[i].c - a[i].b * mid) / a[i].a;
	reverse(val + 1, val + n + 1);
	ll inversions = count_inversions(val, n);
	return inversions;
}


