double cs[114514];
int BIT[114514];

void add(int k, int x) {
  k++;
  while (k <= N+1) {
    BIT[k] += x;
    k += k&-k;
  }
}

int getsum(int k) {
  k++;
  int ret = 0;
  while (k > 0) {
    ret += BIT[k];
    k -= k&-k;
  }
  return ret;
}

double determine(double *A, double *B, double *C) {
  double low = -INF;
  double high = INF;
  for (int i=0; i<80; i++) {
    LLI cnt = 0;
    double k = (low+high)/2;
    vector<double> ys;
    vector<Pair> ps;

    fill(BIT, BIT+N+10, 0);
    for (int j=0; j<N; j++) {
      double X = A[j]/B[j];
      double Y = k*(A[j]/B[j]) - (C[j]/B[j]);
      ys.emplace_back(Y);
      ps.emplace_back(Pair(X, Y));
    }

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    sort(ps.begin(), ps.end());
    for (Pair p : ps) {
      double X = p.first;
      double Y = p.second;
      int idx = lower_bound(ys.begin(), ys.end(), Y) - ys.begin();
      cnt += getsum(idx);
      add(idx, 1);
    }

    //printf("%.20f: %lld %lld\n", k, cnt, (tot/2+tot%2));
    if (cnt < (tot/2+tot%2)) low = k;
    else high = k;
  }
  return low;
}

