typedef tuple<double, ll> dt;
typedef tuple<double, ll, ll ,ll> dttt;

double solve(const V<dttt> &dabclist, ll n, bool isx)
{
    double left = -1e8;
    double right = 1e8;
    double now = 0.0;
    double ret = 1e8;

    ll border = (n * (n - 1LL)) / 2LL;
    border = ((border & 1LL) ? (border / 2LL + 1LL) : (border / 2LL));

    BIT bitree(n+1, 0LL);

    debug_printf("n=%lld border=%lld\n", n, border);
    ll loopcount = 0LL;

    for ( ; ; now = (left + right) / 2.0) {

        if (abs(left) > 0.0) {
            if (abs(right / left - 1.) < 1e-15) break;
        }
        if (abs(right) > 0.0) {
            if (abs(left / right - 1.) < 1e-15) break;
        }

        bitree.init(0LL);
        V<dt> order;

        rep (i, n) {
            ll a = get<1>(dabclist[i]);
            ll b = get<2>(dabclist[i]);
            ll c = get<3>(dabclist[i]);

            double p = (double)c - ((double)(isx ? a : b)) * now;
            p /= (double)(isx ? b : a);

            order.pb(dt(p, i+1LL));  // 0 origin --> 1 origin
        }

        sort(order);

        ll count = 0LL;
        for (auto pi : order) {
            ll i = get<1>(pi);
            count += bitree.sum(i);
            bitree.add(i, 1LL);
        }

        debug_printf("left=%5.15lf right=%5.15lf sub=%5.15lf now=%5.15lf ret=%5.15lf count=%lld\n",
                     left, right, right - left, now, ret, count);

        if (count < border) {
            left = now;
        }
        if (count == border) {
            ret = min(ret, now);
            right = now;
        }
        if (count > border) {
            right = now;
        }

        loopcount++;
        // if (loopcount >= 5000LL) return ret;
        assert(loopcount < 5000LL);
    }

    debug_printf("loopcount=%lld\n", loopcount);

    return ret;
}

int _main()
{
    ll n; llin(n);
    V<t3> abclist; llinl3(abclist, n);

    V<dttt> dabclist;
    for (auto abc : abclist) {
        ll a = get<0>(abc);
        ll b = get<1>(abc);
        ll c = get<2>(abc);
        double d = -((double)a) / ((double)b);
        dabclist.pb(dttt(d, a, b, c));
    }
    sort(dabclist);

    double x = solve(dabclist, n, true);

    dabclist.clear();
    for (auto abc : abclist) {
        ll a = get<0>(abc);
        ll b = get<1>(abc);
        ll c = get<2>(abc);
        double d = -((double)b) / ((double)a);
        dabclist.pb(dttt(d, a, b, c));
    }
    sort(dabclist);

    double y = solve(dabclist, n, false);

    printf("%5.15lf %5.15lf\n", x, y);

    return 0;
}

