        int sum = 0;

        for (j = 0; j < n; j++) {
            w[j].first = (-(double)a[j] * m + c[j]) / b[j];
            w[j].second = d[j];
        }

        sort(w.begin(), w.end());

        bt.clear();

        for (j = 0; j < n; j++) {
            sum += bt.get(w[j].second);
            bt.add(w[j].second, 1);
        }

        if (n * (n - 1) / 2 % 2 == 0) {
            if (sum >= n * (n - 1) / 4) {
                r = m;
                m = (l + r) / 2;
            } else {
                l = m;
                m = (l + r) / 2;
            }
