using namespace std;
template <typename T>
struct fenwick_tree{
	static const int DEFAULT = 200200;
	int size, off;
	vector<T> tree;
	fenwick_tree(int size = DEFAULT, int off = 0) : size(size), off(off) {
		clear();
	}
	void clear(){
		tree.assign(size, T());
	}
	void add(int pos, T v){
		for (pos += off; pos < size; pos += pos & -pos)
			tree[pos] = tree[pos] + v;
	}
	T sum(int pos){
		T r = T();
		for (pos += off; pos; pos -= pos & -pos)
			r = r + tree[pos];
		return r;
	}
	T query(int l, int r){
		return sum(r) - sum(l - 1);
	}
};
const int maxn = 40400;
int a[maxn], b[maxn], c[maxn];
int id[maxn], pos[maxn], cid[maxn];
