ld solve(int n) {
    vector<int> ix(n);
    forn(i, 0, n) ix[i] = i;
    ld l = -1e9, r = 1e9;
    ll cnt = 1ll * n * (n - 1) / 2;
    int its = 50;
    while (its--) {
        ld m = (l + r) / 2;
        //cerr << l << ' ' << r  << '\n';
        //cerr << m << ' ';
        forn(i, 0, n) vals[i] = ls[i].val(m);
        auto cmp = [&](int x, int y) {
            return vals[x] < vals[y] - eps1;
        };
        sort(all(ix), cmp);
        ll rgt = 0;
        ordered_set a;
        //cerr << "lines:\n";
        for (int i : ix) {
            //cerr << i << ' ' << a.order_of_key(i) << '\n';
            rgt += a.order_of_key(i);
            a.insert(i);
        }
        if (rgt > cnt / 2) l = m;
        else r = m;
    }
    return (l + r) / 2;
}

