struct inv_num{
  vector<ll>bit;
  ll n;
  void init(ll _n){
    n = _n;
    bit.resize(2*n);
  }
  ll sum(ll i){
    ll s = 0;
    while(i>0){
      s+=bit[i];
      i-=i&-i;
    }
    return s;
  }
  void add(ll i, ll x){
    while(i<=n){
      bit[i]+=x;
      i+=i&-i;
    }
  }
  ll ans(ll* list, ll n){
    init(n);
    ll res = 0;
    REP(j,n){
      res+=j-sum(list[j]);
      add(list[j],1);
    }
    return res;
  }
};


