double x(int i, int j) {
    return double(b[i] * c[j] - c[i] * b[j]) / (a[i] * b[j] - b[i] * a[j]);
}

double y(int i, int j) {
    return -double(a[i] * c[j] - c[i] * a[j]) / (a[i] * b[j] - b[i] * a[j]);
}

double get_x(int n, int m) {
    m++;

    double minx = -1e9, maxx = 1e9;

    while (true) {
        double X = (maxx + minx) / 2;
        double ans = minx;

        int cnt = 0;
        rep (i, n) {
            rep (j, i) {
                double xx = x(i, j);
                if (xx < X) {
                    cnt++;
                    chmax(ans, xx);
                }
            }
        }

        if (cnt == m)
            return ans;
        if (cnt < m)
            minx = X;
        else
            maxx = X;
    }
}

