	void init(int sz) {
		size_ = sz + 2;
		dat.resize(size_ + 2, 0);
	}
	void add(int pos, int x) {
		pos++;
		while (pos <= size_) {
			dat[pos] += x;
			pos += (pos&-pos);
		}
		return;
	}
	int sum(int pos) {
		int s = 0; pos++;
		while (pos >= 1) {
			s += dat[pos];
			pos -= (pos&-pos);
		}
		return s;
	}
};

long long hanten(vector<long long>E) {
	BIT Z; Z.init(E.size() + 2);
	long long Y = 0;
	for (int i = 0; i < E.size(); i++) {
		Y += (long long)(i - Z.sum(E[i]));
		Z.add(E[i], 1);
	}
	return Y;
}

