namespace XX
{
    template<typename T>
    class Treap
    {
        public:
    //        template<typename U = T, void(U::*P)(T&, T&) = &U::operator()>
  //          static constexpr bool CHECK_STAT(void(T::*p)(T&, T&) = P){return true;}
//            static constexpr bool CHECK_STAT(...){return false;}
            static const constexpr bool HAS_STAT = 0;//CHECK_STAT(0);

            int size() const{ return _size;}
            Treap():_size(0){}
            template<typename... Args> void insert(Args... args) { _size++; _insert(_root, _newnode(args...)); }
            bool erase(const T& val) { bool ret = false; if(_erase(_root, val))_size--, ret = true; return ret;}
            int rank(const T& val)const { return _rank(_root, val); }
            T kth(int k)const { return _kth(_root, k);}



            T min()const
            {
                Node* node = _root;
                while(!node->child[0]->isNull())
                    node = node->child[0];
                return node->data;
            }
            T max()const
            {
                Node* node = _root;
                while(!node->child[1]->isNull())
                    node = node->child[1];
                return node->data;
            }



            template<typename F>
            void statistic(T key, F f)
            {
                statistic(_root, key, f);
            }


            struct Node: public BlockAllocater<Node>, NullNode<Node>
            {
                int pr = -1;
                T data;
                Node* child[2] = {Node::null(), Node::null()};
                int sum;

                Node(){}
                template<typename... Args> Node(int p, Args... args) :pr(p), data(args...) {}
            };

            Node* find(const T& data)
            {
                return _find(_root, data);
            }

            template<typename F>
            void travel(Node* node, F f)
            {
                if(node->isNull())return;

                travel(node->child[0], f);
                f(node);
                travel(node->child[1], f);
            }
            template<typename F>
            void travel(int num, Node* node, F f)
            {
                if(node->isNull())return;
                travel(num, node->child[0], f);
                if(node->child[0]->sum < num)
                {
                    f(node);
                    if(node->child[0]->sum + 1 < num)
                        travel(num - node->child[0]->sum - 1, node->child[1], f);
                }
            }
            template<typename F>
            void travel(F f)
            {
                travel(_root, f);
            }
            template<typename F>
            void travel(int num, F f)
            {
                travel(num, _root, f);
            }

            template<typename F>
            void statistic(Node* node, T key, F f)
            {
                if(node->isNull())return;
                if(node->data < key)
                {
                    f(node->data);
                    statistic(node->child[1], key, f);
                }
                else
                {
                    statistic(node->child[0], key, f);
                }
            }

            void clear()
            {
                _dealloc(_root); _root = Node::null(); _size = 0;
            }
            Node* _root = Node::null();
            int _size;
        private:


            void _dealloc(Node* node)
            {
                if(!node->isNull())
                {
                    _dealloc(node->child[0]);
                    _dealloc(node->child[1]);
                    delete node;
                }
            }

            T _kth(Node* now, int k)const
            {
                while(true)
                {
                    int ls = now->child[0]->sum;
                    if(ls > k)
                        now = now->child[0];
                    else if(ls == k)
                        break;
                    else
                        k -= ls + 1, now = now->child[1];
                }
                return now->data;
            }

            void _rotate(Node*& node, int idx)
            {
                Node* child = node->child[idx];
                node->child[idx] = child->child[idx ^ 1];
                child->child[idx ^ 1] = node;
                node = child;
            }

            bool _erase(Node*& now, const T& data)
            {
                if(now->isNull())
                    return false;

                bool ret = false;

                if(data < now->data)
                    ret = _erase(now->child[0], data);
                else if(now->data < data)
                    ret = _erase(now->child[1], data);
                else if(now->child[0]->isNull() && now->child[1]->isNull())
                {
                    delete now;
                    now = Node::null();
                    return true;
                }
                else 
                {
                    int idx = now->child[0]->pr < now->child[1]->pr;
                    _rotate(now, idx);
                    _erase(now->child[idx ^ 1], data);
                    ret = true;
                }
                _resum(now);
                return ret;
            }
            int _rank(Node* now, const T& data)const
            {
                if(now->isNull())
                    return 0;
                if(now->data < data)
                    return now->sum + _rank(now->child[1],data) - now->child[1]->sum;
                else 
                    return _rank(now->child[0], data);
            }

            template<bool S = HAS_STAT>
            typename std::enable_if<S, void>::type _resum(Node* node)
            {
                node->sum = 1 + node->child[0]->sum + node->child[1]->sum;
                node->data(node->child[0]->data, node->child[1]->data);
            }
            template<bool S = HAS_STAT>
            typename std::enable_if<!S, void>::type _resum(Node* node, ...)
            {
                node->sum = 1 + node->child[0]->sum + node->child[1]->sum;
            }

            Node* _find(Node* now, const T& data)
            {
                /*
                if(now->isNull())
                    return now;
                else if(data < now->data)
                    return _find(now->child[0], data);
                else if(now->data < data)
                    return _find(now->child[1], data);
                else
                    return now;*/
                while(!now->isNull())
                    if(data < now->data)
                        now = now->child[0];
                    else if(now->data < data)
                        now = now->child[1];
                    else
                        break;
                return now;
            }
            void _insert(Node*& now, Node* node) 
            {
                if(now->isNull())
                    now = node;
                else                
                {
                    int idx = now->data < node->data;
                    _insert(now->child[idx], node);
                    if(now->pr < node->pr)
                    {
                        _rotate(now, idx);
                        _resum(now->child[idx ^ 1]);
                    }
                }
                _resum(now);
            }

            template<typename... Args>
            Node* _newnode(Args... args)
            {
                return new Node(Random::xor128() & std::numeric_limits<int>::max(), args...);
            }

    };
}






