struct Line {
    int a, b, c;
    bool operator <(const Line &i) const {
        return (lf)-a/b*X-(lf)c/b + 1e-12 < (lf)-i.a/i.b*X-(lf)i.c/i.b || (abs((lf)-a/b*X-(lf)c/b - (lf)-i.a/i.b*X+(lf)i.c/i.b) < 1e-12 && (lf)-a/b < (lf)-i.a/i.b);
