int n;
struct Line {
    LL a, b, c;
} L[maxn];

bool cmpx(Line x, Line y) {
    return double(x.a) / x.b > double(y.a) / y.b;
}
bool cmpy(Line x, Line y) {
    return double(x.b) / x.a > double(y.b) / y.a;
}

int c[maxn];
int rk[maxn];
double pos[maxn];

bool cmp(int x, int y) { 
    return pos[x] < pos[y]; 
}

#define lowbit(x) ((x) & -(x))
void update(int u) {
    while(u < maxn) {
        c[u] ++;    
        u += lowbit(u);
    }
}
int query(int u) {
    int res = 0;
    while(u > 0) {
        res += c[u];
        u -= lowbit(u);
    }
    return res;
}

bool chkx(double mid) {
    LL res = 0;
    memset(c, 0, sizeof c);
    for(int i = 1; i <= n; ++i) rk[i] = i, pos[i] = -double(L[i].c + L[i].a * mid) / L[i].b;

    sort(rk + 1, rk + n + 1, cmp);
    for(int i = 1; i <= n; ++i) {
        res += query(rk[i]); update(rk[i]);
    }
    return (res << 2LL) >= 1LL * n * (n-1);
}

bool chky(double mid) {
    LL res = 0;
    memset(c, 0, sizeof c);
    for(int i = 1; i <= n; ++i) rk[i] = i, pos[i] = -double(L[i].c + L[i].b * mid) / L[i].a;

    sort(rk + 1, rk + n + 1, cmp);
    for(int i = 1; i <= n; ++i) {
        res += query(rk[i]); update(rk[i]);
    }
    return (res << 2LL) >= 1LL * n * (n-1);
}

