class BIT
{
public:
    vector<int> bit;
    int M;

    BIT(int M):
        bit(vector<int>(M+1, 0)), M(M) {}

    int sum(int i) {
        if (!i) return 0;
        return bit[i] + sum(i-(i&-i));
    }

    void add(int i, int x) {
        if (i > M) return;
        bit[i] += x;
        add(i+(i&-i), x);
    }
};

double calcans(int N, vector<double> &A, vector<double> &B, vector<double> &C){
    //傾き順にソート
    vector<Pdi> p(N);
    REP(i, N) p[i] = Pdi(-1.0 * A[i] / B[i], i);
    SORT(p);
    vector<int> invp(N);
    //傾きの順位(1~N)
    REP(i, N) invp[p[i].second] = i + 1;

    int N_tot = N * (N - 1) / 2;

    double x1 = -1.0e10, x2 = 1.0e10;
    while(x2 - x1 > max(1.0e-12, max(abs(x1), abs(x2)) * 1.0e-12)){
        double x = (x1 + x2) / 2.0;
        vector<Pdi> y(N);
        //y(x)でソート
        REP(i, N) y[i] = Pdi(-1.0 * A[i] / B[i] * x + C[i] / B[i], i);
        SORT(y);
        int count = 0;
        BIT b(N);
        REP(i, N){
            int i0 = y[i].second;
            count += b.sum(invp[i0]);
            b.add(invp[i0], 1);
        }
        if(count >= (N_tot + 1) / 2) x2 = x;
        else x1 = x;
    }
