using namespace std;

const int depth = 16;
class Segtree {
	int data[1 << (depth + 1)];
public:

	void init() { for (int i = 0; i < (1 << (depth + 1)); i++) data[i] = 0; }

	//区間[l, r)にvを足す
	void add(int l, int r, int v, int a = 0, int b = (1 << depth), int id = 0) {
		if (l >= b || r <= a) return;
		if (l <= a && b <= r) { data[id] += v; return; }
		add(l, r, v, a, a + (b - a) / 2, id * 2 + 1);
		add(l, r, v, a + (b - a) / 2, b, id * 2 + 2);
	}

	//要素posの値
	int getNum(int pos) {
		pos = (1 << depth) - 1 + pos;
		int ret = data[pos];
		while (pos > 0) {
			pos = (pos - 1) / 2;
			ret += data[pos];
		}
		return ret;
	}
};

Segtree seg;

