	seg.init();
	for (i = 0; i < n; i++) {
		pos[a[i]] = i;
	}
	for (i = 0; i < n; i++) seg.add(i, i + 1, i);

	sort(a.begin(), a.end());

	int ans = 0;
	for (i = 0; i < n; i++) {
		ans += seg.getNum(pos[a[i]]);
		seg.add(pos[a[i]] + 1, n, -1);
	}
	return ans;
}

