int cntinv(vector<int>v) {
	int N = v.size();
	fenwick_tree<int>BIT(N+1);
	int ans = 0;
	REP(i, N) {
		ans += BIT.sum(v[i],N);
		BIT.add(v[i], 1);
	}
	return ans;
}

