using namespace std;

int N, V;
double A[40005], B[40005], C[40005];
int a[40005], p[40005], array[40005];
vector< pair<double, int> > vec;

int bit[40005];
void init(){
	for(int i = 1; i <= N; i++) bit[i] = 0;
}
int sum(int i)
{
	int ret = 0;
	while(i > 0){
		ret += bit[i];
		i -= i & (-i);
	}
	return ret;
}
void add(int i, int val)
{
	while(i <= N){
		bit[i] += val;
		i += i & (-i);
	}
}

int checkx(double x)
{
	vec.clear();
	for(int i = 1; i <= N; i++){
		vec.push_back( make_pair(-A[i]/B[i], i) );
	}
	sort(vec.begin(), vec.end());
	for(int i = 0; i < vec.size(); i++){
		a[vec[i].second] = i+1;
	}

	vec.clear();
	for(int i = 1; i <= N; i++){
		vec.push_back( make_pair(-A[i]/B[i]*x + C[i]/B[i], i) );
	}
	sort(vec.begin(), vec.end());
	for(int i = 0; i < vec.size(); i++){
		p[vec[i].second] = i+1;
	}

	int ret = 0;
	for(int i = 1; i <= N; i++){
		array[p[i]] = a[i];
	}
	init();
	for(int i = 1; i <= N; i++){
		ret += sum(array[i]);
		add(array[i], 1);
	}
	return ret >= (V+1)/2;
}

int checky(double x)
{
	vec.clear();
	for(int i = 1; i <= N; i++){
		vec.push_back( make_pair(-B[i]/A[i], i) );
	}
	sort(vec.begin(), vec.end());
	for(int i = 0; i < vec.size(); i++){
		a[vec[i].second] = i+1;
	}

	vec.clear();
	for(int i = 1; i <= N; i++){
		vec.push_back( make_pair(-B[i]/A[i]*x + C[i]/A[i], i) );
	}
	sort(vec.begin(), vec.end());
	for(int i = 0; i < vec.size(); i++){
		p[vec[i].second] = i+1;
	}

	int ret = 0;
	for(int i = 1; i <= N; i++){
		array[p[i]] = a[i];
	}
	init();
	for(int i = 1; i <= N; i++){
		ret += sum(array[i]);
		add(array[i], 1);
	}
	return ret >= (V+1)/2;
}

int main(void)
{
	cin >> N;
	for(int i = 1; i <= N; i++){
		cin >> A[i] >> B[i] >> C[i];
	}
	V = N*(N-1)/2;

	double ansx, ansy;

	double ub = 1e9, lb = -1e9, mid;
	while(ub - lb > 1e-11){
		mid = (ub + lb) / 2.0;
		if(checkx(mid)) ub = mid;
		else lb = mid;
	}
	ansx = (ub+lb) / 2.0;

	ub = 1e9, lb = -1e9, mid;
	while(ub - lb > 1e-11){
		mid = (ub + lb) / 2.0;
		if(checky(mid)) ub = mid;
		else lb = mid;
	}
	ansy = (ub+lb) / 2.0;

	printf("%.12f %.12f\n", ansx, ansy);
	return 0;
}

#include<bits/stdc++.h>

using namespace std;

#define X   first
#define Y   second
#define ld  double

const int   N   = 4e4 + 5;
const ld    eps = 1e-10;

typedef pair<ld,ld> ii;
typedef pair<ii,ld> pii;

int n, t[N];

vector<pii> Line;

int fix(pii &p) {
    if (p.X.X < 0)
        p.X.X = -p.X.X,
        p.X.Y = -p.X.Y,
        p.Y = -p.Y;
}
int chk(ld  M)  {
    vector<ld>  v1;
    for(pii l : Line)
        v1.push_back((l.Y - M * l.X.Y) / l.X.X);
    vector<ld>  v2 = v1;
    sort(v2.begin(),v2.end());
    v2.erase(unique(v2.begin(),v2.end()),v2.end());

    int ans = 0;

    for(int i = 1 ; i <= n ; ++i)   t[i] = 0;
    for(ld  x : v1) {
        int p = lower_bound(v2.begin(),v2.end(),x) - v2.begin() + 1;
        for(int k = p ; k <= n ; k += k & -k)   ans += t[k];
        for(int k = p ; k >= 1 ; k -= k & -k)   t[k]++;
    }
    return  4 * ans >= n * n - n + 5;
}
ld  work()  {
    for(pii &l : Line)  fix(l);
    sort(Line.begin(),Line.end(),[](pii &a,pii &b)  {
        return  a.X.X * b.X.Y > a.X.Y * b.X.X;
    });
    ld  L = -1e8;
    ld  R =  1e8;
    while (L + eps < R) {
        ld M = (L + R) / 2;
        if (chk(M))
            R = M;
        else
            L = M;
    }
    for(pii &l : Line)  swap(l.X.X,l.X.Y);
    return  abs(L) > eps ? L : 0;
}

int main()  {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    cin >> n;

    for(int i = 1 ; i <= n ; ++i)   {
        ld  a;  cin >> a;
        ld  b;  cin >> b;
        ld  c;  cin >> c;
        Line.push_back(pii({a,b},c));
    }

    ld  Y = work();
    ld  X = work();

    cout << fixed << setprecision(9) << X << " " << Y;
}

