struct vec2 {
    double x, y;

    vec2() : x(0.0), y(0.0) {}
    vec2(double x, double y) : x(x), y(y) {}

    vec2 operator + (const vec2 &v) const {
        return vec2(x + v.x, y + v.y);
    }
    vec2 operator - (const vec2 &v) const {
        return vec2(x - v.x, y - v.y);
    }
    double operator * (const vec2 &v) const {
        return x * v.x + y * v.y;
    }
    vec2 operator / (const double k) const {
        return vec2(x / k, y / k);
    }
    double operator ^ (const vec2 &v) const {
        return x * v.y - y * v.x;
    }
    bool operator == (const vec2 &v) const {
        return fabs(x - v.x) < eps && fabs(y - v.y) < eps;
    }

    vec2 scale(double k) {
        return vec2(x * k, y * k);
    }
} base;

struct Line2D {
    vec2 a, b;

    Line2D() {}
    Line2D(vec2 a, vec2 b) : a(a), b(b) {}

    int getIntersection(Line2D &line, vec2 &p) {
        if (fabs((a - b) ^ (line.a - line.b)) < eps) {
            if (fabs((a - line.a) ^ (b - line.b)) < eps &&
                fabs((a - line.b) ^ (b - line.a)) < eps) return -1;
            else return 1;
        }
        double t = ((line.b - line.a) ^ (a - line.a)) / ((b - a) ^ (line.b - line.a));
        p = a + (b - a).scale(t);
        return 0;
    }
}l[MAXN];

