int a[40001], b[40001], c[40001];
int n;
struct node
{
	double l, r;
	int typ;
	inline bool operator< (const node &x) const
	{
		return l < x.l;
	}
}comp[40001];

struct idn
{
	double val;
	int typ, t;
};

class cp
{
public:
	inline bool operator() (const idn &a, const idn &b) const
	{
		return a.val > b.val;
	}
};

priority_queue<idn, vector<idn>, cp> pq;

int cnt[2];
pair<double, int> h[40001];
int pos[40001];
int tree[2][40001];

inline int get(int typ, int x)
{
	int ret = 0;
	for (; x <= n; x += x&-x) ret += tree[typ][x];
	return ret;
}

inline void update(int typ, int x, int val)
{
	for (; x; x -= x&-x) tree[typ][x] += val;
}

inline long long checkx(double x)
{
	long long ret = 0;
	for (int i = 1; i <= n; i++)
	{
		double L = (1e6*a[i] + c[i]) / b[i], R = (-x*a[i] + c[i]) / b[i];
		comp[i] = { min(L,R),max(L,R),L < R };
	}
	sort(comp + 1, comp + n + 1);
	for (int i = 1; i <= n; i++)
		h[i] = { comp[i].r,i };
	sort(h + 1, h + n + 1);
	for (int i = 1; i <= n; i++)
		pos[h[i].second] = i;
	while (!pq.empty()) pq.pop();
	cnt[0] = cnt[1] = 0;
	memset(tree, 0, sizeof tree);
	for (int i = 1; i <= n; i++)
	{
		while (!pq.empty() && comp[i].l - pq.top().val > 1e-15)
		{
			cnt[pq.top().typ]--;
			update(pq.top().typ, pq.top().t, -1);
			pq.pop();
		}
		ret += cnt[!comp[i].typ];
		int t = pos[i];
		ret += get(comp[i].typ, t);
		update(comp[i].typ, t, 1);
		pq.push({ comp[i].r,comp[i].typ,t });
		cnt[comp[i].typ]++;
	}
	return ret;
}

inline long long checky(double x)
{
	long long ret = 0;
	for (int i = 1; i <= n; i++)
	{
		double L = (1e6*b[i] + c[i]) / a[i], R = (-x*b[i] + c[i]) / a[i];
		comp[i] = { min(L,R),max(L,R),L < R };
	}
	sort(comp + 1, comp + n + 1);
	for (int i = 1; i <= n; i++)
		h[i] = { comp[i].r,i };
	sort(h + 1, h + n + 1);
	for (int i = 1; i <= n; i++)
		pos[h[i].second] = i;
	while (!pq.empty()) pq.pop();
	cnt[0] = cnt[1] = 0;
	memset(tree, 0, sizeof tree);
	for (int i = 1; i <= n; i++)
	{
		while (!pq.empty() && comp[i].l - pq.top().val > 1e-15)
		{
			cnt[pq.top().typ]--;
			update(pq.top().typ, pq.top().t, -1);
			pq.pop();
		}
		ret += cnt[!comp[i].typ];
		int t = pos[i];
		ret += get(comp[i].typ, t);
		update(comp[i].typ, t, 1);
		pq.push({ comp[i].r,comp[i].typ,t });
		cnt[comp[i].typ]++;
	}
	return ret;
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++)
		scanf("%d%d%d", &a[i], &b[i], &c[i]);
	long long tar = (long long)n*(n - 1) / 2;
	tar = (tar + 1) / 2;
	double l = -1e6, r = 1e6, ansx = -1e6;
	while ((r - l) > 1e-10)
	{
		double mid = (l + r) / 2;
		if (checkx(mid) >= tar) ansx = mid, r = mid - 1e-11;
		else l = mid + 1e-11;
	}
	l = -1e6, r = 1e6;
	double ansy = -1e6;
	while ((r - l) > 1e-10)
	{
		double mid = (l + r) / 2;
		if (checky(mid) >= tar) ansy = mid, r = mid - 1e-11;
		else l = mid + 1e-11;
	}
	printf("%.10lf %.10lf", ansx, ansy);
	return 0;
}

