template<class T> using SET=tree<T,null_type,less<T>,rb_tree_tag,tree_order_statistics_node_update>;
/*
setでできるものは大体できます。insert,erase,iterator関連・swapなど。
find_by_order 関数
var_name.find_by_order(k) でk番目（0-indexed）のiteratorを返します。
order_of_key 関数
var_name.order_of_key(key) でkey以上の最初の要素が、treeの中で何番目か返します。
 */

double solve(vector<ll> &a,vector<ll> &b,vector<ll> &c){
  int n=a.size();
  ll t=n*(n-1)/2;
  vector<int> ind(n); iota(all(ind),0);
  double l=-2e10,r=2e10;
  rep(_,100){
    double x=(l+r)/2;
    sort(all(ind),[&](int i,int j){ return (c[i]-a[i]*x)/b[i] < (c[j]-a[j]*x)/b[j];});
    SET<double> st;
    ll cnt=0;
    for(int i:ind){
      double r=(double)a[i]/b[i];
      cnt+=st.order_of_key(r);
      st.insert(r);
    }
    (t-cnt>=cnt?r:l)=x;
  }
  return r;
}

