	REP(i, n) {
		L[i] = LINE{ a[i], b[i], c[i], i };
	}
	double x, y;
	{ // x
		std::sort(ALL(L), [&](LINE l, LINE r) {
			return -(double)l.a / l.b > -(double)r.a / r.b;
		});
		REP(i, n) {
			L[i].i = i;
		}
