				return t < n * (n - 1) / 4;
			}
			else {
				return t <= n * (n - 1) / 4;
			}
		};
		x = bisectionDouble(l, r, 100, check);
	}
	{ // y
		std::sort(ALL(L), [&](LINE l, LINE r) {
			return -(double)l.b / l.a > -(double)r.b / r.a;
		});
		REP(i, n) {
			L[i].i = i;
		}
		double l = -1000000, r = 1000000;
		auto check = [&](double y) {
			using P = std::multimap<double, int>;
			P map;
			REP(i, n) {
				map.insert(P::value_type((double)(-L[i].b*y + L[i].c) / L[i].a, L[i].i));
			}
			std::vector<int> a;
			a.reserve(n);
			for (auto p : map) {
				a.emplace_back(p.second);
			}
			int t = 0;
			ST st(n, SUM);
			REP(i, n) {
				t += i - st.query(0, a[i]);
				st.add(a[i], 1);
			}
			if ((n*(n-1)/2) % 2 == 0) {
				return t < n * (n - 1) / 4;
			}
			else {
				return t <= n * (n - 1) / 4;
			}
		};
		y = bisectionDouble(l, r, 100, check);
	}
	FOUT(12, x)SP FOUT(12, y)BR;
