//1-origin
template <typename T>
struct FenwickTree {
        vector<T> data;
        FenwickTree(int n) : data(n + 1, 0) {}
        //data[i] += x
        void add(int i, T x){
                while (i <= (int)data.size()) {
                        data[i] += x;
                        i += i & -i;
                }
        }
        //[1, i)
        T sum(int i){
                T res = 0;
                while (i > 0) {
                        res += data[i];
                        i -= i & -i;
                }
                return res;
        }
        //[l, r)
        T sum(int l, int r) { return sum(r) - sum(l); }
};
long long InversionNumber(vector<int> a) {
        for (int i = 0; i < a.size(); i ++) {
                a[i] ++;
        }
        FenwickTree<long long> ft(300030);
        long long res = 0;
        for (int i = 0; i < a.size(); i ++) {
                res += i - ft.sum(a[i]);
                ft.add(a[i], 1);
        }
        return res;
}

int main() {
        int n;
        scanf("%d", &n);
        vector<line> ln(n);
        for (int i = 0; i < n; i ++) {
                scanf("%d %d %d", &ln[i].a, &ln[i].b, &ln[i].c);
        }
        int half = n * (n - 1) / 4 + !!(n * (n - 1) % 4);
        double leftmost = -50000;
        vector<pair<double, int>> left_points;
        for (int i = 0; i < n; i ++) {
                line l = ln[i];
                left_points.emplace_back((double) (l.c - l.a * leftmost) / (double) l.b, i);
        }        
        sort(left_points.begin(), left_points.end());
        vector<int> convert(n);
        for (int i = 0; i < n; i ++) {
                convert[left_points[i].second] = i;
        }
        double lb = -500000, ub = 500000;
        int loop = 100;
        while (loop --) {
                double mid = (lb + ub) / 2;
                vector<pair<double, int>> mid_points;
                for (int i = 0; i < n; i ++) {
                        line l = ln[i];
                        mid_points.emplace_back((double) (l.c - l.a * mid) / (double) l.b, i);
                }
                sort(mid_points.begin(), mid_points.end());
                vector<int> a;
                for  (int i = 0; i < mid_points.size(); i ++) {
                        a.push_back(convert[mid_points[i].second]);
                }
                int get = InversionNumber(a);
                if (get < half) {
                        lb = mid;
                } else {
                        ub = mid;
                }
        }
        double ansx = lb;
        leftmost = -50000;
        left_points.clear();
        for (int i = 0; i < n; i ++) {
                line l = ln[i];
                left_points.emplace_back((double) (l.c - l.b * leftmost) / (double) l.a, i);
        }        
        sort(left_points.begin(), left_points.end());
        for (int i = 0; i < n; i ++) {
                convert[left_points[i].second] = i;
        }
        lb = -500000, ub = 500000;
        loop = 100;
        while (loop --) {
                double mid = (lb + ub) / 2;
                vector<pair<double, int>> mid_points;
                for (int i = 0; i < n; i ++) {
                        line l = ln[i];
                        mid_points.emplace_back((double) (l.c - l.b * mid) / (double) l.a, i);
                }
                sort(mid_points.begin(), mid_points.end());
                vector<int> a;
                for  (int i = 0; i < mid_points.size(); i ++) {
                        a.push_back(convert[mid_points[i].second]);
                }
                int get = InversionNumber(a);
                if (get < half) {
                        lb = mid;
                } else {
                        ub = mid;
                }
        }
        double ansy = lb;
        printf("%.15lf %.15lf\n", ansx, ansy);
        return 0;
}

