struct solver
{
    i64 n;

    double calc(vector<pair<double,double>> lines)
    {
        sort(begin(lines), end(lines));
        auto ok=[&](const double k)
        {
            vector<double> val;
            for(auto [x,y]: lines) val.emplace_back(x*k+y);
            sort(begin(val), end(val));
            segment_tree<int> seg(n);
            i64 cnt=0;
            for(auto [x,y]: lines)
            {
                double now=x*k+y;
                int ival=lower_bound(begin(val), end(val), now)-begin(val);
                cnt+=seg.fold(0,ival);
                seg[ival]++;
            }
            return cnt*2>=n*(n-1)/2;
        };
        return binary(1e6,-1e6,1e-9,ok);
    }

    solver() : n(read())
    {
        vector<pair<double,double>> lx,ly;
        for(int i=0; i<n; ++i)
        {
            int a=read(),b=read(),c=read();
            lx.emplace_back(double(-a)/b,double(c)/b);
            ly.emplace_back(double(-b)/a,double(c)/a);
        }
        cout<<calc(lx)<<" "<<calc(ly)<<endl;
    }
};

