using namespace std;
typedef long long ll;
typedef pair<long double,int> P;

int n;
long double a[50001],b[50001],c[50001];

int n_=1<<16;

class segtree{
public:
	int dp[1<<17];
	segtree(){
		memset(dp,0,sizeof(dp));
	}
	void init(){
		memset(dp,0,sizeof(dp));
	}
	void update(int k,int v){
		k+=n_-1;
		dp[k]+=v;
		while(k>0){
			k=(k-1)/2;
			dp[k]=dp[k*2+1]+dp[k*2+2];
		}
	}

	int query(int a,int b,int k=0,int l=0,int r=n_){
		if(b<=l || r<=a)return 0;
		if(a<=l && r<=b)return dp[k];
		int mid=(l+r)/2;
		int vl=query(a,b,k*2+1,l,mid);
		int vr=query(a,b,k*2+2,mid,r);
		return vl+vr;
	}
};

segtree seg;

vector<P> vec;
vector<P> vec2;
int ord[50001];

bool C(long double v){
	vec.clear();
	vec2.clear();
	for(int i=0;i<n;i++){
		long double val=(long double)c[i]/b[i]-(a[i]/b[i])*(-100000005.0);
		vec.push_back(P(val,i));
	}
	sort(vec.begin(),vec.end());
	seg.init();
	for(int i=0;i<n;i++){
		ord[vec[i].second]=i;
		long double val=(long double)c[i]/b[i]-(a[i]/b[i])*v;
		vec2.push_back(P(val,i));
		seg.update(i,1);
	}
	sort(vec2.begin(),vec2.end());
	ll cnt=0;
	for(int i=0;i<n;i++){
		cnt+=(ll)seg.query(0,ord[vec2[i].second]);
		seg.update(ord[vec2[i].second],-1);
	}
	ll val=(ll)n*(n-1)/2LL;
	if(val%2LL==0)return cnt<(val/2LL);
	return cnt*2LL<val;
}

