#include <bits/stdc++.h>
using namespace std;
const long double EPS=1e-10;

template<typename T>
struct BinaryIndexedTree{
    vector<T> dat;
    BinaryIndexedTree(int n):dat(n+1,0){}
    void add(int i,T x){
        if (i==0) return;
        for (;i<=dat.size();i+=(i&-i)) dat[i]+=x;
    }
    T sum(int i){
        T res=0;
        for (;i>0;i-=(i&-i)) res+=dat[i];
        return res;
    }
    T query(int l,int r){ //[l,r)
        return sum(r-1)-sum(l-1);
    }
    int lower_bound(T x){
        if (x<=0) return 0;
        int lb=0,r=1;
        while(r<dat.size()) r<<=1;
        for (;r>0;r>>=1){
            if (lb+r<dat.size()&&dat[lb+r]<x){
                x-=dat[lb+r]; lb+=r;
            }
        }
        return lb+1;
    }
    void add0(int i,T x){add(i+1,x);}
    T sum0(int i){return sum(i+1);}
    T query0(int l,int r){return sum(r)-sum(l);}
};

template<typename T> vector<T> compress(vector<T> v){
    sort(v.begin(),v.end());
    v.erase(unique(v.begin(),v.end()),v.end());
    return v;
}

template<typename T> vector<int> dict(vector<T> v){
    vector<T> cv=compress(v);
    int n=v.size();
    vector<int> res(n);
    for (int i=0;i<n;++i)
        res[i]=lower_bound(cv.begin(),cv.end(),v[i])-cv.begin();
    return res;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N; cin >> N;
    struct Line{
        long double A,B,C;
        Line(long double A,long double B,long double C):A(A),B(B),C(C){}
    };
    vector<Line> ls;
    for (int i=0;i<N;++i){
        long double A,B,C; cin >> A >> B >> C;
        ls.emplace_back(A,B,C);
    }
    vector<long double> ans(2);
    int half=(N*(N-1)/2+1)/2;
    for (int _=0;_<2;++_){
        sort(ls.begin(),ls.end(),[](Line a,Line b){
            return a.A/a.B<b.A/b.B;
        });
        vector<long double> X(N);
        set<long double> posX,negX;
        long double lb=-1e9,ub=1e9;
        while(ub-lb>EPS){
            long double mid=(ub+lb)/2.0;
            int cnt=0,sum=0;
            for (int i=0;i<N;++i){
                long double A=ls[i].A,B=ls[i].B,C=ls[i].C;
                X[i]=C/B-A/B*mid;
            }
            vector<int> cX=dict(X);
            BinaryIndexedTree<int> pos(N+1),neg(N+1),neg0(N+1);
            for (int i=N-1;i>=0;--i){
                if (ls[i].B>0){
                    cnt+=pos.sum0(cX[i]);
                    cnt+=neg.sum0(cX[i]);
                    pos.add0(cX[i],1);
                } else {
                    cnt+=neg.sum0(cX[i]);
                    neg.add0(cX[i],1);
                }
            }
            for (int i=0;i<N;++i){
                if (ls[i].B>0) cnt+=sum-(cX[i]>0?neg0.sum0(cX[i]-1):0);
                else neg0.add0(cX[i],1),++sum;
            }
            (cnt>=half?ub:lb)=mid;
