	scanf("%d", &n);
	REP(i, n) scanf("%d%d%d", &lines[i].a, &lines[i].b, &lines[i].c);
	double x = solve();
	REP(i, n) swap(lines[i].a, lines[i].b);
	double y = solve();
	printf("%.15lf %.15lf\n", x, y);
}

int main() {
	run();
	return 0;
}

