  for (; x <= N; x += x & -x)
    sum[x] += v;
}

int ask(int x) {
  int res = 0;
  for (; x; x -= x & -x)
    res += sum[x];
  return res;
}

i64 calc(double mid) {

  for (int i = 1; i <= N; ++i) {
    P[i] = (C[id[i]] - mid * A[id[i]]) / B[id[i]];
    idx[i] = i;
  }

  sort(idx + 1, idx + N + 1, cmp2);

  memset(sum, 0, sizeof sum);
  i64 num = 0;

  for (int i = 1; i <= N; ++i) {
    num += ask(N - idx[i] + 1);
    update(N - idx[i] + 1, 1);
  }

  return num;
}

double work() {
  double l = -300000000, r = 300000000;

  for (int i = 1; i <= N; ++i)
    id[i] = i;
  sort(id + 1, id + N + 1, cmp);

  i64 tot = 1LL * N * (N - 1) / 2;

  for (int i = 0; i <= 70; ++i) {
    double mid = (l + r) / 2;
    if (calc(mid) * 2 < tot) l = mid;
    else r = mid;
  }
  return l;
}

