class BIT{
    //index : 1-based
    public:
        vector<ll> bit;
        ll M;

        BIT(ll M):
            bit(vector<ll>(M + 1, 0)), M(M) {}
        ll sum(ll i){
            ll s = 0;
            while (i > 0) {
                s += bit[i];
                i -= i & (-i);
            }
            return s;
        }

        void add(ll i, ll x){
            while (i <= M){
                bit[i] += x;
                i += i & -i;
            }
        }
};  

const ll MAX_N = 4e4;
