	// log N
	double high,low;
	high = 1e4;low=-1e4;
	REP(i, 70){
		double mid = (high+low)/2;
		// N log N
		int x=countLeft(mid, false);
		// go x==target
		if(x < target) low = mid;
		else high = mid;
	}

	double ansx = low;
	high = 1e4;low=-1e4;
	REP(i, 70){
		double mid = (high+low)/2;
		int x=countLeft(mid, true);
		// go x==target
		if(x < target) low = mid;
		else high = mid;
	}
	double ansy = low;

	cout << fixed << setprecision(9) << ansx << " " << ansy << endl;
}

