void add(int p, int x) {
	while (p <= 100008) { bit[p] += x; p += (p&-p); }
}
void zero() {
	for (int i = 0; i < 100009; i++)bit[i] = 0;
}
int sum(int p) {
	int s = 0;
	while (p >= 1) { s += bit[p]; p -= (p&-p); }
	return s;
}
int search(double p) {
	vector<pair<double, int>>T; vector<double>E;
	for (int i = 0; i < F.size(); i++) {
		double V = (get<2>(F[i]) - get<0>(F[i])*p) / get<1>(F[i]);
		double W = get<0>(F[i]) / get<1>(F[i]);
		E.push_back(W);
	}
	sort(E.begin(), E.end());
	for (int i = 0; i < F.size(); i++) {
		double V = (get<2>(F[i]) - get<0>(F[i])*p) / get<1>(F[i]);
		double W = get<0>(F[i]) / get<1>(F[i]);
		int pos1 = lower_bound(E.begin(), E.end(), W) - E.begin();
		T.push_back(make_pair(V, pos1 + 1));
	}
	sort(T.begin(), T.end());
	int ret = 0;
	for (int i = 0; i < T.size(); i++) {
		ret += sum(T[i].second);
		add(T[i].second, 1);
	}
	return ret;
}
