double x(int i, int j) {
    return double(b[i] * c[j] - c[i] * b[j]) / (a[i] * b[j] - b[i] * a[j]);
}

double y(int i, int j) {
    return double(a[j] * c[i] - c[j] * a[i]) / (a[i] * b[j] - b[i] * a[j]);
}

double get_x(int n, int m) {
    m++;

    double minx = -1e10, maxx = 1e10;

    while (maxx - minx > 1e-10) {
        double X = (maxx + minx) / 2;
        double ans = minx;

        int cnt = 0;

        rep (i, n) {
            rep (j, i) {
                double xx = x(i, j);
                if (xx < X) {
                    cnt++;
                    chmax(ans, xx);
                }
            }
        }

        if (cnt == m)
            return ans;
        if (cnt < m)
            minx = max(ans, X);
        else
            maxx = min(ans, X);
    }

    return maxx;
}

double get_y(int n, int m) {
    m++;

    double minx = -1e10, maxx = 1e10;

    while (maxx - minx > 1e-10) {
        double X = (maxx + minx) / 2;
        double ans = minx;

