        rep (i, n) {
            rep (j, i) {
                double xx = y(i, j);
                if (xx < X) {
                    cnt++;
                    chmax(ans, xx);
                }
            }
        }

        if (cnt == m)
            return ans;
        if (cnt < m)
            minx = max(ans, X);
        else
            maxx = min(ans, X);
    }
    return maxx;
}

