    pair<double, double> intersection(double a1, double b1, double c1, double a2, double b2, double c2){
        double x = det(c1, b1, c2, b2) / det(a1, b1, a2, b2);
        double y = det(a1, c1, a2, c2) / det(a1, b1, a2, b2);
        return mp(x, y);
    }

    void solve1(){
        //O(N^2)でよければこれで楽勝
        vector<double> x, y;
        REP(i, N){
            FOR(j, i + 1, N){
                pair<double, double> z = intersection(A[i], B[i], C[i], A[j], B[j], C[j]);
                x.pb(z.first); y.pb(z.second);
            }
        }
        SORT(x); SORT(y);
        ll M = N * (N - 1) / 2;
        printf("%f %f\n", x[(M-1)/2], y[(M-1)/2]);
    }


class BIT{
    //index : 1-based
    public:
        vector<ll> bit;
        ll M;

        BIT(ll M):
            bit(vector<ll>(M + 1, 0)), M(M) {}
        ll sum(ll i){
            if (!i) return 0;
            return bit[i] + sum(i - (i & -i));
        }

        void add(ll i, ll x){
            if (i > M) return;
            bit[i] += x;
            add(i + (i & -i), x);
        }
};  

ll inversion(vector<double> x){
    //vector xの転倒数を求める
    BIT t(N);
    vector<pair<double, ll>> y;
    ll ans = 0;
    REP(i, x.size()){
        y.pb(mp(x[i], i));        
    }
    SORT(y);
    REP(i, x.size()){
        ans += y[i].second - t.sum(y[i].second + 1);
        t.add(y[i].second + 1, 1);
    }
    return ans;
}

ll search_x(double x){
    vector<pair<double, double>> ys;
    REP(i, N){
        ys.pb(mp(-A[i] / B[i], (C[i] - A[i] * x) / B[i]));
    }
    SORT(ys);
    vector<double> y;
    REP(i, N){
        y.pb(ys[i].second);
    }
    return inversion(y);
}

ll search_y(double y){
    vector<pair<double, double>> xs;
    REP(i, N){
        xs.pb(mp(-B[i] / A[i], (C[i] - B[i] * y) / A[i]));
    }
    SORT(xs);
    vector<double> x;
    REP(i, N){
        x.pb(xs[i].second);
    }
    return inversion(x);
}


int main(){
    scanf("%lld", &N);
    REP(i, N) {
        scanf("%lf%lf%lf", &A[i], &B[i], &C[i]);
    }
    double x_min = -INF, x_max = INF;
    double y_min = -INF, y_max = INF;
    ll M = N * (N - 1) / 2;

    while(x_max - x_min > EPS){
        double xmid = (x_max + x_min) / 2;
        if (search_x(xmid) <= M / 2) x_max = xmid;
        else x_min = xmid;
    }
    while(y_max - y_min > EPS){
        double ymid = (y_max + y_min) / 2;
        if (search_y(ymid) <= M / 2) y_max = ymid;
        else y_min = ymid;
    }
    printf("%.10lf %.10lf\n", x_min, y_min);

//    solve1();
}

