struct BIT {
	vector<int> bit;
	void resize(int N) {
		bit.assign(N, 0);
	}
	void add(int i, int j) {
		i++;
		while (i < bit.size()) {
			bit[i] += j;
			i += i&-i;
		}
	}
	int sum(int i) {
		int r = 0;
		i++;
		while (i) {
			r += bit[i];
			i -= i&-i;
		}
		return r;
	}
	int rng(int lef, int rig) {
		int F = sum(rig);
		if (lef) {
			F -= sum(lef - 1);
		}
		return F;
	}
};
BIT b;

map<long double, int> mpp;
int ord[MAX];

int cnt_lef(long double X) {
	b.resize(n + 1);
	mp.clear();
	for (int i = 0; i < n; i++) {
		mp[A[i] * X + B[i]].push_back(ord[i]);
	}
	int same = 0;
	int rig = 0;
	for (auto it = mp.rbegin(); it != mp.rend(); it++) {
		same += (*it).second.size()*((*it).second.size() - 1) / 2;
		vector<long double> &V = (*it).second;
		for (auto a : V) {
			rig += b.sum(a - 1);
			b.add(a, 1);
		}
	}
	int lef = n*(n - 1) / 2 - same - rig;
	return rig - lef;
}

double solve() {
	mpp.clear();
	for (int i = 0; i < n; i++) {
		mpp[A[i]] = 0;
	}
	int cc = 0;
	for (auto it = mpp.begin(); it != mpp.end(); it++) {
		(*it).second = cc;
		cc++;
	}
	for (int i = 0; i < n; i++) {
		ord[i] = mpp[A[i]];
	}
	double mint = -199999999;
	double maxt = 199999999;
	double EP = 1e-9;
	while (mint + EP < maxt) {
		double mid = (mint + maxt) / 2.0;
		int flag = cnt_lef(mid);
		if (flag <= 0) {
			maxt = mid;
		}
		else {
			mint = mid;
		}
	}
	return mint;
}
