template<class T> struct Fenwick {
    int n;
    T* d;
    Fenwick() : n(0), d(NULL) {}
    Fenwick(int n_) : n(n_) {
	d = new T[n_]();
    }
    Fenwick(const Fenwick &y) : n(y.n) {
	d = new T[n];
	memcpy(d, y.d, sizeof (T) * n);
    }
    ~Fenwick() {
	delete[] d; d = NULL;
	n = 0;
    }
    friend void swap(Fenwick &x, Fenwick &y) {
	swap(x.n, y.n); swap(x.d, y.d);
    }
    Fenwick& operator=(Fenwick y) {
	swap(*this, y);
	return *this;
    }
    inline void add(int i, const T &x) {
	for (; i<n; i|=i+1) d[i] += x;
    }
    inline T sum(int r) {
	T s = T();
	for (; r; r&=r-1) s += d[r-1];
	return s;
    }
    T sum(int l, int r) {
	return sum(r) - sum(l);
    }
    int lower_bound(const T &x) { // sum(ret) < x <= sum(ret+1);
	if (n == 0) return 0;
	int i = 0; T s = T();
	for (int k=1<<__lg(n); k; k>>=1) {
	    if (i+k <= n && s + d[i+k-1] < x) {
		i += k; s += d[i-1];
	    }
	}
	return i;
    }
    int upper_bound(const T &x) { // sum(ret) <= x < sum(ret+1);
	if (n == 0) return 0;
	int i = 0; T s = T();
	for (int k=1<<__lg(n); k; k>>=1) {
	    if (i+k <= n && !(x < s + d[i+k-1])) {
		i += k; s += d[i-1];
	    }
	}
	return i;
    }
};

const int MAXN = 40011;
int N;
double P[MAXN], Q[MAXN];
pair<double, int> H[MAXN];
int rnk[MAXN];

bool ok(double x) {
    REP (i, N) H[i] = make_pair(P[i] * x + Q[i], i);
    sort(H, H+N);
    Fenwick<int> F(N);
    LL cnt = 0;
    REP (i, N) {
	int r = rnk[H[i].second];
	cnt += F.sum(r);
	F.add(r, 1);
    }
    return cnt*2 >= (LL)N*(N-1)/2;
}

double solve() {
    REP (i, N) H[i] = make_pair(P[i], i);
    sort(H, H+N);
    REP (i, N) rnk[H[i].second] = i;

    double lo = -1, hi = 1;
    while (!ok(hi)) {
	lo = hi;
	hi *= 2;
    }
    while (ok(lo)) {
	hi = lo;
	lo *= 2;
    }
    REP (t, 50) {
	double mid = (lo + hi) / 2;
	(ok(mid)? hi: lo) = mid;
    }
    return hi;
}

