#define pb push_back
typedef long long ll;
typedef pair<int, int> i_i;
typedef pair<double, int> d_i;

struct bit {
	vector<ll> v;
	bit(int n) : v(n + 1) {}
	ll sum(int i) {
		ll res = 0;
		for (; i > 0; i -= i & -i) res += v[i];
		return res;
	}
	void add(int i, ll x) {
		for (i++; i < v.size(); i += i & -i) v[i] += x;
	}
	int lower_bound(ll x) {
		if (x <= 0) return 0;
		int res = 0;
		for (int i = 1 << 24; i > 0; i >>= 1)
			if (res + i < v.size() && v[res + i] < x) {
				res += i; x -= v[res];
			}
		return res + 1;
	}
};

double solve(int N, vector<int> a, vector<int> b, vector<int> c) {
	ll tot = (ll)N * (N - 1) / 2;
	vector<d_i> di(N);
	rep(i, N) di[i] = d_i((double)a[i] / b[i], i);
	sort(di.begin(), di.end());
	vector<int> _a(N), _b(N), _c(N);
	rep(i, N) {
		int j = di[i].second;
		_a[i] = a[j], _b[i] = b[j], _c[i] = c[j];
	}
	a = _a, b = _b, c = _c;
	double lb = -1e9, ub = 1e9;
	rep(t, 100) {
		double x0 = (lb + ub) / 2;
		vector<d_i> di(N);
		rep(i, N) di[i] = d_i((c[i] - a[i] * x0) / b[i], i);
		sort(di.begin(), di.end());
		bit bt(N);
		ll sum = 0;
		rep(j, N) {
			int i = di[j].second;
			sum += j - bt.sum(i);
			bt.add(i, 1);
		}
		if (sum * 2 >= tot) ub = x0;
		else lb = x0;
	}
	return lb;
}

