struct bit {
    int n;
    int* dat;

    bit(int _n) {
        n = 1;
        while(n < _n) n *= 2;
        dat = new int[n + 1];
        fill(dat + 1, dat + n + 1, 0);
    }

    void update(int i, int x) {
        while(i <= n) {
            dat[i] += x;
            i += i & -i;
        }
    }

    int query(int i) {
        int res = 0;
        while(i > 0) {
            res += dat[i];
            i -= i & -i;
        }
        return res;
    }
};

struct line {
    double a, b, c;

    bool operator<(const line& rhs) const {
        return a / b < rhs.a / rhs.b;
    }
};

signed main() {
    int n;
    cin >> n;
    line* lines = new line[n];
    rep(i, n) {
        double a, b, c;
        cin >> a >> b >> c;
        lines[i] = {a, b, c};
    }
    bit bt(n);
    DIP* dip = new DIP[n];

    sort(lines, lines + n);

    double left = -1e8*2, right = 1e8*2;
    while(right - left > EPS) {
        double mid = (left + right) / 2;
        rep(i, n) {
            line l = lines[i];
            dip[i] = DIP(-l.a / l.b * mid + l.c / l.b, i);
        }
        sort(dip, dip + n);

        fill(bt.dat + 1, bt.dat + bt.n + 1, 0);
        ll res = 0;
        rep(i, n) {
            res += i - bt.query(dip[i].second + 1);
            bt.update(dip[i].second + 1, 1);
        }

        if(res >= ((ll)n * (n - 1) + 2) / 4) right = mid;
        else left = mid;
    }
    double x = left;

    rep(i, n) lines[i] = {lines[i].b, lines[i].a, lines[i].c};
    sort(lines, lines + n);

    left = -1e8*2, right = 1e8*2;
    while(right - left > EPS) {
        double mid = (left + right) / 2;
        rep(i, n) {
            line l = lines[i];
            dip[i] = DIP(-l.a / l.b * mid + l.c / l.b, i);
        }
        sort(dip, dip + n);

        fill(bt.dat + 1, bt.dat + bt.n + 1, 0);
        ll res = 0;
        rep(i, n) {
            res += i - bt.query(dip[i].second + 1);
            bt.update(dip[i].second + 1, 1);
        }

        if(res >= ((ll)n * (n - 1) + 2) / 4) right = mid;
        else left = mid;
    }

    printf("%.10f %.10f\n", x, left);
}

