llint tensort(vector<lldo>& in){
	//転倒数を計算しながらソートします
	llint ans=0;
	llint i,j,n=in.size(),gen=1;
	vector<lldo>iti(n);
	for(gen=1;gen<n;gen*=2){
		llint now=0;
		for(i=0;i<n;i+=gen*2){//i,i+gen
			if(i!=now){cout<<"de";}
			int hid=i,mig=i+gen,end=min(n,i+gen+gen);
			if(n<=i+gen){for(j=i;j<n;j++){iti[j]=in[j];}}
			while(now!=end){
				if(mig==end){iti[now]=in[hid];now++;hid++;}//左
				else if(hid==i+gen){iti[now]=in[mig];now++;mig++;}//右
				else if(in[hid]<in[mig]){iti[now]=in[hid];now++;hid++;}//左
				else{ans+=i+gen-hid;iti[now]=in[mig];now++;mig++;}//右
			}
		}
		swap(in,iti);
	}
	return ans;
}
lldo solve(vector<tuple<int,int,int>> a){
	llint n,i;n=a.size();
	vector<tuple<lldo,lldo>>car(n);//y=ax+b
	for(i=0;i<n;i++){
		get<0>(car[i])=(lldo)-get<0>(a[i])/(lldo)get<1>(a[i]);
		get<1>(car[i])=(lldo)get<2>(a[i])/(lldo)get<1>(a[i]);
	}
	sort(car.begin(),car.end());//xを無限大に飛ばしたときの車の配置
	lldo bmax=big,bmin=-big;
	//改良型にぶたん
	//-1見る
	//1見る

	for(int q=0;q<45;q++){
		lldo gen=(bmax+bmin)/2;
		if(bmin+eps<-1&&-1<bmax-eps){gen=-1;}
		else if(bmin+eps<1&&1<bmax-eps){gen=1;}
		else if(q<10&&1<=bmin){gen=sqrt(bmax*bmin);}
		else if(q<10&&bmax<=-1){gen=-sqrt(bmax*bmin);}
		vector<lldo> ima(n);
		for(i=0;i<n;i++){ima[i]=get<0>(car[i])*gen+get<1>(car[i]);}
		llint beet=tensort(ima);
		if(beet<=(n*(n-1)/4)){bmax=gen;}
		else{bmin=gen;}
	}
	return (bmin+bmax)/2;
}
int main(void){
	ios::sync_with_stdio(false);
	llint n,i;
	cin>>n;
	vector<tuple<int,int,int>>a(n);
	for(i=0;i<n;i++){cin>>get<0>(a[i])>>get<1>(a[i])>>get<2>(a[i]);}
	cout<<setprecision(20)<<solve(a);
	for(i=0;i<n;i++){swap(get<0>(a[i]),get<1>(a[i]));}
	cout<<" "<<solve(a)<<endl;
	return 0;
}

