using namespace std;
typedef pair<double, double> line;
#define point line
#define fi first
#define se second
int n;
double a[50005], b[50005], c[50005];
line l[50005];
bool cmp(line x,line y){
	if (x.fi * y.fi < 0) return x.fi <= 0;
	return x.fi >= y.fi;
}
double resx, resy;
vector <point> lst;
int fw[50005];
int fw_get(int x){
	int res = 0; for(;x;x-=x&-x) res+= fw[x]; return res;
}
void fw_upd(int x){
	for(;x<=n;x+=x&-x) fw[x] ++;
}
double solve(){
	sort(l+1,l+n+1,cmp);
	double L = -1e12, R = 1e12;
	//for(int i=1;i<=n;i++) cout << l[i].fi << ' ' << l[i].se << endl;
	for(int _time=0;_time<100;_time++){
		double divide_line = (L+R)/2;
		//cout << "div " << divide_line << endl;
		lst.clear();
		fill(fw,fw+n+5,0);
		for(int i=1;i<=n;i++)
			lst.push_back(point((divide_line - l[i].se) / l[i].fi, i));
		sort(lst.begin(), lst.end());
		int cnt = 0;
		for(int i=0;i<n;i++)
			cnt += fw_get(lst[i].se),
			fw_upd(lst[i].se);
			//cout << lst[i].fi << ' ' << lst[i].se << ' ';
			//cout << endl;
		// cnt equals !inverse

		if (cnt <= (n * (n-1) / 2) / 2) 
			L = divide_line;
		else
			R = divide_line;
		//cout << cnt << endl;
	}
	return L;
}
int main(){
	iostream::sync_with_stdio(0);
	cin >> n;
	for(int i=1;i<=n;i++)
		cin >> a[i] >> b[i] >> c[i], c[i] = -c[i]; // ax + by + c = 0

	for(int i=1;i<=n;i++)
		l[i].fi = - a[i] / b[i],
		l[i].se = - c[i] / b[i];
	resy = solve();
	for(int i=1;i<=n;i++)
		l[i].fi = - b[i] / a[i],
		l[i].se = - c[i] / a[i];
	resx = solve();
	cout << fixed << setprecision(10) << resx << ' ' << resy;
}

