};

struct Point {
    double x, y;
};

int main() {
    std::ios::sync_with_stdio(false);
    int n;cin >> n;
    vector<D> d(n);
    for(int i=0;i<n;i++){
        int a, b, c;cin >> a >> b >> c;
        d[i] = {a, b, c};
    }
    vector<Point> p;
    for(int i=0;i<n;i++){
        for(int j=i+1;j<n;j++){
            double y;
            if(d[i].a*d[j].c-d[j].a*d[i].c == 0){
                y = 0;
            }else{
                y = double(d[i].a*d[j].c-d[j].a*d[i].c)/double(d[i].a*d[j].b-d[j].a*d[i].b);
            }

            double x = double(d[i].c-d[i].b*y)/double(d[i].a);
            p.push_back({x, y});
        }
    }
    int m = p.size();
    sort(p.begin(), p.end(), [](Point &p1, Point &p2){return p1.x < p2.x;});
    double maxx = 0;
    for(int i=0;i<m;i++){
        maxx += p[i].x - p[0].x;
    }
    double nowx = maxx;
    double ansx = p[0].x;
    for(int i=1;i<m;i++){
        double dx = p[i].x - p[i-1].x;
        nowx += dx*i - dx*(m-i);
        if(nowx < maxx){
            maxx = nowx;
            ansx = p[i].x;
        }
    }

    sort(p.begin(), p.end(), [](Point &p1, Point &p2){return p1.y < p2.y;});
    double maxy = 0;
    for(int i=0;i<m;i++){
        maxy += p[i].y - p[0].y;
    }
    double nowy = maxy;
    double ansy = p[0].y;
    for(int i=1;i<m;i++){
        double dy = p[i].y - p[i-1].y;
        nowy += dy*i - dy*(m-i);
        if(nowy < maxy){
            maxy = nowy;
            ansy = p[i].y;
        }
    }
    printf("%0.10lf %0.10lf\n", ansx, ansy);
    return 0;
}

