{
    ll n; llin(n);
    V<t3> abclist; llinl3(abclist, n);

    double x = solve(abclist, n, 0);
    double y = solve(abclist, n, 1);

    printf("%5.15lf %5.15lf\n", x, y);

    return 0;
}

