constexpr int INF = 1 << 29;
constexpr int MOD = 1000000007;
typedef long long ll;
typedef unsigned long long ull;

constexpr int dx[4] = {1, 0, -1, 0};
constexpr int dy[4] = {0, 1, 0, -1};

struct Line {
	double a, b, c;
};

struct BIT {
	int N;
	vector<int> bit;
	BIT(int n) : N(n), bit(N + 1){}
	void add(int a, int w) {
		for(int x = a; x < N; x |= x + 1) {
			bit[x] += w;
		}
	}
	int sum(int a) {
		int ret = 0;
		for(int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) {
			ret += bit[x];
		}
		return ret;
	}
};

ll getTransNum(vector<int> &r) {
	BIT bit(r.size());
	ll ret = 0;
	for(int i = 0; i < r.size(); i++) {
		ret += i - bit.sum(r[i]);
		bit.add(r[i], 1);
	}
	return ret;
}

bool ok(vector<Line> &L, double c, bool vertical) {
	vector<pair<double, int>> L_c;
	if (vertical) {
		for (int i = 0; i < L.size(); i++) {
			// Ax+By=C
			// By=C-Ax
			// y=(C-Ax)/B
			double y = (L[i].c - L[i].a * c) / L[i].b;
			L_c.push_back(mp(y, i));
		}
	} else {
		for (int i = 0; i < L.size(); i++) {
			// Ax+By=C
			// Ax=C-By
			// x=(C-By)/A
			double x = (L[i].c - L[i].b * c) / L[i].a;
			L_c.push_back(mp(x, i));
		}
	}

	sort(L_c.begin(), L_c.end());
	vector<int> r;
	for (int i = 0; i < L_c.size(); i++) {
		r.push_back(L_c[i].second);
		//cout << i << ": (" << L_c[i].first << ", " << L_c[i].second << ")" << endl; 
	}

	ll n = getTransNum(r);

	return n >= (L.size() * (L.size() - 1) / 4 + L.size() % 2);
}

