struct BIT{//Be careful! 1-indexed!
	int size;
	vector<int> bit;//Mind overflow.

	BIT(int n){
		size=n;
		bit.resize(size+1);
		fill(bit.begin(),bit.end(),0);
	}

	void update(int k,int a){
		while(k<=size){
			bit[k]+=a;
			k=(k|(k-1))+1;
		}
	}

	int s(int k){//Caution! It may be necessary to substitute int for long long.
		int r=0;//Caution! It may be necessary to substitute int for long long.
		while(k>0){
			r+=bit[k];
			k=k&(k-1);
		}
		return r;
	}
};

