struct segtree
{
	static const int SIZE = 1 << 16;
	int data[2 * SIZE];

	segtree() {
		for (int i = 0; i < 2 * SIZE; ++i) data[i] = 0;
	}

	void incl(int p) {
		p += SIZE;
		while (p) {
			data[p] += 1;
			p >>= 1;
		}
	}

	int query(int L, int R) {
		L += SIZE;
		R += SIZE;
		int ret = 0;
		while (L < R) {
			if (L & 1) ret += data[L++];
			if (R & 1) ret += data[--R];
			L >>= 1; R >>= 1;
		}
		return ret;
	}
};

