i64 solve2(double t)
{
	vector<pair<double, int> > fst;
	for (int i = 0; i < N; ++i) {
		fst.push_back({ (double)A[i] / B[i], i });
	}
	sort(fst.begin(), fst.end());

	vector<pair<double, int> > aft;
	for (int i = 0; i < N; ++i) {
		aft.push_back({ (C[i] - A[i] * t) / B[i], i });
	}
	sort(aft.begin(), aft.end());

	return inv(trans(fst), trans(aft));
}

double solve()
{
	double left = -1e9, right = 1e9;
	int tot = (1+  N * (N - 1) / 2) / 2;
	for (int i = 0; i < 70; ++i) {
		double mid = (left + right) / 2;

		if (solve2(mid) < tot) {
			left = mid;
		} else {
			right = mid;
		}
	}
	return left;
}

