    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());

    double lo_x = xs[SAMPLES / 2 - SAMPLES / 1000];
    double hi_x = xs[SAMPLES / 2 + SAMPLES / 1000];
    double lo_y = ys[SAMPLES / 2 - SAMPLES / 1000];
    double hi_y = ys[SAMPLES / 2 + SAMPLES / 1000];

    if (n < 1000) {
        lo_x = xs.front();
        hi_x = xs.back();
        lo_y = ys.front();
        hi_y = ys.back();
    }
    // cerr << lo_x << ", " << hi_x << endl;
    // cerr << lo_y << ", " << hi_y << endl;

    int lo_cnt_x = 0;
    int lo_cnt_y = 0;

    static int fs[40000];
    for (int i = 0; i < n; i++) {

#pragma clang loop vectorize(enable) interleave(enable)
        for (int j = i + 1; j < n; j++) {
            const auto p = cross(vs[i], vs[j]);

            if (p.first < lo_x)
                lo_cnt_x++;
            if (p.second < lo_y)
                lo_cnt_y++;

            fs[j] = (lo_x < p.first && p.first < hi_x ? 1 : 0) + (lo_y < p.second && p.second < hi_y ? 2 : 0);
        }

        for (int j = i + 1; j < n; j++) {
            if (fs[j] & 1) {
                rxs.push_back(cross(vs[i], vs[j]).first);
            }
            if (fs[j] & 2) {
                rys.push_back(cross(vs[i], vs[j]).second);
            }
        }
    }

    int nn = (n * (n - 1) / 2 + 1) / 2;
    // cerr << lo_cnt_x << " + " << rxs.size() << " = " << lo_cnt_x + rxs.size() << " ~ " << nn << endl;
    // cerr << lo_cnt_y << " + " << rys.size() << " = " << lo_cnt_y + rys.size() << " ~ " << nn << endl;

    assert(lo_cnt_x < nn && lo_cnt_x + rxs.size() >= nn);
    assert(lo_cnt_y < nn && lo_cnt_y + rys.size() >= nn);

    sort(rxs.begin(), rxs.end());
    sort(rys.begin(), rys.end());

    printf("%.12f %.12f\n", rxs[nn - 1 - lo_cnt_x], rys[nn - 1 - lo_cnt_y]);

    return 0;
}

