	sort(L_y.begin(), L_y.end(), [](Line &lhs, Line &rhs){return lhs.b / lhs.a < rhs.b / rhs.a;});

	double ans_x, ans_y;
	double a = -1e30;
	double b = 1e30;
	for (int i = 0; i < 200; i++) {
		double c = (a + b) / 2;
		if (ok(L_x, c, true)) {
			b = c;
		} else {
