#define EPS 0.0000000001

using namespace std;
using ll = long long;
using P = pair<int, int>;
using DP = pair<double, double>;
using ILP = pair<int, ll>;
using DIP = pair<double, int>;

struct bit {
    int n;
    int* dat;

    bit(int _n) {
        n = 1;
        while(n < _n) n *= 2;
        dat = new int[n + 1];
        fill(dat + 1, dat + n + 1, 0);
    }

    void update(int i, int x) {
        while(i <= n) {
            dat[i] += x;
            i += i & -i;
        }
    }

    int query(int i) {
        int res = 0;
        while(i > 0) {
            res += dat[i];
            i -= i & -i;
        }
        return res;
    }
};

struct line {
    double a, b, c;

    bool operator<(const line& rhs) const {
        return a / b < rhs.a / rhs.b;
    }
};

signed main() {
    int n;
    cin >> n;
    line* lines = new line[n];
    rep(i, n) {
        double a, b, c;
        cin >> a >> b >> c;
        lines[i] = {a, b, c};
    }

    sort(lines, lines + n);

    double left = -INF, right = INF;
    while(right - left > EPS) {
        double mid = (left + right) / 2;
        DIP* dip = new DIP[n];
        rep(i, n) {
            line l = lines[i];
            dip[i] = DIP(-l.a / l.b * mid + l.c / l.b, i);
        }
        sort(dip, dip + n);

        bit bt(n);
        ll res = 0;
        rep(i, n) {
            res += i - bt.query(dip[i].second + 1);
            bt.update(dip[i].second + 1, 1);
        }

        if(res >= ((ll)n * (n - 1) + 2) / 4) right = mid;
        else left = mid;
    }
    double x = left;

    rep(i, n) lines[i] = {lines[i].b, lines[i].a, lines[i].c};
    sort(lines, lines + n);

    left = -INF, right = INF;
    while(right - left > EPS) {
        double mid = (left + right) / 2;
        DIP* dip = new DIP[n];
        rep(i, n) {
            line l = lines[i];
            dip[i] = DIP(-l.a / l.b * mid + l.c / l.b, i);
        }
        sort(dip, dip + n);

        bit bt(n);
        ll res = 0;
        rep(i, n) {
            res += i - bt.query(dip[i].second + 1);
            bt.update(dip[i].second + 1, 1);
        }

        if(res >= ((ll)n * (n - 1) + 2) / 4) right = mid;
        else left = mid;
    }

    printf("%.10f %.10f\n", x, left);
}

