//!==============================================================================================!//
template <std::size_t L>
class WaveletMatrix
{
public:
    using T = unsigned long long;
    template <typename InIt>
    WaveletMatrix(const InIt first, const InIt last) : sz(std::distance(first, last))
    {
        std::vector<bool> b(sz);
        std::vector<T> v(first, last);
        for (std::size_t i = 0, j = L - 1; i < L; i++, j--) {
            std::vector<T> z, o;
            for (std::size_t i = 0; i < sz; i++) { b[i] = (v[i] >> j) & 1, (b[i] ? o : z).push_back(v[i]); }
            table.push_back(FID{b}), v = z, zero.push_back(z.size());
            for (const T e : o) { v.push_back(e); }
        }
    }
    std::size_t noLessThan(std::size_t l, std::size_t r, const T v) const
    {
        assert(l < r);
        std::size_t ans = 0;
        for (std::size_t i = 0, j = L - 1; i < L; i++, j--) {
            const bool b = (v >> j) & 1;
            const std::size_t rl = table[i].rank(l), rr = table[i].rank(r);
            l = (b ? rl + zero[i] : l - rl), r = (b ? rr + zero[i] : r - rr), ans += (b ? 0 : rr - rl);
        }
        return r - l + ans;
    }
    std::size_t lessThan(const std::size_t l, const std::size_t r, const T v) const { return assert(l < r), r - l - noLessThan(l, r, v); }
    std::size_t rangeFreq(const std::size_t l, const std::size_t r, const T vinf, const T vsup) const { return assert(l < r), assert(vinf < vsup), noLessThan(l, r, vinf) - noLessThan(l, r, vsup); }
    std::size_t rank(const std::size_t l, const std::size_t r, const T v) const { return assert(l < r), rangeFreq(l, r, v, v + 1); }
    T quantile(std::size_t l, std::size_t r, std::size_t k) const
    {
        assert(l < r);
        std::size_t ans = 0;
        for (std::size_t i = 0, j = L - 1; i < L; i++, j--) {
            const std::size_t rl = table[i].rank(l), rr = table[i].rank(r);
            const bool b = rr - rl > k;
            l = (b ? rl + zero[i] : l - rl), r = (b ? rr + zero[i] : r - rr), k += (b ? 0 : k -= rr - rl), ans |= ((std::size_t)b << j);
        }
        return ans;
    }

private:
    class FID
    {
    private:
        using B = unsigned long long;
        static constexpr std::size_t BS = sizeof(B) * 8;
        const std::size_t sz;
        std::vector<B> data;
        std::vector<std::size_t> large;

    public:
        FID(const std::vector<bool>& b) : sz(b.size()), data((sz + BS) / BS, 0), large((sz + BS) / BS, 0)
        {
            std::size_t one = 0;
            for (std::size_t i = 0; i < sz; i++) {
                data[i / BS] |= ((B)b[i] << (i % BS)), one += b[i];
                if (i % BS == BS - 1) { large[(i + 1) / BS] = one; }
            }
        }
        bool operator[](const std::size_t n) const { return (data[n / BS] >> (n % BS)) & 1; }
        std::size_t rank(const std::size_t n) const { return large[n / BS] + (n % BS == 0 ? 0 : popCount(data[n / BS] & ((1ULL << (n % BS)) - 1))); }
    };
    const std::size_t sz;
    std::vector<std::size_t> zero;
    std::vector<FID> table;
};
