    const int CP = N * (N - 1) / 2;
    auto bin = [&]() {
        ld inf = -1e18, sup = 1e18;
        std::vector<int> ind(N);
        std::iota(ind.begin(), ind.end(), 0);
        std::sort(ind.begin(), ind.end(), [&](const int i, const int j) { return (C[i] - A[i] * inf) / B[i] < (C[j] - A[j] * inf) / B[j]; });
        for (int t = 0; t < 100; t++) {
            const ld mid = (inf + sup) / 2;
            std::vector<int> ord(N);
            std::iota(ord.begin(), ord.end(), 0);
            std::sort(ord.begin(), ord.end(), [&](const int i, const int j) { return (C[ind[i]] - A[ind[i]] * mid) / B[ind[i]] < (C[ind[j]] - A[ind[j]] * mid) / B[ind[j]]; });
            WaveletMatrix<18> wm(ord.begin(), ord.end());
            int cp = 0;
            for (int i = 0; i < N; i++) { cp += wm.lessThan(i, N, ord[i]); }
            (cp * 2 < CP ? inf : sup) = mid;
        }
        return inf;
    };
    std::cout << std::fixed << std::setprecision(18) << bin() << " ";
    for (int i = 0; i < N; i++) { std::swap(A[i], B[i]); }
