int cnt_lef(double X) {
	b.resize(n+1);
	mp.clear();
	for (int i = 0; i < n; i++) {
		mp[A[i] * X + B[i]].push_back(ord[i]);
	}
	int same = 0;
	int rig = 0;
	for (auto it = mp.rbegin(); it != mp.rend(); it++) {
		same += (*it).second.size()*((*it).second.size() - 1) / 2;
		vector<double> &V = (*it).second;
		for (auto a : V) {
			rig += b.sum(a-1);
			b.add(a,1);
		}
	}
	int lef = n*(n - 1) / 2 - same - rig;
	return rig - lef;
}

