        double x = (ng + ok) / 2;
        if (check(x)) ok = x;
        else ng = x;
    }
    check(ok);

    //printf(">> %.10f\n", ok);

    printf("%.10f %.10f\n", (sx + sy) / 2, (sx - sy) / 2);
}

