class Bit {
public:
	int n;
	vl bit; // 0-index

	Bit(int _n) { n = _n; bit.resize(n); }

	// [0, i)の和
	ll sum(int i) {
		ll s = 0;
		while (i > 0) {
			s += bit[i - 1];
			i -= i & -i;
		}
		return s;
	}

	//iは0-index
	void add(int i, ll x) {
		i++;
		while (i <= n) {
			bit[i - 1] += x;
			i += i & -i;
		}
	}
};

double solve(int n, vi a, vi b, vi c) {
  rep (i, n) {
    if (b[i] < 0) {
      a[i] *= -1;
      b[i] *= -1;
      c[i] *= -1;
    }
  }

  vector<pair<pii, int>> abc(n);
  rep (i, n) {
    abc[i].first.first = a[i];
    abc[i].first.second = b[i];
    abc[i].second = c[i];
  }
  sort(all(abc), cmp);
  //DEBUG_VEC(abc);
  rep (i, n) {
    a[i] = abc[i].first.first;
    b[i] = abc[i].first.second;
    c[i] = abc[i].second;
  }

  /*
  DEBUG_VEC(a);
  DEBUG_VEC(b);
  DEBUG_VEC(c);
  //*/

  double ng = -inf, ok = inf;
  int threshold = ((n * (n - 1) / 2) + 1) / 2;
  //DEBUG(threshold);
  rep (_, 65) {
    double mid = (ng + ok) / 2;
    vector<double> value(n);
    set<double> st;
    rep (i, n) {
      value[i] = (double)(c[i] - mid*a[i]) / b[i];
      st.insert(value[i]);
    }
    map<double, int> mp;
    int cnt = 0;
    for (auto itr = st.begin(); itr != st.end(); itr++) {
      mp[*itr] = cnt++;
    }

    vi value_int(n);
    vi num(cnt);
    rep (i, n) {
      value_int[i] = mp[value[i]];
      num[value_int[i]]++;
    }

    //DEBUG_VEC(value);
    //DEBUG_VEC(value_int);
    //SegmentTree<int> big(num, f1, f2, 0), small(vi(cnt), f1, f2, 0);
    Bit big(cnt), small(cnt);
    rep (i, cnt) {
      big.add(i, num[i]);
    }

    int smaller = 0;
    rep (i, n) {
      int x = value_int[i];
      big.add(x, -1);

      /*
      rep (i, cnt) {
        cout << big.query(i, i + 1, 0, 0, big.n) << " ";
      }
      cout << endl;
      rep (i, cnt) {
        cout << small.query(i, i + 1, 0, 0, small.n) << " ";
      }
      cout << endl;
      //*/

      smaller += big.sum(x + 1);
      smaller += small.sum(cnt) - small.sum(x);
      //smaller += big.query(0, x + 1, 0, 0, big.n);
      //smaller += small.query(x, small.n, 0, 0, small.n);
      small.add(x, 1);
      //DEBUG(smaller);
    }
    assert((smaller & 1) == 0);
    smaller >>= 1;
    //DEBUG(mid);
    //DEBUG(smaller);
    if (smaller >= threshold) {
      ok = mid;
    }
    else {
      ng = mid;
    }
  }
  return ok;
}

