template <typename T>
pair<T, T> cross(const line& l1, const line& l2)
{
    const int a1 = l1.first.first;
    const int b1 = l1.first.second;
    const int c1 = l1.second;

    const int a2 = l2.first.first;
    const int b2 = l2.first.second;
    const int c2 = l2.second;

    const T x = (T)(c1 * b2 - c2 * b1) / (a1 * b2 - a2 * b1);
    const T y = (T)(c1 * a2 - c2 * a1) / (b1 * a2 - b2 * a1);

    return make_pair(x, y);
}

