ld INF = 1e9;
ll res;

void Merge(vi& S, int left, int mid, int right) {
	int n1 = mid - left, n2 = right - mid;
	vector<int> L(n1 + 1, INF), R(n2 + 1, INF);
	for (int i = 0; i < n1; i++)
		L[i] = S[left + i];
	for (int i = 0; i < n2; i++)
		R[i] = S[mid + i];
	for (int i = 0, j = 0, k = left; k < right; k++) {
		if (L[i] <= R[j]) {
			S[k] = L[i];
			i++;
		}
		else {
			S[k] = R[j];
			j++;
			res += n1 - i;
		}
	}
}

void MergeSort(vi& S, int left, int right) {
	if (left + 1 < right) {
		int mid = (left + right) / 2;
		MergeSort(S, left, mid);
		MergeSort(S, mid, right);
		Merge(S, left, mid, right);
	}
}
int cntrev(vi &v)
{
	res = 0;
	MergeSort(v, 0, v.size());
	return res;
}


