struct line {
	long double a, b, c;
	line() {}
	void input() {
		scanf("%LF %LF %LF", &a, &b, &c);
	}
	long double calx(long double x) {
		return (c - a * x) / b;
	}
	long double caly(long double y) {
		return (c - b * y) / a;
	}
	bool operator < (const line &l) const {
		return a / -b < l.a / -l.b;
	}
} L[N];
bool cmp(line A, line B) {
	return A.b / -A.a < B.b / -B.a;
} 
struct value {
	long double x;
	value() {}
	value(long double x) : x(x) {}
	bool operator < (const value &v) const {
		return fabs(x - v.x) > 1e-10 && x < v.x;
	}
	bool operator == (const value &v) const {
		return fabs(x - v.x) < 1e-10;
	}
} V[N];
int B[N];
inline void Ins(int x) {
	while (x <= n) {
		++B[x];
		x += x & -x;
	}
}
inline int Query(int x) {
	int res = 0;
	while (x) {
		res += B[x];
		x -= x & -x;
	}
	return res;
}
int check(long double x) {
	int res = 0;
	for (int i = 0; i <= n; i++) B[i] = 0;
	for (int i = 1; i <= n; i++) V[i].x = L[i].calx(x);
	sort(V + 1, V + 1 + n);
	//for (int i = 1; i <= n; i++) cout << V[i].x << "/"; cout << endl;
	m = unique(V + 1, V + 1 + n) - V - 1;
	//for (int i = 1; i <= m; i++) cout << V[i].x << "/"; cout << endl;
	for (int i = 1; i <= n; i++) {
		int p = lower_bound(V + 1, V + 1 + m, value(L[i].calx(x))) - V;
		//cout << p << endl;
		res += Query(p);
		Ins(p);
	} 
	return res;
}
int check1(long double y) {
	int res = 0;
	for (int i = 0; i <= n; i++) B[i] = 0;
	for (int i = 1; i <= n; i++) V[i].x = L[i].caly(y);
	sort(V + 1, V + 1 + n);
	m = unique(V + 1, V + 1 + n) - V - 1;
	for (int i = 1; i <= n; i++) {
		int p = lower_bound(V + 1, V + 1 + m, value(L[i].caly(y))) - V;
		res += Query(p);
		Ins(p);
	} 
	return res;
}
