struct BIT {
    BIT(int n) : s(n + 1), n(n) {}
    int sum(int k) {
        int r = 0;
        for (; k > 0; k -= k & -k) r += s[k];
        return r;
    }
    void add(int i, int v) {
        for (int k = i + 1; k <= n; k += k & -k) s[k] += v;
    }
    vector<int> s;
    int n;
};

struct Line {
    bool operator<(const Line& l) {
        return y < l.y;
    }
    double y;
    int16_t a, b, c;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<Line> l(n);
    for (int i = 0; i < n; i++) {
        cin >> l[i].a >> l[i].b >> l[i].c;
    }

    vector<pair<double, int>> p(n);
    BIT b(n);
    int m = (n - 1) * n / 2;
    int h = (m + 1) / 2;

    for (int u = 0; u < 2; u++) {
        for (int i = 0; i < n; i++) {
            l[i].y = (double)l[i].a / l[i].b;
        }
        sort(l.begin(), l.end());

        double x, x1 = 2e+8, x0 = -x1;
        while (1) {
            x = (x0 + x1) * 0.5;
            if (x1 - x0 < 1e-9) break;

            for (int i = 0; i < n; i++) {
                p[i] = { (l[i].c - l[i].a * x) / l[i].b, i };
            }
            sort(p.begin(), p.end());

            fill(b.s.begin(), b.s.end(), 0);

            int k = m;
            for (int i = 0; i < n; i++) {
                int j = p[i].second;
                k -= b.sum(j);
                b.add(j, 1);
            }
            if (k < h) x0 = x; else x1 = x;
        }

        cout << fixed << setprecision(12) << x << " \n"[u];

        if (u == 1) break;

        for (int i = 0; i < n; i++) {
            swap(l[i].a, l[i].b);
        }
    }

    return 0;
}

