template<typename T>
struct BIT{
    vector<T> data;

    BIT(int size){
        data.assign(++size,0);
    }
    T sum(int k){
        T ret=0;
        for(++k;k>0;k-=k&-k) ret+=data[k];
        return (ret);
    }
    void add(int k,T x){
        for(++k;k<data.size();k+=k&-k)data[k]+=x;
    }
};
/*
和の方
BIT(size) :長さsizeで初期化
sum(k) 区間[0,k]の和を返す
add(k,x) 要素kにxを加える
*/

template<typename T>
struct RBIT{
    BIT<T> bit0,bit1;
    RBIT(int n){
        bit1=bit0=BIT<T>(n);
    }
    //[l,r]にxを加える
    void add(int l,int r,T x){
        bit0.add(l,-x*(l-1));
        bit1.add(l,x);
        bit0.add(r+1,x*r);
        bit1.add(r+1,-x);
    }
    T sum(int i){
        return bit0.sum(i)+bit1.sum(i)*i;
    }
};

