struct fenwick_tree{
	// Number of elements
	int n;

	// Items of the tree
	int ft[MAXN];

	// Get query [l ... r]
	int get_val(int l, int r){
		return get_val(r) - get_val(l - 1);
	}

	// Get query [0 ... r]
	int get_val(int r){
		int res = 0;
		for(; r >= 0; r = (r & (r + 1)) - 1){
			res += ft[r];
		}
		return res;
	}

	// Update query
	void upd_val(int pos, int add){
		for(; pos < n; pos = (pos | (pos + 1))){
			ft[pos] += add;
		}
	}
} ftree;

