int lowbit(int x)
{
     return x&(-x);
}
int sum_(int m)
{
     int ans = 0;
     while(m>0)
     {
          ans += f[m];
          m -= lowbit(m);
     }
     return ans;
}
void add(int m, int d)
{
     while(m <= n)
     {
          f[m] += d;
          m += lowbit(m);
     }
}

#include<bits/stdc++.h>

using namespace std;

#define X   first
#define Y   second
#define ld  double

const int   N   = 4e4 + 5;
const ld    eps = 1e-10;

typedef pair<ld,ld> ii;
typedef pair<ii,ld> pii;

int n, t[N];

vector<pii> Line;

int fix(pii &p) {
    if (p.X.X < 0)
        p.X.X = -p.X.X,
        p.X.Y = -p.X.Y,
        p.Y = -p.Y;
}
int chk(ld  M)  {
    vector<ld>  v1;
    for(pii l : Line)
        v1.push_back((l.Y - M * l.X.Y) / l.X.X);
    vector<ld>  v2 = v1;
    sort(v2.begin(),v2.end());
    v2.erase(unique(v2.begin(),v2.end()),v2.end());

    int ans = 0;

    for(int i = 1 ; i <= n ; ++i)   t[i] = 0;
    for(ld  x : v1) {
        int p = lower_bound(v2.begin(),v2.end(),x) - v2.begin() + 1;
        for(int k = p ; k <= n ; k += k & -k)   ans += t[k];
        for(int k = p ; k >= 1 ; k -= k & -k)   t[k]++;
    }
    return  ans >= (n * n - n + 2) / 4;
}
ld  work()  {
    for(pii &l : Line)  fix(l);
    sort(Line.begin(),Line.end(),[](pii &a,pii &b)  {
        return  a.X.X * b.X.Y > a.X.Y * b.X.X;
    });
    ld  L = -1e7;
    ld  R =  1e7;
    while (L + eps < R) {
        ld M = (L + R) / 2;
        if (chk(M))
            R = M;
        else
            L = M;
    }
    for(pii &l : Line)  swap(l.X.X,l.X.Y);
    return  abs(L) > eps ? L : 0;
}

int main()  {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    cin >> n;

    for(int i = 1 ; i <= n ; ++i)   {
        ld  a;  cin >> a;
        ld  b;  cin >> b;
        ld  c;  cin >> c;
        Line.push_back(pii({a,b},c));
    }

    ld  Y = work();
    ld  X = work();

    cout << fixed << setprecision(10) << X << " " << Y;
}

