struct Line {
  int a, b, c;
  double katamuki;
  Line(int a_, int b_, int c_) : a(a_), b(b_), c(c_) {
    katamuki = -(double)a / b;
  }
  double y(double x) {
    return (c - a * x) / b;
  }
};
inline bool operator < (const Line &lhs, const Line &rhs) {
  return lhs.katamuki > rhs.katamuki;
}

struct Line2 {
  int a, b, c;
  double katamuki;
  Line2(int a_, int b_, int c_) : a(a_), b(b_), c(c_) {
    katamuki = -(double)b / a;
  }
  double x(double y) {
    return (c - b * y) / a;
  }
};
inline bool operator < (const Line2 &lhs, const Line2 &rhs) {
  return lhs.katamuki > rhs.katamuki;
}

template <typename Abelian>
struct BIT {
  BIT(int sz_, const Abelian UNITY_ = 0) : UNITY(UNITY_) {
    sz = sz_ + 1;
    dat.assign(sz, UNITY);
  }

  void add(int idx, Abelian value) {
    while (idx < sz) {
      dat[idx] += value;
      idx += idx & -idx;
    }
  }

  Abelian sum(int idx) {
    Abelian res = UNITY;
    while (idx > 0) {
      res += dat[idx];
      idx -= idx & -idx;
    }
    return res;
  }

  int lower_bound(Abelian value) {
    if (value <= UNITY) return UNITY;
    int res = UNITY, exponent = 1;
    while (exponent < sz) exponent <<= 1;
    for (int mask = exponent >> 1; mask > 0; mask >>= 1) {
      if (res + mask < sz && dat[res + mask] < value) {
        value -= dat[res + mask];
        res += mask;
      }
    }
    return res + 1;
  }

private:
  int sz;
  const Abelian UNITY;
  vector<Abelian> dat;
};

template <typename T>
long long inversion_number(const vector<T> &seq) {
  int sz = seq.size();
  vector<T> cp = seq;
  sort(ALL(cp));
  cp.erase(unique(ALL(cp)), cp.end());
  BIT<int> bit(cp.size());
  long long res = 0;
  REP(i, sz) {
    int idx = lower_bound(ALL(cp), seq[i]) - cp.begin() + 1;
    res += i - bit.sum(idx);
    bit.add(idx, 1);
  }
  return res;
}

