int sum(int v, int l, int r, int tl, int tr)
{
	if (l > r || tl > tr)
		ret 0;
	if (l == tl && r == tr)
		ret t[v];
	int m = (l + r) / 2;
	ret sum(2 * v, l, m, tl, min(tr, m)) + sum(2 * v + 1, m + 1, r, max(tl, m + 1), tr);
}

void upd(int v, int l, int r, int pos)
{
	if (pos < l || pos > r)
		ret;
	if (l == r)
	{
		t[v] = 1;
		ret;
	}
	int m = (l + r) / 2;
	upd(2 * v, l, m, pos);
	upd(2 * v + 1, m + 1, r, pos);
	t[v] = t[2 * v] + t[2 * v + 1];
}

