#include<bits/stdc++.h>
using namespace std;

typedef long double lf;

int N;
lf X;
struct Line {
    int a, b, c;
    bool operator <(const Line &i) const {
        return (lf)-a/b*X-(lf)c/b + 1e-9 < (lf)-i.a/i.b*X-(lf)i.c/i.b || (abs((lf)-a/b*X-(lf)c/b - (lf)-i.a/i.b*X+(lf)i.c/i.b) < 1e-9 && (lf)-a/b < (lf)-i.a/i.b);
    }
};
vector<Line> line;

struct BIT {
    vector<int> tree;
    void init() {
        tree = vector<int>(4*N, 0);
    }
    void upd(int idx, int val, int l, int r, int n) {
        if(idx < l || r < idx) return;
        if(l == r) {
            tree[n] += val;
            return;
        }
        int m = (l + r)>>1;
        upd(idx, val, l, m, 2*n);
        upd(idx, val, m + 1, r, 2*n + 1);
        tree[n] = tree[2*n] + tree[2*n + 1];
    }
    int quer(int a, int b, int l, int r, int n) {
        if(b < l || r < a) return 0;
        if(a <= l && r <= b) return tree[n];
        int m = (l + r)>>1;
        int L = quer(a, b, l, m, 2*n);
        int R = quer(a, b, m + 1, r, 2*n + 1);
        return L + R;
    }
} bit;

struct Frac {
    int a, b;
    bool operator <(const Frac &i) const {
        return a * i.b < i.a * b;
    }
};
vector<Frac> F;
map<Frac, int> df;

lf solve() {
    F.clear();
    df.clear();
    for(int i = 0; i < N; i++) {
        F.push_back({ (((line[i].a < 0) ^ (line[i].b < 0))? 1 : -1) * abs(line[i].a), abs(line[i].b) });
    }
    sort(F.begin(), F.end());
    for(int i = 0; i < N; i++) df[ F[i] ] = i;

    lf s = -1e9, e = 1e9;
    for(int i = 0; i < 64; i++) {
        lf m = (s + e) / 2;
        X = m;

        sort(line.begin(), line.end());

        bit.init();

        int cnt = 0;
        for(int j = 0; j < line.size(); j++) {
            int t = df[ { (((line[j].a < 0) ^ (line[j].b < 0))? 1 : -1) * abs(line[j].a), abs(line[j].b) } ];
            cnt += bit.quer(0, t, 0, N - 1, 1);
            bit.upd(t, 1, 0, N - 1, 1);
        }

        if(cnt >= (N*(N - 1)/2 + 1)/2) e = m;
        else s = m;
    }

    return e;
}

int main() {
    scanf("%d", &N);
    line.resize(N);
    for(int i = 0; i < N; i++) {
        scanf("%d %d %d", &line[i].a, &line[i].b, &line[i].c);
        line[i].c = -line[i].c;
    }

    lf x = solve();

    for(int i = 0; i < N; i++) {
        swap(line[i].a, line[i].b);
    }

    lf y = solve();

    cout<<fixed;
    cout.precision(20);
    cout << x << ' ' << y;
}

