db p[N],pp[N];
int get_num(int l,int r){
	if(l>=r) return 0;
	int mid=(l+r)>>1;
	int ans=get_num(l,mid)+get_num(mid+1,r),i=l,j=mid+1;
	for(int k=l;k<=r;k++){
		if((p[i]<=p[j]&&i<=mid)||j>r) pp[k]=p[i++];
		else pp[k]=p[j++],ans+=mid-i+1;
	}
	for(int k=l;k<=r;k++) p[k]=pp[k];
	return ans;
}
