double solve(){
    int ki=n*(n-1)/2;
    double u=1000000000,d=-1000000000;
    int kata[n];
    vector<pair<double,double>> v;
    rep(i,0,n){
        v.push_back({a[i],b[i]});
    }
    sort(v.begin(),v.end(),cmp);
    v.erase(unique(v.begin(),v.end()),v.end());
    map<pair<double,double>,int> mp;
    rep(i,0,v.size())mp[v[i]]=i+1;
    rep(i,0,n)kata[i]=mp[{a[i],b[i]}];
    rep(i,0,256){
        double mid=(u+d)/2;
        if(u-d<1e-9*max(abs(mid),1.0))break;
        BIT bi(n+1);
        vector<pair<double,int>> w;
        rep(j,0,n){
            double se=-a[j]/b[j]*mid+c[j]/b[j];
            w.push_back({se,j});
