struct fenwick {
    fenwick(int n) : size(n), v(n,0) {}
    void add(int n, int x){for(;n<size;n|=n+1)v[n]+=x;}
    int sum(int n){int s=0;while(n>=0){s+=v[n];n=(n&(n+1))-1;} return s;}
    int size;
    vi v;
};

struct line {
    int a,b,c;
};

double intersect(line& l, double x){
    return -(x*l.a-l.c)/l.b;
}

int count_left(vector<line>& v, double x){
    int cnt = 0;
    vector<pair<double,int>> vec;
    vec.reserve(v.size());
    for(auto& l : v)
        vec.emplace_back(intersect(l,x), cnt++);
    sort(ALL(vec));
    fenwick f(v.size());
    int ans = 0;
    for(auto& p : vec){
        ans += f.sum(p.second);
        f.add(p.second, 1);
    }
    return ans;
}

double medianx(vector<line>&v){
    int n = v.size();
    int tot = n*(n-1)/2;
    int c = count_left(v,0);
    double l,r;
    if(2*c < tot){
        l=0; r=1;
        while(2*count_left(v,r) < tot){l=r;r*=2;}
    } else {
        l=-1; r=0;
        while(2*count_left(v,l) > tot){r=l;l*=2;}
    }
    /*
    for(int i=0;i<90;++i){
        double m=(l+r)/2;
        if(2*count_left(v,m) < tot)
            l=m;
        else
            r=m;
    }
    */
    constexpr double eps = 1e-10;
    while(abs(r-l) > eps){
        double m=(l+r)/2;
        if(2*count_left(v,m) < tot)
            l=m;
        else
            r=m;
    }
    return l;
}

void solve(){
    int n;
    cin>>n;
    vector<line> v(n);
    REP(i,n)
        cin>>v[i].a>>v[i].b>>v[i].c;
    sort(ALL(v), [](line&a, line&b){
            if((a.b<0)^(b.b<0))
                return a.a*b.b<a.b*b.a;
            return a.a*b.b>a.b*b.a;
            });
    double x = medianx(v);
    for(auto& p : v){
        swap(p.a, p.b);
        p.b = -p.b;
    }
    sort(ALL(v), [](line&a, line&b){
            if((a.b<0)^(b.b<0))
                return a.a*b.b<a.b*b.a;
            return a.a*b.b>a.b*b.a;
            });
    double y = medianx(v);
    cout<<setprecision(9)<<fixed<<x<<' '<<y<<'\n';
}

