const int MAXN = 120000;

class BITree {
 public:
 	void build() {
 		SET(bit, 0);
	}

	void update(int idx, int val) {
		while (idx < TREE_SIZE) {
			bit[idx] += val;
			idx += idx & -idx;
		}
	}

	int query(int idx) {
		int ret = 0;
		while (idx) {
			ret += bit[idx];
			idx -= idx & -idx;
		}
		return ret;
	}

 private:
 	static const int TREE_SIZE = 40010;
 	int bit[TREE_SIZE];
};


int A[MAXN], B[MAXN], C[MAXN];
int N;

LL cnt;

vector<int> X, Y, k;
vector<pair<double, int> > inter;
vector<pair<double, int> > steep;
int pos[MAXN];


BITree bit;


double solve(vector<int> X, vector<int> Y, vector<int> k) {
	double s = -100000001.0, e = 100000001.0, mid;
	double ret = s;
	steep.clear();
	FOR (i, N)
		steep.pb(make_pair(-1.0 * X[i] / Y[i], i));
	sort(all(steep));
	FOR (i, N)
		pos[steep[i].second] = i + 1;
	inter.clear();
	FOR (i, N)
		inter.pb(make_pair(-1, -1));
	while (fabs(s - e) > 1e-10) {
		mid = (s + e) / 2.0;
		LL sum = 0;

		FOR (i, N)
			inter[i] = make_pair((k[i] - X[i] * mid) / Y[i], i);
		sort(all(inter));
		bit.build();
		FOR (i, N) {
			sum += bit.query(pos[inter[i].second]);
			bit.update(pos[inter[i].second], + 1);
		}
		if (sum >= (cnt + 1LL) / 2) {
			ret = mid;
			e = mid;
		}
		else
			s = mid;
	}
	return ret;
}

int main() {
	scanf("%d", &N);
	FOR (i, N)
		scanf("%d %d %d", &A[i], &B[i], &C[i]);
	cnt = 1LL * N * (N - 1LL) / 2LL;

	X.clear();
	Y.clear();
	k.clear();
	FOR (i, N) {
		X.pb(A[i]);
		Y.pb(B[i]);
		k.pb(C[i]);
	}

	printf("%.10lf ", solve(X, Y, k));
	printf("%.10lf\n", solve(Y, X, k));
	return 0;
}

