struct L {
  double A, B, C;

  double y(double x) const {
    // y = (-Ax + C) / B
    return (-A * x + C) / B;
  }
  double x(double y) const {
    // x = (-By + C) / A;
    return (-B * y + C) / A;
  }
};

using F = double (L::*)(double) const;

const double INF = 1ll << 30;

template <class T>
struct fenwick_tree {
  vector<T> x;
  fenwick_tree(int n) : x(n + 1) {}
  void add(int k, T a) {
    for (++k; k < x.size(); k += k & -k) x[k] += a;
  }
  T sum(int k) {
    T s = 0;
    for (; k > 0; k &= k - 1) s += x[k];
    return s;
  }
  T sum(int a, int b) { return sum(b) - sum(a); }
  int lower_bound(T a) {
    if (a <= 0) return 0;
    int k = x.size() - 1;
    for (int s : {1, 2, 4, 8, 16}) k |= (k >> s);
    for (int p = ++k; p > 0; p >>= 1, k |= p)
      if (k < x.size() && x[k] < a)
        a -= x[k];
      else
        k ^= p;
    return k + 1;
  }
};

double solve(const vector<L>& ls, F f) {
  const int N = ls.size();
  const int M = (N * (N - 1) / 2 + 1) / 2;
  double ng = -INF, ok = INF;
  for (int i = 0; i < 100; i++) {
    double x = (ng + ok) / 2;
    vector<pair<double, int>> ys(N);
    for (int i = 0; i < N; i++) ys[i] = make_pair((ls[i].*f)(x), i);
    sort(ys.begin(), ys.end());
    ll cnt = 0;
    fenwick_tree<int> bit1(N), bit2(N);
    for (int i = 0; i < N; i++) {
      cnt += bit1.sum(ys[i].snd);
      bit1.add(ys[i].snd, 1);
    }
    for (int i = N - 1; i >= 0; i--) {
      cnt += bit2.sum(ys[i].snd + 1, N);
      bit2.add(ys[i].snd, 1);
    }
    if (cnt >= M * 2) {
      ok = x;
    } else {
      ng = x;
    }
  }
  return ok;
}

int main() {
  int N;
  while (cin >> N) {
    vector<L> ls(N);
    for (int i = 0; i < N; i++) {
      double A, B, C;
      cin >> A >> B >> C;
      ls[i] = {A, B, C};
    }
    sort(ls.begin(), ls.end(),
         [&](auto& a, auto& b) { return -a.A / a.B < -b.A / b.B; });
    double x = solve(ls, &L::y);
    sort(ls.begin(), ls.end(),
         [&](auto& a, auto& b) { return -a.B / a.A < -b.B / b.A; });
    double y = solve(ls, &L::x);
    printf("%.20f %.20f\n", x, y);
  }
  return 0;
}

