pair<double, double> cross(int a1, int b1, int c1, int a2, int b2, int c2){
    double y = (c2 - (c1 * a2) /(double)a1) / (double) (b2 - a2 * b1 / (double) a1);
    double x = (c1 - b1 * y) / a1;
    return make_pair(x, y);
}


