int dat[200000];
void add(int x, int y) {
	while (x <= n) {
		dat[x] += y;
		x += x & -x;
	}
}
int query(int x) {
	int sum = 0;
	while (x > 0) {
		sum += dat[x];
		x -= x & -x;
	}
	return sum;
}
A a[200000];
ld solve() {
	ld ng = -200000000, ok = 200000000, t;
	//自分より左の交点の個数がg以上である最小の点
	int g = ceil(n * (n - 1) / 2 / 2.);
	while (abs(ok - ng) > 1e-11) {
		for (int i = 0; i <= n; i++) 
			dat[i] = 0;
