using namespace std;
typedef long long int ll;
typedef pair <int,int> P;

struct BIT
{
	int bit[SIZE];

	void init()
	{
		memset(bit,0,sizeof(bit));
	}
	void add(int k,int x)
	{
		k++;
		while(k<SIZE)
		{
			bit[k]+=x;
			k+=k&-k;
		}
	}
	int get(int k)
	{
		k++;
		int ret=0;
		while(k>0)
		{
			ret+=bit[k];
			k-=k&-k;
		}
		return ret;
	}
	int get(int s,int t)
	{
		return get(t)-get(s-1);
	}
	int pos(int k)//k 番目
	{
		int l=0,r=SIZE;
		while(r-l>1)
		{
			int m=(l+r)/2;
			if(get(m)<k) l=m;
			else r=m;
		}
		return r;
	}
};
BIT bit;
int A[SIZE],B[SIZE],C[SIZE];
int n;

vector <double> comp(vector <double> vx)
{
	sort(vx.begin(),vx.end());
	vector <double> ret;
	for(int i=0;i<vx.size();)
	{
		ret.push_back(vx[i]);
		int f=i;
		for(;i<vx.size()&&vx[i]-vx[f]<EPS;i++);
	}
	return ret;
}
ll solve(double X)
{
	vector <double> vx,vy;
	for(int i=0;i<n;i++)
	{
		double Y=(double) ((double) C[i]-X*(double) A[i])/(double) B[i];
		double Z=-(double) A[i]/(double) B[i];
		vx.push_back(Y);
		vy.push_back(Z);
	}
	vx=comp(vx);
	vy=comp(vy);
	vector <P> vt;
	for(int i=0;i<n;i++)
	{
		double Y=(double) (C[i]-X*A[i])/(double) B[i];
		double Z=-(double) A[i]/(double) B[i];
		int y=lower_bound(vx.begin(),vx.end(),Y-EPS)-vx.begin();
		int z=lower_bound(vy.begin(),vy.end(),Z-EPS)-vy.begin();
		vt.push_back(P(y,z));
	}
	sort(vt.begin(),vt.end());
	bit.init();
	ll ret=0;
	for(int i=0;i<n;i++)
	{
		P p=vt[i];
		ret+=bit.get(0,p.second);
		bit.add(p.second,1);
	}
	return ret;
}
int main()
{
	scanf("%d",&n);
	for(int i=0;i<n;i++) scanf("%d %d %d",&A[i],&B[i],&C[i]);
	double l=-DINF,r=DINF;
	for(int i=0;i<100;i++)
	{
		double d=(l+r)/2;
		ll cnt=solve(d);
		if(cnt*2<(ll) n*(ll) (n-1)/2) l=d;
		else r=d;
	}
	double px=l;
	for(int i=0;i<n;i++) swap(A[i],B[i]);
	l=-DINF,r=DINF;
	for(int i=0;i<100;i++)
	{
		double d=(l+r)/2;
		ll cnt=solve(d);
		if(cnt*2<(ll) n*(ll) (n-1)/2) l=d;
		else r=d;
	}
	double py=l;
	printf("%.10f %.10f\n",px,py);
	return 0;
}

