#define INF 1120000000

template<typename T>
class BIT {
private:
  vector<T> bit;
  int n;
public:
  BIT(int _n) : n(_n) {
    bit = vector<T>(n+1, 0); //0初期化
  }
  void add(int v, T a){ //vは0-indexed
    for(int x=v+1; x<=n; x += x&(-x)) bit[x] += a;
  }
  T sum(int v){ //vは0-indexed
    T ret=0;
    for(int x=v+1; x>0; x -= x&(-x)) ret += bit[x];
    return ret;
  }
};

int main(){
  int n;
  cin>>n;
  vector<int> a(n),b(n),c(n);
  rep(i,n) cin>>a[i]>>b[i]>>c[i];

  auto arrange = [&](double m){
    vector<pair<double,int>> v;
    rep(i,n) v.pb(mp((double)(c[i]-m*a[i])/b[i], i));
    sort(all(v));
    return v;
  };

  auto sol = [&](){
    auto vl = arrange(-INF);
    vector<int> perm(n);
    rep(i,n) perm[vl[i].se] = i;

    auto calc = [&](double m){
      auto v = arrange(m);

      BIT<int> bit(n);
      int ret = 0;
      rep(i,n){
        int x = perm[v[i].se];
        ret += i - bit.sum(x);
        bit.add(x,1);
      }
      dbg(m,ret);
      return ret;
    };

    double l = -INF, r = INF;
    rep(_,200){
      double m = (r+l)/2.0;
      if( calc(m)>=(n*(n-1)/2+1)/2 ) r = m;
      else l = m;
    }
    return r;
  };

  double x = sol();
  swap(a,b);
  double y = sol();

  printf("%.10f %.10f\n", x, y);

  return 0;
}

