int N, x[40009], y[40009], z[40009], pp[40009], bit[40009]; long double a[40009], b[40009], aa[40009], bb[40009], p[40009];
void add(int p) {
	for (int i = p + 1; i <= N; i += i & (-i)) bit[i]++;
}
int sum(int p) {
	int ret = 0;
	for (int i = p; i >= 1; i -= i & (-i)) ret += bit[i];
	return ret;
}
int calc() {
	fill(bit, bit + N, 0);
	for (int i = 0; i < N; i++) pp[i] = i;
	sort(pp, pp + N, [](int i, int j) { return p[i] < p[j]; });
	int ret = 0;
	for (int i = 0; i < N; i++) {
		ret += sum(pp[i]);
		add(pp[i]);
	}
	return ret;
}
double solve() {
	for (int i = 0; i < N; i++) pp[i] = i, aa[i] = a[i], bb[i] = b[i];
	sort(pp, pp + N, [](int i, int j) { return a[i] < a[j]; });
	for (int i = 0; i < N; i++) a[i] = aa[pp[i]], b[i] = bb[pp[i]];
	long double l = -1.0e+8L, r = 1.0e+8L;
	for (int i = 0; i < 80; i++) {
		long double m = (l + r) * 0.5L;
		for (int j = 0; j < N; j++) p[j] = a[j] * m + b[j];
		if (calc() * 2 < N * (N - 1) / 2) l = m;
		else r = m;
	}
	return l;
}
int main() {
	cin >> N;
	for (int i = 0; i < N; i++) cin >> x[i] >> y[i] >> z[i];
