		b[i] = 1.0 * z[i] / y[i];
	}
	long double ret1 = solve();
	for (int i = 0; i < N; i++) {
		a[i] = -1.0 * y[i] / x[i];
		b[i] = 1.0 * z[i] / x[i];
	}
	long double ret2 = solve();
	printf("%.15Lf %.15Lf\n", ret1, ret2);
	return 0;
}

