    rep(i,n){
        int a,b,c;
        cin >> a >> b >> c;
        v1[i] = P((double)a/-b,(double)c/b);
        v2[i] = P((double)b/-a,(double)c/a);
    }
    sort(all(v1)),sort(all(v2));
    printf("%.12lf %.12lf\n",solve(v1),solve(v2));
    return 0;
}

