const int MOD = 1e9 + 7;
const int oo = 1e9;
const int N = 1e5 + 10;

typedef pair<double, int> ii;

int n;
int BIT[N];
double a[N], b[N], c[N];
double eps = 1e-10;
ii pa[N];
struct con{
    double a, b;
    // y = ax + b
    // :D
}t[N];

bool cmp(const con x, const con y)  {
    if(x.a != y.a) return x.a < y.a;
    else {
        return x.b < y.b; // :D
    }
}

bool cmpv(ii x, ii y)   {
    if(x.fi != y.fi) return x.fi < y.fi;
    return x.se < y.se;
}

double get(con x, double s) {
    return 1.00 * x.a * s + x.b;
}

void upd(int pos)   {
    for(int i = pos; i <= n; i += (i & -i)) BIT[i] ++;
    return; // :D
}

int getBIT(int pos) {
    int res = 0;
    for(int i = pos; i >= 1; i -= (i & -i)) res += BIT[i];
    return res;
}

bool check(double s)    {
    FOR(i, 1, n) BIT[i] = 0;
    FOR(i, 1, n)    pa[i] = ii(get(t[i], s), i);
    sort(pa + 1, pa + 1 + n, cmpv);
    //FOR(i, 1, n) cout << i << ' ' << t[i].a << ' ' << t[i].b << '\n';
    //cout << "spm\n";
    //FOR(i, 1, n) cout << pa[i].fi << ' ' << pa[i].se << '\n';
    int cnt = 0;
    for(int i = n; i >= 1; --i)    {
        cnt += getBIT(pa[i].se);
        upd(pa[i].se);
    }

    int tmp = (n - 1) * n / 2;
    cnt = tmp - cnt;
    return cnt >= (tmp + 1) / 2;
}

double solve()  {
    // we need to find x
    // x = s => a = 1 && b = -s
    double l = (-1.00) * oo, r = 1.00 * oo;
    while(r - l > eps)  {
        //cout << l << ' ' << r << '\n';
        double mid = (l + r) / 2;
        if(check(mid)) // >= mid
            r = mid;
        else l = mid + eps;
    }
    //cout << l << ' ' << r << '\n';
    //cout << fixed << setprecision(9) << l << ' ' << r << '\n';
    if(check(l)) return 1.00 * l;
    else return 1.00 * r;
}

