    FOR(i, 1, n) cin >> a[i] >> b[i] >> c[i];
    FOR(i, 1, n)    {
        t[i].a = (-1.00) * a[i] / b[i];
        t[i].b =  1.00 * c[i] / b[i];
    }
    sort(t + 1, t + n + 1, cmp);
    //cout << check(-1.000000000000000) << '\n'; return 0;
    //cout << solve() << '\n'; return 0;
    double x = solve(); //cout << fixed << setprecision(9) << x << '\n';
    FOR(i, 1, n)    {
        // ay + b = x
        t[i].a = (-1.00) * b[i] / a[i];
        t[i].b = 1.00 * c[i] / a[i];
    }
    sort(t + 1, t + n + 1, cmp);
    double y = solve();
    cout << fixed << setprecision(10) << x << ' '<< y;
    // :D
    return 0;
}

