typedef pair<ld, ld> ldld;

class CARtesianCoordinate{
    int N,K;
    const ld e = 1.e-14, err = 1.e-14;
    ld Mx,mx,My,my;
    vector<vi> Ls;
    inline bool gt(ld x, ld y) { return x > y+e; }
    int mergeSort(vector<ld> &A, int l, int r){
        if(r-l <= 1) return 0;
        if(r-l==2){
            if(A[l] < A[l+1]) return 0;
            swap(A[l], A[l+1]);
            return 1;
        }
        int c = (l+r)/2, ans = 0;
        ans += mergeSort(A, l, c);
        ans += mergeSort(A, c, r);
        vector<ld> tmp(r - l, 0);
        int i = 0, j = 0;
        while(i< c-l || j <r-c){
            if(i == c-l) {
                tmp[i+j] = A[c+j];
                ++j;
            }
            else if(j==r-c) {
                tmp[i+j] = A[l+i];
                ++i;
            }
            else if(A[l+i] < A[c+j]){
                tmp[i+j] = A[l+i];
                ++i;
            }
            else{
                ans += c-l-i;
                tmp[i+j] = A[c+j];
                ++j;
            }
        }
        copy(tmp.begin(), tmp.end(), A.begin()+l);
        return ans;
    }

    int cntX(ld x){
        vector<ld> tmp;
        for(auto vec: Ls) tmp.push_back(ld(vec[2] - vec[0]*x)/vec[1]);
        return mergeSort(tmp, 0, N);
    }
    int cntY(ld y){
        vector<ld> tmp;
        for(auto vec: Ls) tmp.push_back(ld(vec[2] - vec[1]*y)/vec[0]);
        return mergeSort(tmp, 0, N);
    }
    void initX(){
        for(auto &vec: Ls) if(vec[1]<0){
            for(int i=0;i<3;++i) vec[i] *= -1;
        }
        sort(Ls.begin(), Ls.end(), [](const vi&A, const vi&B){return A[0]*B[1] < B[0]*A[1];});
    }
    void initY(){
        for(auto &vec: Ls) if(vec[1]<0){
            for(int i=0;i<3;++i) vec[i] *= -1;
        }
        sort(Ls.begin(), Ls.end(), [](const vi&A, const vi&B){
            if((ld(A[0])/A[1]) * (ld(B[0])/B[1]) >= 0) return ld(-A[0])/A[1] < ld(-B[0])/B[1];
            else if(ld(A[0])/A[1] < 0) return true;
            return false;
        });
    }
    ld findX(){
        initX();
        ld xl = mx, xr = Mx;
        while(xr - xl > err){
            ld c = (xl + xr)/2.;
            if(cntX(c) < (K+1)/2) xl = c;
            else xr = c;
        }
        return (xl + xr)/2.;
    }
    ld findY(){
        initY();
        ld yl = my, yu = My;
        while(yu - yl > err){
            ld c = (yl + yu)/2.;
            if(cntY(c) < (K+1)/2) yl = c;
            else yu = c;
        }
        return (yl + yu)/2.;
    }
public:
    ldld solve(){
        cin>>N;
        K = N*(N-1)/2;
        for(int i=0;i<N;++i){
            vi vec(3);
            for(int i=0;i<3;++i) cin>>vec[i];
            Ls.push_back(vec);
        }
        Mx = My = 1.E8;
        mx = my = -1.E8;
        ld x = findX(), y = findY();
        return ldld(x, y);
    }
};

int main(){
    std::ios_base::sync_with_stdio(false),cin.tie(0),cout.tie(0);
    auto ans = CARtesianCoordinate().solve();
    cout<<setprecision(15);
    cout<<ans.first<<' '<<ans.second<<endl;
    return 0;
}

#include<bits/stdc++.h>

using namespace std;

#define X   first
#define Y   second
#define ld  double

const int   N   = 4e4 + 5;
const ld    eps = 1e-10;

typedef pair<ld,ld> ii;
typedef pair<ii,ld> pii;

int n, t[N];

vector<pii> Line;

int fix(pii &p) {
    if (p.X.X < 0)
        p.X.X = -p.X.X,
        p.X.Y = -p.X.Y,
        p.Y = -p.Y;
}
int chk(ld  M)  {
    vector<ld>  vv;
    map<ld,int> mp;
    for(pii l : Line)
        vv.push_back((l.Y - M * l.X.Y) / l.X.X),
        mp[vv.back()] = 0;

    int tot = 0;
    int ans = 0;
    for(auto &it : mp)  it.Y = ++tot;

    for(int i = 1 ; i <= n ; ++i)   t[i] = 0;
    for(ld  x : vv) {
        for(int k = mp[x] ; k <= n ; k += k & -k)   ans += t[k];
        for(int k = mp[x] ; k >= 1 ; k -= k & -k)   t[k]++;
    }
    return  4 * ans >= n * n - n;
}
ld  work()  {
    for(pii &l : Line)  fix(l);
    sort(Line.begin(),Line.end(),[](pii &a,pii &b)  {
        return  a.X.X * b.X.Y > a.X.Y * b.X.X;
    });
    ld  L = -1e8;
    ld  R =  1e8;
    while (L + eps <= R)    {
        ld M = (L + R) / 2;
        if (chk(M))
            R = M;
        else
            L = M;
    }
    for(pii &l : Line)  swap(l.X.X,l.X.Y);
    return  abs(L) > eps ? L : 0;
}

int main()  {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    cin >> n;

    for(int i = 1 ; i <= n ; ++i)   {
        ld  a;  cin >> a;
        ld  b;  cin >> b;
        ld  c;  cin >> c;
        Line.push_back(pii({a,b},c));
    }

    ld  Y = work();
    ld  X = work();

    cout << fixed << setprecision(9) << X << " " << Y;
}

