using namespace std;

typedef long long ll;
typedef pair<int,int> pii;
typedef pair<int,int> pli;

const int MX = 200005;
const int MM = 1000000007;

pii operator-(const pii &l, const pii &r){
	return pii(l.first - r.first, l.second - r.second);
}

ll operator/(const pii &l, const pii &r){
	return (ll)l.first * r.second - (ll)l.second * r.first;
}

struct line{
	pii d;
	int a, b, c;
	bool operator<(const line &l)const{
		return d/l.d < 0;
	}
} D[MX];

int N;

struct Tree{
	int t[MX];
	int read(int x){
		int r = 0;
		while(x) r += t[x], x -= x&-x;
		return r;
	}
	void update(int x, int v){
		while(x < MX) t[x] += v, x += x&-x;
	}
} tree;

double value(line X, double v){
	return (X.c - X.b*v) / X.a;
}

double solve(line D[MX]){
	sort(D+1, D+N+1);
	double s = -1e9, e = 1e9, m;
	for(int t = 0; t < 100; t++){
		for(int i = 1; i < MX; i++) tree.t[i] = 0;
		vector<double> X;
		m = (s+e) / 2;
		for(int i = 1; i <= N; i++){
			X.push_back(value(D[i], m));
		}
		sort(X.begin(), X.end());
		ll ans = 0;
		for(int i = 1; i <= N; i++){
			int v = lower_bound(X.begin(), X.end(), value(D[i], m)) - X.begin() + 1;
			ans += tree.read(v);
			tree.update(v, 1);
		}
		if( ans < ((ll)N*(N-1)/2+1)/2 ) s = m;
		else e = m;
	}
	return e;
}

int main()
{
	scanf("%d", &N);
	for(int i = 1; i <= N; i++){
		scanf("%d%d%d", &D[i].a, &D[i].b, &D[i].c);
	}
	for(int i = 1; i <= N; i++){
		if( D[i].a < 0 ) D[i].a *= -1, D[i].b *= -1, D[i].c *= -1;
		D[i].d = pii(-D[i].b, D[i].a);
	}
	double x = solve(D);
	for(int i = 1; i <= N; i++){
		swap(D[i].a, D[i].b);
		if( D[i].a < 0 ) D[i].a *= -1, D[i].b *= -1, D[i].c *= -1;
		D[i].d = pii(-D[i].b, D[i].a);
	}
	double y = solve(D);
	printf("%.10lf %.10lf\n", y, x);
}

