//!    8888ba.88ba             oo              !//
//!    88  '8b  '8b                            !//
//!    88   88   88  .d8888b.  dP  88d888b.    !//
//!    88   88   88  88'  '88  88  88'  '88    !//
//!    88   88   88  88.  .88  88  88    88    !//
//!    dP   dP   dP  '88888P8  dP  dP    dP    !//
//!============================================!//
int main()
{
    int N;
    std::cin >> N;
    std::vector<ld> A(N), B(N), C(N);
    for (int i = 0; i < N; i++) { std::cin >> A[i] >> B[i] >> C[i]; }
    const int CP = N * (N - 1) / 2;
    auto bin = [&]() {
        ld inf = -1e12, sup = 1e12;
        std::vector<int> ind(N);
        std::iota(ind.begin(), ind.end(), 0);
        std::sort(ind.begin(), ind.end(), [&](const int i, const int j) { return (C[i] - A[i] * inf) / B[i] < (C[j] - A[j] * inf) / B[j]; });
        for (int t = 0; t < 70; t++) {
            const ld mid = (inf + sup) / 2;
            std::vector<int> ord(N);
            std::iota(ord.begin(), ord.end(), 0);
            std::sort(ord.begin(), ord.end(), [&](const int i, const int j) { return (C[ind[i]] - A[ind[i]] * mid) / B[ind[i]] < (C[ind[j]] - A[ind[j]] * mid) / B[ind[j]]; });
            WaveletMatrix<18> wm(ord.begin(), ord.end());
            int cp = 0;
            for (int i = 0; i < N; i++) { cp += wm.lessThan(i, N, ord[i]); }
            (cp * 2 < CP ? inf : sup) = mid;
        }
        return inf;
    };
    std::cout << std::fixed << std::setprecision(15) << bin() << " ";
    for (int i = 0; i < N; i++) { std::swap(A[i], B[i]); }
    std::cout << bin() << std::endl;
    return 0;
}

#include<bits/stdc++.h>
#define N 200000
using namespace std;
struct line {
    int A, B, C, n;
    double p;
} L[N];
int t[N], n;

bool cmpX(line a, line b) {
    return a.A * b.B > b.A * a.B;
}
bool cmp(line a, line b) {
    return a.p < b.p;
}
int lb(int x) {
    return x & (-x);
}
double calc(double x, int i) {
    return ((double)L[i].C - (double)L[i].A * x) / L[i].B;
}
void add(int x) {
    for(; x <= n; x += lb(x)) t[x]++;
}
int ask(int x) {
    int ret = 0;
    for(; x > 0; x -= lb(x)) ret += t[x];
    return ret;
}

int ch(double mid) {
    for(int i = 1; i <= n; i++) L[i].p = calc(mid, i);
    sort(L + 1, L + n + 1, cmp);
    for(int i = 1; i <= n; i++) t[i] = 0;
    int ret = 0;
    for(int i = 1; i <= n; i++) {
        ret += ask(L[i].n);
        add(L[i].n);
    }
    return ret;
}

double sol() {
    double l = -1e9, r = 1e9;
    for(int i = 1; i <= 80; i++) {
        double mid = (l + r) / 2;
        int tmp = ch(mid);
        if (tmp + tmp < n * (n - 1) / 2) l = mid;
        else r = mid;
    }
    return l;
}

int main() {
    cin >> n;
    for(int i = 1; i <= n; i++) scanf("%d%d%d", &L[i].A, &L[i].B, &L[i].C);
    for(int i = 1; i <= n; i++)
        if (L[i].B < 0) L[i].A *= -1, L[i].B *= - 1, L[i].C *= -1;
    sort(L + 1, L + n + 1, cmpX);
    for(int i = 1; i <= n; i++) L[i].n = i;
    double X = sol();
    for(int i = 1; i <= n; i++) swap(L[i].A, L[i].B);
    for(int i = 1; i <= n; i++)
        if (L[i].B < 0) L[i].A *= -1, L[i].B *= - 1, L[i].C *= -1;
    sort(L + 1, L + n + 1, cmpX);
    for(int i = 1; i <= n; i++) L[i].n = i;
    double Y = sol();
    printf("%.8f %.8f\n", X, Y);
}

