class tenka_e {
	bool chose;
	int BITa[MAXN];
	void add(int p) {
		for (int i=p; i<=n; i+=i&-i)
			BITa[i]++;
	}
	int sum(int p) {
		int result=0;
		for (int i=p;i>0;i-=i&-i)
			result+=BITa[i];
		return result;
	}

	static double cc;
	static bool cmpY (const Line &a, const Line &b) {
		if (a.getY(cc) < b.getY(cc))
			return true;
		else if (a.getY(cc) == b.getY(cc))
			return a.sequence<b.sequence;
		return false;
	}
	static bool cmpX (const Line &a, const Line &b) {
		if (a.getX(cc) < b.getX(cc))
			return true;
		else if (a.getX(cc) == b.getX(cc))
			return a.sequence<b.sequence;
		return false;
	}

public:
	tenka_e(bool _chose) {
		this->chose = _chose;
		arrage(-200000000.0);
		for (int i=0;i<n;i++)
			l[i].sequence = i+1;
