		for (int i=0;i<n;i++)
			cout<<l[i].sequence<<" ";
		cout<<endl;
		*/
		int result = 0;
		memset(BITa,0,sizeof(BITa));
		for (int i=n-1;i>=0;i--) {
			add( l[i].sequence );
			result += sum(l[i].sequence-1);
		}
		return result;
	}
};
