ll inversion_number(const vector<T>& d) {
	ll N = d.size();
	BIT<T> bit(N);
	ll cnt = 0;
	for(int i=N-1;i>=0;i--) {
		cnt += bit.sum(0, d[i]);
		bit.add(d[i], 1);
	}
	return cnt;
}

