int qry(int x, int st, int nd){
  if(st>rt||nd<lf)
    return 0;
  if(st>=lf&&nd<=rt)
    return tr[x];
  int md=(st+nd)/2;
  return qry(x*2, st, md)+qry(x*2+1, md+1, nd);
}
void updt(int x, int st, int nd){
  if(st>rt||nd<lf)
    return;
  if(st==nd){
    tr[x]=1;
    return;
  }
  int md=(st+nd)/2;
  updt(x*2, st, md);
  updt(x*2+1, md+1, nd);
  tr[x]=tr[x*2]+tr[x*2+1];
}
