template<class V> class BIT {
private:
	int n;
	vector<V> bit;

public:
	void add(int i,V x)
	{
		while(i < n){
			bit[i] += x;
			i += i & -i;
		}
	}
	V sum(int i)
	{
		V s = 0;
		while(i>0){
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}
	//初期値がすべて0の場合
	BIT(int sz){
		n = sz + 1;
		bit.resize(n,0);
	}
	BIT(vector<V> v) {
		int sz = (int)v.size();
		n = sz + 1;
		bit.resize(n);
		rep(i,sz){
			 add(i+1,v[i]);
		}
	}
	void print()
	{
		cout << "0 ";
		for(int i=1;i<n;i++){
			cout << sum(i) - sum(i-1) << " ";
		}
		cout << endl;
	}
	void print_sum()
	{
		rep(i,n){
			cout << sum(i) << " ";
		}
		cout << endl;
	}
};

int n;

bool ok(vector<double>& s,vector<double>& t,double cri)
{
    vector<P> vec(n);
    rep(i,n){
        vec[i] = P(cri*s[i]+t[i],i);
    }
    sort(all(vec));
    BIT<int> bt(n+5);
    int num = 0;
    rep(i,n){
        int hoge = round(vec[i].se);
        num += bt.sum(hoge+1);
        bt.add(hoge+1,1);
    }
    if(n % 2 == 0){
        return num < n*(n-1)/4;
    }else{
        return num <= n*(n-1)/4;
    }
}

double solve(vector<P>& vec)
{
    vector<double> tilt(n),tang(n);
    rep(i,n){
        tilt[i] = vec[i].fi,tang[i] = vec[i].se;
    }
    double l = -INF,h = INF;
