ll mod_pow(ll a, ll n, ll mod) {
	ll ret = 1;
	ll p = a % mod;
	while (n) {
		if (n & 1) ret = ret * p % mod;
		p = p * p % mod;
		n >>= 1;
	}
	return ret;
}
template<class T> T extgcd(T a, T b, T& x, T& y) { for (T u = y = 1, v = x = 0; a;) { T q = b / a; swap(x -= q * u, u); swap(y -= q * v, v); swap(b -= q * a, a); } return b; }
template<class T> T mod_inv(T a, T m) { T x, y; extgcd(a, m, x, y); return (m + x % m) % m; }

using Pdd = pair<double, double>;

ll mergecount(vector<Pdd> &a) {
	ll count = 0;
	int n = a.size();
	if (n > 1) {
		vector<Pdd> b(a.begin(), a.begin() + n / 2);
		vector<Pdd> c(a.begin() + n / 2, a.end());
		count += mergecount(b);
		count += mergecount(c);
		for (int i = 0, j = 0, k = 0; i < n; ++i)
			if (k == c.size())       a[i] = b[j++];
			else if (j == b.size())  a[i] = c[k++];
			else if (b[j].second <= c[k].second)   a[i] = b[j++];
			else { a[i] = c[k++]; count += n / 2 - j; }
	}
	return count;
}

ll f(vector<Pdd>& vp, double t) {
	static vector<Pdd> buf;
	buf.clear();

	for (auto& ac : vp) {
		double a, c; tie(a, c) = ac;
		buf.emplace_back(a, t * a - c);
	}
	sort(buf.begin(), buf.end());

	ll cnt = mergecount(buf);
	return cnt;
}

double solve(vector<Pdd>& vp) {
	f(vp, -1e18);
	f(vp, -2);
	f(vp, -1);
	f(vp, 0);

	double l = -1e18, r = 1e18;
	ll cnt = 0;
	ll alls = ll(sz(vp)) * (sz(vp) - 1) / 2;
	ll md = alls / 2 + 1;
	FOR(_, 110) {
		double t = (l + r) / 2;
		ll cnt = f(vp, t);

		if (md <= cnt) {
			l = t;
		} else {
			r = t;
		}
	}

	return l;
}

