typedef pair<double,Line> PL;
struct FenwickTree {
  static const int MAX_N = 50000;
  ll storage[MAX_N+1];
  int N;
  void init(int n) {
    N=n;
    for(int i=0;i<MAX_N;++i) {
      storage[i]=0;
    }
  }
  ll sum(int i) { // 0<i<=N
    if (i==0) return 0;
    int ret = 0;
    while(i>0) {
      ret+=storage[i];
      i -= i&-i;
    }
    return ret;
  }
  void add(int i, ll x) {// 0<=i<N
    ++i;
    while(i<=N) {
      storage[i] += x;
      i += i&-i;
    }
  }
  ll rangeSum(int l, int r) {
    return sum(r)-sum(l);
  }
};

ll N;
FenwickTree ft;
PL pls[4*10000+10];
P angles[4*10000+10];
bool isOK(double d) {
  ft.init(N+10);
  for(int i=0;i<N;++i) {
    double val= (pls[i].second.c -pls[i].second.a*d ) /pls[i].second.b;
    angles[i]=P(val,i);
  }
  sort(angles, angles + N);
  for(int i=0;i<N;++i) {
    pls[angles[i].second].second.order=i;
  }
  ll numLine=0;
  for(int i=0;i<N;++i) {
    numLine += ft.rangeSum(0,pls[i].second.order+1);
    ft.add(pls[i].second.order,1);
  }
  return numLine >= (N*(N-1)/2+2)/2;
}
double INF=1.0*1000*1000*100;
double EPS=0.0000000001;
double solve() {
  for(int i=0;i<N;++i) {
    pls[i].first = pls[i].second.a /pls[i].second.b;
  }
  sort(pls, pls+N);
  double l=-INF,r=INF;
  while(fabs(r-l)>EPS) {
    double m=(r+l)/2;
    if (isOK(m)) {
      l=m;
    } else {
      r=m;
    }
  }
  return l;
}
