class CARtesianCoordinate{
    int N,K;
    const ld e = 1.e-14, err = 1.e-12;
    ld Mx,mx,My,my;
    vector<vi> Ls;
    inline bool gt(ld x, ld y) { return x > y+e; }
    struct T{
        ld val;
        int cnt;   /* # of nodes that are greater than val */
        T *lc, *rc;
        T(ld x):val(x), cnt(0), lc(NULL), rc(NULL){}
    };
    T* addNode(ld x, T *root, int &ans){
        if(!root) return new T(x);
        if(gt(x, root->val)){
            root->cnt += 1;
            root->rc = addNode(x, root->rc, ans);
        }
        else{
            ans += 1 + root->cnt;
            root->lc = addNode(x, root->lc, ans);
        }
        return root;
    }

    int cntX(ld x){
        T *root = NULL;
        int ans = 0;
        for(auto vec: Ls){
            ld y = ld(vec[2] - vec[0]*x)/vec[1];
            root = addNode(y, root, ans);
        }
        return ans;
    }
    int cntY(ld y){
        T *root = NULL;
        int ans = 0;
        for(auto vec: Ls){
            ld x = ld(vec[2] - vec[1]*y)/vec[0];
            root = addNode(x, root, ans);
        }
        return ans;
    }
    void initX(){
        for(auto &vec: Ls) if(vec[1]<0){
            for(int i=0;i<3;++i) vec[i] *= -1;
        }
        sort(Ls.begin(), Ls.end(), [](const vi&A, const vi&B){return A[0]*B[1] < B[0]*A[1];});
    }
    void initY(){
        for(auto &vec: Ls) if(vec[1]<0){
            for(int i=0;i<3;++i) vec[i] *= -1;
        }
        sort(Ls.begin(), Ls.end(), [](const vi&A, const vi&B){
            if((ld(A[0])/A[1]) * (ld(B[0])/B[1]) >= 0) return ld(-A[0])/A[1] < ld(-B[0])/B[1];
            else if(ld(A[0])/A[1] < 0) return true;
            return false;
        });
    }
    ld findX(){
        initX();
        ld xl = mx, xr = Mx;
        while(xr - xl > err){
            ld c = (xl + xr)/2.;
            if(cntX(c) < (K+1)/2) xl = c;
            else xr = c;
        }
        return (xl + xr)/2.;
    }
    ld findY(){
        initY();
        ld yl = my, yu = My;
        while(yu - yl > err){
            ld c = (yl + yu)/2.;
            if(cntY(c) < (K+1)/2) yl = c;
            else yu = c;
        }
        return (yl + yu)/2.;
    }
public:
    ldld solve(){
        cin>>N;
        K = N*(N-1)/2;
        for(int i=0;i<N;++i){
            vi vec(3);
            for(int i=0;i<3;++i) cin>>vec[i];
            Ls.push_back(vec);
        }
        Mx = My = 1.E8;
        mx = my = -1.E8;
        ld x = findX(), y = findY();
        return ldld(x, y);
    }
};

int main(){
    std::ios_base::sync_with_stdio(false),cin.tie(0),cout.tie(0);
    auto ans = CARtesianCoordinate().solve();
    cout<<setprecision(12);
    cout<<ans.first<<' '<<ans.second<<endl;
    return 0;
}

