struct BIT{
private:
    ll u;
    vector<ll> bit;
public:
    BIT(ll n){
        u=1;while(u<n)u*=2;
        bit.resize(u+10,0);

    }
    void add(ll n,ll x){
        ll i=n;
        bit[i]+=x;
        //bit[i]%=mod;
        while(i<u){
            i+=i&(-i);
            bit[i]+=x;
            //bit[i]%=mod;
        }

    }
    ll sum(ll n){
        ll i=n;
        ll ret=0;
        while(i>0){
            ret+=bit[i];
            i-=i&(-i);
            //ret%=mod;
        }
        return ret;
    }
    ll lb(ll w){
        if(w<=0)return 0;
        ll x=0;
        for(ll k=u;k>0;k/=2){
            if(x+k<=u&&bit[x+k]<w){
                w-=bit[x+k];
                x+=k;
            }
        }
        return x+1;
    }
};
