bool cmp(pair<double,double> a,pair<double,double> b){
    double f=a.first/a.second,g=b.first/b.second;
    return -f<-g;
}
int n;
double a[40010],b[40010],c[40010];
double solve(){
    int ki=n*(n-1)/2;
    double u=1000000000,d=-1000000000;
    int kata[n];
    vector<pair<double,double>> v;
    rep(i,0,n){
        v.push_back({a[i],b[i]});
    }
    sort(v.begin(),v.end(),cmp);
    v.erase(unique(v.begin(),v.end()),v.end());
    map<pair<double,double>,int> mp;
    rep(i,0,v.size())mp[v[i]]=i+1;
    rep(i,0,n)kata[i]=mp[{a[i],b[i]}];
    rep(i,0,256){
        double mid=(u+d)/2;
        BIT bi(n+1);
        vector<pair<double,int>> w;
        rep(j,0,n){
            double se=-a[j]/b[j]*mid+c[j]/b[j];
            w.push_back({se,j});
        }
        sort(w.begin(),w.end());
        int sum=0;
        rep(j,0,w.size()){
            int num=w[j].second;
            sum+=bi.sum(kata[num]);
            bi.add(kata[num],1);
        }
        if(sum<(ki+1)/2)d=mid;
        else u=mid;
    }
    return u;
}
int main(){
    ios::sync_with_stdio(false);cin.tie(0);
    cin>>n;
    rep(i,0,n)cin>>a[i]>>b[i]>>c[i];
    double x=solve();
    rep(i,0,n)swap(a[i],b[i]);
    double y=solve();
    cout<<fixed<<setprecision(12)<<x<<" "<<y<<endl;
}

