#define ub upper_bound

const int MOD = 1000000007;

ll N,combo;
int A[100000], B[100000], C[100000];

ll calc(ld mid) {
    vector<pdd> v;
    F0R(i,N) {
        pdd tmp = {(C[i]-B[i]*mid)/A[i],-(ld)A[i]/B[i]};
        if (tmp.s < 0) tmp.s = -tmp.s;
        else tmp.s = MOD-tmp.s;
        v.pb(tmp);
    }
    sort(v.begin(),v.end());

    Tree<ld> T;
    ll ret = 0;
    F0R(i,N) {
        ret += T.order_of_key(v[i].s);
        T.insert(v[i].s);
    }
    return ret;
}

void solve() {
	ld lox = -1000000000, hix = 1000000000;
	assert(calc(hix) == combo);
	F0R(i,70) {
	    ld mid = (lox+hix)/2;
	    if (2*calc(mid) >= combo) hix = mid; // first one such that 2*calc(mid) >= combo
	    else lox = mid;
	}
	cout << lox << " ";
}

int main() {
	ios_base::sync_with_stdio(0);cin.tie(0);
	cin >> N; combo = N*(N-1)/2;
	F0R(i,N) cin >> A[i] >> B[i] >> C[i];
	cout << fixed << setprecision(11);
	F0R(i,N) swap(A[i],B[i]);
	solve();
	F0R(i,N) swap(A[i],B[i]);
	solve();
}

