  rep(j, N) {
    int i = ls[j]._2;
    double y = (-X*(double)A[i] + (double)C[i]) / (double)B[i];
    ps.pb(make_pair(y, j));
  }
  sort(all(ps));
  rep(i, N) pos[ps[i]._2] = i;
  rep(i, N) fill(all(bit.xs), 0);

  long long s = 0;
  rep(i, N) {
    s += i-bit.sum(pos[i]);
    bit.add(pos[i], 1);
  }
  //cout<<"f("<<X<<"): ";
  //rep(i, N) cout<<ps[i]._2<<",";cout<<"->"<<s<<"\n";
  return s;
}

double solve() {
  long long n = (1LL*N*(N-1))/2;
  ls.clear();
  rep(i, N) {
    int p = -A[i], q = B[i];
    if (q < 0) p = -p, q = -q;
    ls.pb(P2(P(p, q), i));
  }
  sort(all(ls), cmp);
  reverse(all(ls));
  assert(ls.size() == N);

  double lo = -1e10, hi = 1e10;
  rep(_, 100) {
    double mid = (lo + hi) / 2;
    if (f(mid) >= (n+1)/2) hi = mid;
    else lo = mid;
  }
  return hi;
}

