namespace tree {

template <typename T>
struct BIT {
    vec<T> data;
    T id_ele;

    BIT(ll size, T id_ele) : id_ele(id_ele) {
        ll bsize = 1;
        while (bsize < size) bsize *= 2;
        data = vec<T>(bsize + 1, id_ele);
    }

    T sum(ll pos) {
        T ret = id_ele;
        for (; 0 < pos; pos -= pos & -pos) ret += data[pos];
        return ret;
    }

    T sum(ll l, ll r) { return sum(r) - sum(l); }

    void add(ll pos, T delta) {
        for (++pos; pos < data.size(); pos += pos & -pos) data[pos] += delta;
    }
};

}

const double inf = 5e15;

double solve(vec<tll> &lines) {
    ll n = lines.size();

    auto til = [](tll t) {
        ll a, b;
        std::tie(a, b, std::ignore) = t;
        return static_cast<double>(a) / b;
    };

    auto val = [](tll t, double x) {
        ll a, b, c;
        std::tie(a, b, c) = t;
        return (-a * x + c) / b;
    };

    std::sort(ALL(lines), [&](tll a, tll b) { return til(a) > til(b); });
    tree::BIT<ll> bt(n + 10, 0);
    vec<double> vals(n);
    vec<ll> ord(n);
    std::iota(ALL(ord), 0);
    double ok = inf, ng = -inf;
    for (ll loop = 0; loop < 100; loop++) {
        ll cnt = 0;
        double mid = (ok + ng) / 2;
        std::fill(ALL(bt.data), 0);
        for (ll i = 0; i < n; i++) vals[i] = val(lines[i], mid);
        std::sort(ALL(ord), [&](ll i, ll j) { return vals[i] < vals[j]; });
        std::map<double, ll> id;
        for (ll idx : ord) {
            double v = vals[idx];
            if (id.find(v) != id.end()) continue;
            ll tmp = id.size();
            id[v] = tmp;
        }
        for (ll i = 0; i < n; i++) {
            ll idx = id[vals[i]];
            cnt += bt.sum(0, idx);
            bt.add(idx, 1);
        }
        ll sum = n * (n - 1) / 2;
        (sum / 2 + (sum & 1) <= cnt ? ok : ng) = mid;
    }

    return ok;
}

int main() {
    ll n;
    std::cin >> n;
    vec<tll> abc(n);
    for (auto &&e : abc) {
        ll a, b, c;
        std::cin >> a >> b >> c;
        e = tll(a, b, c);
    }

    double x = solve(abc);
    for (auto &&e : abc) std::swap(std::get<0>(e), std::get<1>(e));
    double y = solve(abc);
    std::cout << x << ' ' << y << std::endl;
    return 0;
}

