}

double y(int i, int j) {
    if (a[i] * b[j] == b[i] * a[j])
        exit(0);
    return double(a[j] * c[i] - c[j] * a[i]) / (a[i] * b[j] - b[i] * a[j]);
}

double get_x(int n, int m) {
    m++;

    double minx = 1e20, maxx = -1e20;

    rep (i, n) {
        rep (j, i) {
            double xx = x(i, j);
            chmin(minx, xx);
            chmax(maxx, xx);
        }
    }

    rep (_, 100) {
        double X = (maxx + minx) / 2;
        double ans = minx;

        int cnt = 0;
        rep (i, n) {
            rep (j, i) {
                double xx = x(i, j);
                if (xx < X) {
                    cnt++;
                    chmax(ans, xx);
                }
            }
        }

        if (cnt == m)
            return ans;
        if (cnt < m)
            minx = X;
        else
            maxx = X;
    }

    exit(0);
}

