    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    cin >> n;

    for(int i = 1 ; i <= n ; ++i)   {
        ld  a;  cin >> a;
        ld  b;  cin >> b;
        ld  c;  cin >> c;
        Line.push_back(pii({a,b},c));
    }

    ld  Y = work();
    ld  X = work();

    cout << fixed << setprecision(10) << X << " " << Y;
}

