using namespace std;
template<class T> class sumBIT
{
private:
  T *bit;
  int S;
public:
  sumBIT(int S0){
    S=S0;
    bit=(T *)calloc(sizeof(T),1<<S);
  }
  void add(int i,T k){
    int p=i+1;
    while(p<1<<S){
      bit[p]+=k;
      p+=p&-p;
    }
  }
  T sum(int p){
    T ret=0;
    while(p>0){
      ret+=bit[p];
      p-=p&-p;
    }
    return ret;
  }
  T rag(int a,int b){
    return sum(b)-sum(a);
  }
};

double mid(int n,double *a,double *b,double *c)
{
  vector<pair<double,double> > P(n);
  for(int i=0;i<n;i++){
    P[i]=make_pair(-a[i]/b[i],c[i]/b[i]);
  }
  sort(P.begin(),P.end());
  double L=-1e9,R=1e9;
  long long m2=((long long)n*(n-1)/2+1)/2;
  while(R-L>1e-10){
    double M=(R+L)/2;
    vector<pair<double,int> > P2(n);
    sumBIT<int> bit(17);
    long long cnt=0;
    for(int i=0;i<n;i++){
      P2[i]=make_pair(M*P[i].first+P[i].second,i);
    }
    sort(P2.begin(),P2.end());
    for(int i=0;i<n;i++){
      int j=P2[i].second;
      cnt+=bit.sum(j);
      bit.add(j,1);
    }
    //printf("%lf %lld\n",M,cnt);
    if(cnt>=m2){
      R=M;
    }
    else{
      L=M;
    }
  }
  return (R+L)/2;
}

