    }
    pls[i].first=val;
  }
  sort(pls, pls+N);
  for(int i=0;i<N;++i) {
    double t;
    if (isX) {
      t=(pls[i].second.a/pls[i].second.b);
    } else {
      t=(pls[i].second.b/pls[i].second.a);
    }
    angles[i]=P(t,i);
  }
  sort(angles, angles + N);
  for(int i=0;i<N;++i) {
    pls[angles[i].second].second.order=i;
  }
  ll numLine=0;
  for(int i=0;i<N;++i) {
    numLine += ft.sum(pls[i].second.order+1);
    ft.add(pls[i].second.order,1);
  }
  return numLine < (N*(N-1)/2+1)/2;
}
double bsearch(double l,double r, bool isX) {
  if (fabs(r-l) <= 0.000000001) {
    return l;
