template<class T> struct fenwick{
  T *data;
  int memory, size;
  void malloc(int mem){
    memory=mem;
    data=(T*)std::malloc(sizeof(T)*mem);
  }
  void *malloc(int mem, void *workMemory){
    memory=mem;
    data=(T*)workMemory;
    return (void*)(data+mem);
  }
  void free(void){
    memory=0;
    free(data);
  }
  void init(int N){
    size=N;
    memset(data,0,sizeof(T)*N);
  }
  void add(int k, T val){
    while(k<size){
      data[k]+=val,
      k|=k+1;
    }
  }
  T get(int k){
    T res=0;
    while(k>=0){
      res+=data[k],
      k=(k&(k+1))-1;
    }
    return res;
  }
  T range(int a, int b){
    if(b==-1){
      b=size-1;
    }
    return get(b)-get(a-1);
  }
  int kth(T k){
    T v;
    int c, i=0, j=size;
    while(i<j){
      c=(i+j)/2;
      v=get(c);
      if(v<=k){
        i=c+1;
      }
      else{
        j=c;
      }
    }
    return i==size?-1:i;
  }
}
