typedef tuple<double, ll> dt;
typedef tuple<double, ll, ll ,ll> dttt;

double solve(const V<dttt> &dabclist, ll n, bool isx)
{
    double left = -1e8;
    double right = 1e8;
    double now = 0.0;
    double ret = 1e8;

    ll border = (n * (n - 1LL)) / 2LL;
    border = ((border & 1LL) ? (border / 2LL + 1LL) : (border / 2LL));

    BIT bitree(n+1, 0LL);

    debug_printf("n=%lld border=%lld\n", n, border);
    ll loopcount = 0LL;

    for ( ; right - left > 1e-10; now = (left + right) / 2.0) {
        bitree.init(0LL);
        V<dt> order;

        rep (i, n) {
            ll a = get<1>(dabclist[i]);
            ll b = get<2>(dabclist[i]);
            ll c = get<3>(dabclist[i]);

            double p = (double)c - ((double)(isx ? a : b)) * now;
            p /= (double)(isx ? b : a);

            order.pb(dt(p, i+1LL));  // 0 origin --> 1 origin
        }

        sort(order);

        ll count = 0LL;
        for (auto pi : order) {
            ll i = get<1>(pi);
            count += bitree.sum(i);
            bitree.add(i, 1LL);
        }

        debug_printf("left=%lf right=%lf now=%lf ret=%lf count=%lld\n",
                     left, right, now, ret, count);

        if (count < border) {
            left = now;
        }
        if (count == border) {
            ret = min(ret, now);
            right = now;
        }
        if (count > border) {
            right = now;
        }

        loopcount++;
        if (loopcount >= 5000LL) return ret;
        assert(loopcount < 5000LL);
    }

    debug_printf("debug_count=%lld\n", debug_count);

    return ret;
}

