			double mid = (l+r) / 2;

			sort(a+1, a+n+1, [&](line u, line v) { return u.y(mid) < v.y(mid); });

			long long invs = 0;

			tree.clear();

			for (int i=1; i<=n; i++) {
				tree.add(a[i].id, 1);
