struct BIT {
    int size;
    vector<int> node;

    BIT(int n, long long init_num = 0LL) {
        size = n;
        node.resize(size + 1, init_num);
    }

    void add(int i, long long x) {
        while (i <= size) {
            node[i] += x;
            i += i & -i;
        }
    }

    long long sum(int i) {
        long long ret = 0;
        while (i > 0) {
            ret += node[i];
            i -= i & -i;
        }
        return ret;
    }
};

