class BIT   // 1-indexed (0 is not used)
{
private:
    long num;
    vector<long> bit;
public:
    BIT(long n):bit(vector<long>(n+1, 0)), num(n) {}

    long sum(long i) {   // sum of 1..i
        if (!i) return 0;
        return bit[i] + sum(i-(i&-i));
    }

    void add(long i, int x) {
        if (i > num) return;
        bit[i] += x;
        add(i+(i&-i), x);
    }
};

ll InvNum( long n, ll* a )
{
    map<ll,long> mp;
    long i;
    for(i=0; i<n; i++) {
        mp[a[i]]=0;
    }
    long num=0;
    auto it=mp.begin();
    for(; it!=mp.end(); ++it) {
        num++;
        it->second=num;
    }

    ll ans=0;
    BIT bit(num);
    for(i=0; i<n; i++) {
        ans += i - bit.sum(mp[a[i]]);
        bit.add(mp[a[i]], 1);
    }
    return ans;
}

