int N;
struct BIT{
    //1-indexed
    int bit[MAX_N+1];

    void init(){
        memset(bit, 0, sizeof(bit));
    }

    int sum(int i){
        int s=0;
        while(i>0){
            s+=bit[i];
            i-=i&-i;
        }
        return s;
    }

    void add(int i, int x){
        while(i<=N){
            bit[i]+=x;
            i+=i&-i;
        }
    }
