inline int lowbit(int x){
	return x & (-x);
}

inline void add(int x){
	while(x <= n){
		c[x]++;
		x += lowbit(x);
	}
}

inline int sum(int x){
	int ret = 0;
	while(x){
		ret += c[x];
		x -= lowbit(x);
	}
	return ret;
}

