    int node[N];
public:
    BIT() { times(N, i) node[i] = 0; }
    /** 0-based **/
    void set(int i, int v) {
        add(i, v - node[i]);
    }
    /** 0-based **/
    void add(int i, int v) {
        for(++i; i <= N; i += i & -i)
            node[i-1] += v;
    }
    /** [0, i) **/
    int sum(int i) {
        int s = 0;
        for(++i; i; i -= i & -i)
            s += node[i-1];
        return s;
    }
};

