template <class Ab>
struct fenwick_tree {

  int size;
  std::vector<Ab> node;

  fenwick_tree() { }
  fenwick_tree(const int& size_) { init(size_); }

  void init(const int& size_) {
    size = size_;
    node.assign(size + 1, 0);
  }

  void modify(const int& idx, const Ab& value) {
    int x = idx + 1;
    while (x <= size) {
      node[x] += value;
      x += x & -x;
    }
  }

  // [0, idx]
  Ab get(const int& idx) const {
    Ab result{};
    int x = idx + 1;
    while (x > 0) {
      result += node[x];
      x -= x & -x;
    }
    return result;
  }

};

