struct line {
  dbl a, b; 
  int id;
  line(dbl a = 0, dbl b = 0) : a(a), b(b), id(-1) { }
  dbl val(const dbl& x) const {
    return a * x + b;
  }
};

int N, count;
line L[40000];

dbl calc() {
  dbl ok = inf, ng = -inf;
  rep (steps, 100) {
    dbl md = (ok + ng) / 2;
    ([&]{
      std::sort(L, L + N, [&](line l, line m){
        return l.val(md) < m.val(md);
      });
      fenwick_tree<int> fen(N);
      int now = 0;
      rep (i, N) {
        now += fen.get(L[i].id);
        fen.modify(L[i].id, 1);
      }
      return now >= count;
    }() ? ok : ng) = md;
  }
  return ok;
}

void sort() {
  std::sort(L, L + N, [](line l, line m){
    return l.a < m.a;
  });
  rep (i, N) L[i].id = i;
}

void swap() {
  rep (i, N) {
    L[i].a = 1.0L / L[i].a;
    L[i].b = -L[i].a * L[i].b;
  }
}

