struct L{
	int a, b, c;
	L(){}
	double x(double y) { return (c - y * b) / a; }
	bool operator <(L const &o)const{
		int a1 = -a, b1 = b, a2 = -o.a, b2 = o.b;
		if (a1 < 0)b1 = -b1, a1 = -a1;
		if (a2 < 0)b2 = -b2, a2 = -a2;
		return b1 * a2 < b2 * a1;
	}
