typedef tuple<double, ll> dt;
typedef tuple<double, ll, ll ,ll> dttt;

double solve(const V<dttt> &dabclist, ll n, bool isx)
{
    double left = -1e10;
    double right = 1e10;
    double now = 0.0;
    double ret = 1e10;

    ll border = (n * (n - 1LL)) / 2LL;
    border = ((border & 1LL) ? (border / 2LL + 1LL) : (border / 2LL));
    debug_printf("n=%lld border=%lld\n", n, border);

    BIT bitree(n+1, 0LL);

    for ( ; right - left > 1e-15 * max(1.0, abs(right));
          now = (left + right) / 2.0) {

        bitree.init(0LL);
        V<dt> order;

        rep (i, n) {
            ll a = get<1>(dabclist[i]);
            ll b = get<2>(dabclist[i]);
            ll c = get<3>(dabclist[i]);

            double p = (double)c - ((double)(isx ? a : b)) * now;
            p /= (double)(isx ? b : a);

            order.pb(dt(p, i+1LL));  // 0 origin --> 1 origin
        }

        sort(order);

        ll count = 0LL;
        for (auto pi : order) {
            ll i = get<1>(pi);
            count += bitree.sum(i);
            bitree.add(i, 1LL);
        }

        debug_printf("left=%5.15lf right=%5.15lf sub=%5.15lf now=%5.15lf ret=%5.15lf count=%lld\n",
                     left, right, right - left, now, ret, count);

        if (count < border) {
            left = now;
        }
        if (count >= border) {
            ret = min(ret, now);
            right = now;
        }
    }

    return ret;
}

