//1-indexであることに注意
struct BIT {
    int n;
    vector<int> data;

    BIT(int n) : n(n), data(n + 1, 0) {}

    int sum(int i) {
        int s = 0;
        while (i > 0) {
            s += data[i];
            i -= i & -i;
        }
        return s;
    }

    void add(int i, int x) {
        while (i <= n) {
            data[i] += x;
            i += i & -i;
        }
    }
};

int inv(vector<int>& a) {
    int res = 0;
    BIT b(a.size());
    for (int i = 0; i < a.size(); i++) {
        res += i - b.sum(a[i] + 1);
        b.add(a[i] + 1, 1);
    }
    return res;
}

double solve(vector<T>& p, int lim) {
    double ok = 1e9, ng = -1e9 - 1;
    vector<int> idx(p.size());
    for (int i = 0; i < p.size(); i++) {
        idx[i] = i;
    }
    for (int loop = 0; loop < 100; loop++) {
        double mid = (ok + ng) / 2;
        auto comp = [&](const int& i1, const int& i2) {
            double a1, b1, c1, a2, b2, c2;
            tie(a1, b1, c1) = p[i1];
            tie(a2, b2, c2) = p[i2];
            double y1 = (-a1 * mid + c1) / b1;
            double y2 = (-a2 * mid + c2) / b2;
            return y1 < y2;
        };
        sort(idx.rbegin(), idx.rend(), comp);
        if (inv(idx) >= lim) ok = mid;
        else ng = mid;
    }
    return ok;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    int lim = (n * (n - 1) + 3) / 4;
    vector<T> p(n);
    for (int i = 0; i < n; i++) {
        cin >> get<0>(p[i]) >> get<1>(p[i]) >> get<2>(p[i]);
    }
    sort(p.begin(), p.end(), [](const T& t1, const T& t2){return -get<0>(t1) / get<1>(t1) < -get<0>(t2) / get<1>(t2);});
    double ansx = solve(p, lim);
    for (int i = 0; i < n; i++) {
        swap(get<0>(p[i]), get<1>(p[i]));
    }
    sort(p.begin(), p.end(), [](const T& t1, const T& t2){return -get<0>(t1) / get<1>(t1) < -get<0>(t2) / get<1>(t2);});
    double ansy = solve(p, lim);
    cout << fixed << setprecision(10) << ansx << " " << ansy << endl;
    return 0;
}

