int t[MAXN];
int sum(int idx)
{
    int res = 0;
    while (idx)
    {
        res += t[idx];
        idx -= (idx & -idx);
    }
    return res;
}

void upd(int idx, int val)
{
    int old_val = sum(idx) - sum(idx-1);
    while (idx <= n)
    {
        t[idx] += (val - old_val);
        idx += (idx & -idx);
    }
}


