vector<int> getOrder(vector<int> a, vector<int> b, vector<int> c, double x) {
    int n = a.size();
    vector<double> y(n, 0);

    for(int i = 0; i < n; ++i) {
        y[i] = (-c[i] - a[i] * x + 0.0) / b[i];
    }   

    vector<int> p;
    for(int i = 0; i < n; ++i)
        p.push_back(i);

    sort(p.begin(), p.end(), [&] (int a, int b) {
        return y[a] < y[b];
    });

    return p;
}

long long getInversions(vector<int> a, vector<int> p) {
    vector<int> aa = a;
    int n = a.size();
    vector<int> place(n, 0);
    for(int i = 0; i < n; ++i) {
        place[p[i]] = i;
    }
    for(int i = 0; i < n; ++i) {
        aa[i] = place[a[i]];
    }

    ordered_set T;
    long long ans = 0;

    for(int i = 0; i < n; ++i) {
        ans += i - T.order_of_key(aa[i]);
        T.insert(aa[i]);
    }

    return ans;
}

int main() {
    ios_base :: sync_with_stdio(false);
    int n; cin >> n;
    vector<int> a(n, 0), b(n, 0), c(n, 0);

    for(int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i] >> c[i];
    }

    long long total = 1LL * n * (n - 1) / 2;

    auto original = getOrder(a, b, c, -1e11);

    cout.precision(20);

    for(int it = 0; it < 2; ++it) {
        double ans = 0, lf = -1e10, rt = 1e10, mid = 0;
        for(int cnt = 0; cnt < 50; ++cnt) {
            mid = (lf + rt) * 0.5;
            auto now = getOrder(a, b, c, mid);
            long long many = getInversions(now, original);
            if(many <= total / 2) {
                ans = mid;
                lf = mid;
            } else {
                rt = mid;
            }
        }
        cout << -ans << " ";
        for(int i = 0; i < n; ++i) {
            swap(a[i], b[i]);
        }
        original = getOrder(a, b, c, -1e11);
    }
}

