struct solver
{
    const i64 n;

    long double calc(vector<pair<long double,long double>> lines)
    {
        sort(begin(lines), end(lines));
        auto ok=[&](const long double k)
        {
            vector<long double> val;
            for(auto [x,y]: lines) val.emplace_back(x*k+y);
            sort(begin(val), end(val));
            segment_tree<int> seg(n);
            i64 cnt=0;
            for(auto [x,y]: lines)
            {
                long double now=x*k+y;
                int ival=lower_bound(begin(val), end(val), now)-begin(val);
                cnt+=seg.fold(0,ival);
                seg[ival]++;
            }
            return cnt*2>=n*(n-1)/2;
        };
        return binary(1e6,-1e6,1e-10,ok);
    }

    solver() : n(read())
    {
        vector<pair<long double,long double>> lx,ly;
        for(int i=0; i<n; ++i)
        {
            long double a=read(),b=read(),c=read();
            lx.emplace_back(-a/b,c/b);
            ly.emplace_back(-b/a,c/a);
        }
        cout<<calc(lx)<<" "<<calc(ly)<<endl;
    }
};

