LL n;
double pos[maxn];
int c[maxn], rk[maxn];

struct Line { LL a, b, c; } L[maxn];

inline bool cmp(int x, int y) { return pos[x] < pos[y]; }
inline bool cmpx(Line x, Line y) { return double(x.a) / x.b > double(y.a) / y.b; }
inline bool cmpy(Line x, Line y) { return double(x.b) / x.a > double(y.b) / y.a; }

#define lowbit(x) ((x) & -(x))
inline void update(int u) {
    while(u <= n) {
        c[u] ++;    
        u += lowbit(u);
    }
}
inline int query(int u) {
    int res = 0;
    while(u > 0) {
        res += c[u];
        u -= lowbit(u);
    }
    return res;
}

inline bool chkx(double mid) {
    LL res = 0;
    for(int i = 1; i <= n; ++i) 
        c[i] = 0, rk[i] = i, pos[i] = -double(L[i].c + L[i].a * mid) / L[i].b;

    sort(rk + 1, rk + n + 1, cmp);
    for(int i = 1; i <= n; ++i) {
        res += query(rk[i]); update(rk[i]);
    }
    return (res << 2LL) >= n * (n-1);
}

inline bool chky(double mid) {
    LL res = 0;
    for(int i = 1; i <= n; ++i) 
        c[i] = 0, rk[i] = i, pos[i] = -double(L[i].c + L[i].b * mid) / L[i].a;

    sort(rk + 1, rk + n + 1, cmp);
    for(int i = 1; i <= n; ++i) {
        res += query(rk[i]); update(rk[i]);
    }
    return (res << 2LL) >= n * (n-1);
}

