vector<ld> xs, ys;
vector<L> ls;

P solve() {
    xs.clear();
    ys.clear();
    ls.resize(n);
    rep(i, n) ls[i] = make_line(a[i], b[i], -c[i]);
    rep(i, n) rep(j, i) {
        P p = is_ll(ls[i], ls[j]);
        xs.push_back(p.real());
        ys.push_back(p.imag());
    }

    int m = xs.size();
    sort(all(xs));
    sort(all(ys));

    return P(xs[(m-1) / 2], ys[(m-1) / 2]);
}

