ll merge_sort(int l, int r) {
	int m = (l + r) / 2;
	ll ret = 0;
	if (l + 1 < m)	ret += merge_sort(l, m);
	if (m + 1 < r)	ret += merge_sort(m, r);
	vector<ld> al, ar;
	srep(i, l, m)	al.push_back(pos[i]);
	srep(i, m, r)	ar.push_back(pos[i]);
	int s = 0, t = 0;
	srep(i, l, r) {
		if (s == al.size())	pos[i] = ar[t++];
		else if (t == ar.size())	pos[i] = al[s++];
		else if (al[s] > ar[t]) {
			pos[i] = ar[t++];
			ret += al.size() - s;
		}
		else	pos[i] = al[s++];
	}
	return ret;
}

