	ll leftp = merge_sort(0, pos.size());
	pos = vector<ld>(n);
	rep(j, n)	pos[j] = (ld)-(c[j] - a[j] * mid) / b[j];
	ll rightp = merge_sort(0, pos.size());
	if (line != inf) {
		if (line < mid)	leftp += pos.size();
		else if (mid < line)	rightp += pos.size();
	}
	return leftp - rightp;
}

