		ord[vec[i].second]=i;
		long double val=(long double)c[i]/b[i]-(a[i]/b[i])*v;
		vec2.push_back(P(val,i));
		seg.update(i,1);
	}
	sort(vec2.begin(),vec2.end());
	ll cnt=0;
	for(int i=0;i<n;i++){
		cnt+=(ll)seg.query(0,ord[vec2[i].second]);
		seg.update(ord[vec2[i].second],-1);
	}
	ll val=(ll)n*(n-1)/2LL;
	if(val%2LL==0)return cnt<(val/2LL);
	return cnt*2LL<val;
}

