const int N = 4e4 + 5;
const double eps = 1e-10;
int n, a[N], b[N], c[N];
map<double, int> id;

struct Line {
    double A, B;
    Line(double A = 0, double B = 0) : A(A), B(B) {}
    bool operator< (const Line& rhs) const { return A == rhs.A ? B < rhs.B : A < rhs.A; }
} line[2][N];

struct Bit {
    int a[N];
    Bit() { memset(a, 0, sizeof a); }
    void update(int pos, int val) {
        for (; pos < N; pos += pos & -pos) a[pos] += val;
    }
    int get(int pos) {
        int ret = 0;
        for (; pos > 0; pos -= pos & -pos) ret += a[pos];
        return ret;
    }
} bit;

void solve(bool type) {
    sort(line[type] + 1, line[type] + n + 1);
    double l = -1e9, r = 1e9;
    while(r - l > eps) {
        double mid = (l + r) / 2;
        id.clear();
        for (int i = 1; i <= n; ++i) id[mid * line[type][i].A + line[type][i].B];
        int curId = 0;
        for (auto i : id) id[i.fi] = ++curId;
        bit = Bit();
        int cnt = 0;
        for (int i = 1; i <= n; ++i) {
            cnt += bit.get(id[mid * line[type][i].A + line[type][i].B]);
            bit.update(id[mid * line[type][i].A + line[type][i].B], 1);
        }
        if(cnt >= (n + 1) / 2) r = mid;
        else l = mid;
    }
    cout << l;
}

signed main () {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> a[i] >> b[i] >> c[i];
        line[0][i] = Line(-1.0 * a[i] / b[i], 1.0 * c[i] / b[i]);
        line[1][i] = Line(-1.0 * b[i] / a[i], 1.0 * c[i] / a[i]);
    }

    solve(0);
    cout << ' ';
    solve(1);

    return 0;
}

