using namespace std;
using LL = long long;
using LD = long double;

LL N;
LL M;

template< class T >
struct BinaryIndexedTree
{
	vector< T > data;

	BinaryIndexedTree(int sz)
	{
		data.assign(++sz, 0);
	}

	void init()
	{
		for (T& t : data)t = T();
	}

	T sum(int k)
	{
		T ret = 0;
		for (; k > 0; k -= k & -k) ret += data[k];
		return (ret);
	}

	void add(int k, T x)
	{
		for (++k; k < data.size(); k += k & -k) data[k] += x;
	}
};


struct line
{
	LL A, B, C;
};


const LD EPS = 1e-9;
vector<line>plane;

LL getDrop(LD X, BinaryIndexedTree<LL>& bit)
{
	bit.init();
	vector<pair<LD, int>>cash;
	for (int i = 0; i < N; ++i)
	{
		const auto& lin = plane[i];
		LD Y = lin.C - lin.A * X;
		Y /= lin.B;
		cash.push_back({ Y,i });
	}
	sort(cash.rbegin(), cash.rend());
	LL ret = 0;
	for (int i = 0; i < N; ++i)
	{
		ret += bit.sum(cash[i].second);
		bit.add(cash[i].second, 1);
	}
	return ret;
}
LD getMedian()
{
	BinaryIndexedTree<LL>bit(N);
	LD lo = -1e10, hi = 1e10;
	while (hi - lo > EPS)
	{
		LD mid = (lo + hi) / 2;
		LL res = getDrop(mid, bit);
		if (res * 2 < M)
		{
			lo = mid;
		}
		else
		{
			hi = mid;
		}
	}
	return hi;
}

int main(void)
{
	cin >> N;
	M = (N - 1) * (N) / 2;
	for (int i = 0; i < N; ++i)
	{
		int a, b, c;
		cin >> a >> b >> c;
		plane.push_back({ a,b,c });
	}
	sort(plane.begin(), plane.end(), [](const line& l1, const line& l2)
	{
		return (LD)l1.A / l1.B < (LD)l2.A / l2.B;
	});
	LD xMedian = getMedian();
	for (int i = 0; i < N; ++i)
	{
		swap(plane[i].A, plane[i].B);
	}
	sort(plane.begin(), plane.end(), [](const line& l1, const line& l2)
	{
		return (LD)l1.A / l1.B < (LD)l2.A / l2.B;
	});
	LD yMedian = getMedian();
	cout.precision(15);
	cout << xMedian << " " << yMedian << endl;
	return 0;
}

#include <algorithm>
#include <cassert>
#include <cstdio>
#include <deque>
#include <random>
#include <vector>
#define repeat(i, n) for (int i = 0; (i) < int(n); ++(i))
#define whole(x) begin(x), end(x)
using namespace std;

int main() {
    // input
    int n; scanf("%d", &n);
    vector<int16_t> a(n), b(n), c(n);
    repeat (i, n) scanf("%hd%hd%hd", &a[i], &b[i], &c[i]);

    // solve

    // // find the windows
    constexpr int sample_size = 500000;
    constexpr int window_radius = 1000;
    vector<double> samples_x(sample_size);
    vector<double> samples_y(sample_size);
    default_random_engine gen;
    repeat (iteration, sample_size) {
        int i, j;
        do {
            i = uniform_int_distribution<int>(0, n - 1)(gen);
            j = uniform_int_distribution<int>(0, n - 1)(gen);
        } while (i == j);
        double den = a[i] * b[j] - a[j] * b[i];
        double x = (b[j] * c[i] - b[i] * c[j]) / den;
        double y = (a[j] * c[i] - a[i] * c[j]) / - den;
        samples_x[iteration] = x;
        samples_y[iteration] = y;
    }
    sort(whole(samples_x));
    sort(whole(samples_y));
    double dlx = samples_x[sample_size / 2 - window_radius];
    double drx = samples_x[sample_size / 2 + window_radius];
    double dly = samples_y[sample_size / 2 - window_radius];
    double dry = samples_y[sample_size / 2 + window_radius];
    bool determined_x = (dlx == drx);
    bool determined_y = (dly == dry);
    samples_x = vector<double>();
    samples_y = vector<double>();

    // // get poits in them
    int low_count_x = 0;
    int low_count_y = 0;
    float lx = dlx;
    float rx = drx;
    float ly = dly;
    float ry = dry;
    int zoom_x = 0;
    int zoom_y = 0;
    deque<double> bucket_x;
    deque<double> bucket_y;
    vector<int> flag(n);
    repeat (j, n) {
        {
            int aj = a[j];
            int bj = b[j];
            int cj = c[j];
            repeat (i, j) {
                float den = a[i] * bj - aj * b[i];
                float x = (bj * c[i] - b[i] * cj) / den;
                float y = (aj * c[i] - a[i] * cj) / - den;
                low_count_x += (x < lx);
                low_count_y += (y < ly);
                flag[i] = (int(lx <= x and x <= rx) * 2) | int(ly <= y and y <= ry);
            }
        }
        {
            double aj = a[j];
            double bj = b[j];
            double cj = c[j];
            repeat (i, j) if (flag[i]) {
                double den = a[i] * bj - aj * b[i];
                if (flag[i] & 2) {
                    double x = (bj * c[i] - b[i] * cj) / den;
                    bucket_x.push_back(x);
                }
                if (flag[i] & 1) {
                    double y = (aj * c[i] - a[i] * cj) / - den;
                    bucket_y.push_back(y);
                }
            }
        }
        for (; zoom_x < 80 and (zoom_x + 1) * 200000 < bucket_x.size(); ++ zoom_x) {
            lx = dlx + (drx - dlx) / 2 * (zoom_x / 100.0);
            rx = drx - (drx - dlx) / 2 * (zoom_x / 100.0);
        }
        for (; zoom_y < 80 and (zoom_y + 1) * 200000 < bucket_y.size(); ++ zoom_y) {
            ly = dly + (dry - dly) / 2 * (zoom_y / 100.0);
            ry = dry - (dry - dly) / 2 * (zoom_y / 100.0);
        }
    }

    // // make results
    int half = (n * (n - 1) / 2 - 1) / 2;
    double x;
    if (determined_x) {
        x = dlx;
    } else {
        int ix = half - low_count_x;
        assert (0 <= ix and ix < bucket_x.size());
        nth_element(bucket_x.begin(), bucket_x.begin() + ix, bucket_x.end());
        x = bucket_x[ix];
    }
    double y;
    if (determined_y) {
        y = dly;
    } else {
        int iy = half - low_count_y;
        assert (0 <= iy and iy < bucket_y.size());
        nth_element(bucket_y.begin(), bucket_y.begin() + iy, bucket_y.end());
        y = bucket_y[iy];
    }

    // output
    printf("%.15lf %.15lf\n", x, y);
    return 0;
}

