typedef struct linestruct{
  double a,b;
} line;

int cmpLine(const void *a,const void *b){
  double p=((line *)a)->a;
  double q=((line *)b)->a;
  return p-q>0?-1:1;
}

double *v=NULL;
int cmpV(const void *a,const void *b){
  int p=*(int *)a;
  int q=*(int *)b;
  return v[p]<v[q]?-1:1;
}

void init(int *bit){
  int n=bit[0];
  memset(bit+1,0,sizeof(int)*n);
}

int sum(int *bit,int index){
  int res=0;
  for(int i=index;i>0;i-=i&-i) res+=bit[i];
  return res;
}

void add(int *bit,int index){
  int n=bit[0];
  for(int i=index;i<=n;i+=i&-i) bit[i]++;
}

void run(void){
  int n;
  scanf("%d",&n);
  line *l=(line *)calloc(n,sizeof(line));
  int i;
  for(i=0;i<n;i++){
    int a,b,c;
    scanf("%d%d%d",&a,&b,&c);
    l[i].a=-(double)a/b;
    l[i].b=(double)c/b;
  }
  qsort(l,n,sizeof(line),cmpLine);
  v=(double *)calloc(n,sizeof(double));
  int *index=(int *)calloc(n,sizeof(int));
  int *bit=(int *)calloc(n+1,sizeof(int));
  bit[0]=n;
  double ll=-200000000;
  double rr=200000000;
  for(int iter=0;iter<100;iter++){
    double m=(ll+rr)/2;
    for(i=0;i<n;i++){
      v[i]=l[i].a*m+l[i].b;
      index[i]=i;
    }
    qsort(index,n,sizeof(int),cmpV);
    init(bit);
    int inv=0;
    for(i=0;i<n;i++){
      int p=index[i];
      inv+=sum(bit,p+1-1);
      add(bit,p+1);
    }
    if(2*inv<=n*(n-1)/2){
      rr=m;
    } else {
      ll=m;
    }
  }
  double ansX=ll;
  for(i=0;i<n;i++){
    double a=l[i].a;
    double b=l[i].b;
    l[i]=(line){1/a,-b/a};
  }
  qsort(l,n,sizeof(line),cmpLine);
  ll=-200000000;
  rr=200000000;
  for(int iter=0;iter<100;iter++){
    double m=(ll+rr)/2;
    for(i=0;i<n;i++){
      v[i]=l[i].a*m+l[i].b;
      index[i]=i;
    }
    qsort(index,n,sizeof(int),cmpV);
    init(bit);
    int inv=0;
    for(i=0;i<n;i++){
      int p=index[i];
      inv+=sum(bit,p+1-1);
      add(bit,p+1);
    }
    if(2*inv<=n*(n-1)/2){
      rr=m;
    } else {
      ll=m;
    }
  }
  double ansY=ll;
  printf("%.9lf %.9lf\n",ansX,ansY);
}

int main(void){
  run();
  return 0;
}

