ull msort (hwreal a[], ull n) {
	if (n <= 1) return 0;
	ull l = n / 2, r = n - l;
	ull inv = msort(a, l) + msort(a + l, r);
	sll i = 0, j = 0;
	hwreal tmp[n];

	while (i < l || j < r) {
		bool isr;
		if (i == l) {
			isr = true;
		} else if (j == r) {
			isr = false;
		} else if (a[i].b > a[l + j].b) {
			isr = true;
		} else {
			isr = false;
		}

		if (isr) {
			inv += (l - i);
			tmp[i + j] = a[l + j];
			j++;
		} else {
			tmp[i + j] = a[i];
			i++;
		}
	}
	for (i = 0; i < n; i++) {
		a[i] = tmp[i];
	}
	return inv;
}

