int a[10010],b[10010],c[10010];
void f(int i,int j,double *x,double *y){
  *x=(1.0*c[i]*b[j]-c[j]*b[i])/(a[i]*b[j]-a[j]*b[i]);
  *y=(1.0*c[j]*a[i]-c[i]*a[j])/(a[i]*b[j]-a[j]*b[i]);
}
int main(){
  int n,i,j;
  double sx1,sy1,sx2,sy2,rx=1e9,lx=-1e9,ry=1e9,ly=-1e9,x,y,eps=1e-9;
  double mx1,mx2,my1,my2;
  scanf("%d",&n);
  for(i=0;i<n;i++)scanf("%d %d %d",&a[i],&b[i],&c[i]);
  while(rx-lx>eps||ry-ly>eps){//printf("%.10f %.10f %.10f %.10f\n",lx,rx,ly,ry);
    mx1=(lx+lx+rx)/3;
    mx2=(lx+rx+rx)/3;
    my1=(ly+ly+ry)/3;
    my2=(ly+ry+ry)/3;
    sx1=sy1=sx2=sy2=0;
    for(i=0;i<n;i++){
      for(j=0;j<i;j++){
	f(i,j,&x,&y);
	sx1+=fabs(x-mx1);
	sx2+=fabs(x-mx2);
	sy1+=fabs(y-my1);
	sy2+=fabs(y-my2);
      }
    }
    sx1<sx2?(rx=mx2):(lx=mx1);
    sy1<sy2?(ry=my2):(ly=my1);
  }  
  printf("%.10lf %.10lf\n",lx,ly);
  return 0;
}
