}

long long inversion(long long a[],long long b[],long long n){
  long long i,c[524288],r=0;
  for(i=1;i<=n;i++){
    c[a[i]]=i;
  }
  for(i=1;i<=n;i++){
    r+=((i-1)-sum(c[b[i]]));
    add(c[b[i]],1);
  }
  for(i=1;i<=n;i++){
    add(c[b[i]],-1);
  }
  return r;
}

