// 線分と線分の交点取得
int
fGetCrsLine(
	double pdSx1				// <I> 線分１始点Ｘ
	, double pdSy1				// <I> 線分１始点Ｙ
	, double pdEx1				// <I> 線分１終点Ｘ
	, double pdEy1				// <I> 線分１終点Ｙ
	, double pdSx2				// <I> 線分２始点Ｘ
	, double pdSy2				// <I> 線分２始点Ｙ
	, double pdEx2				// <I> 線分２終点Ｘ
	, double pdEy2				// <I> 線分２終点Ｙ
	, double *pdpX				// <O> 交点Ｙ
	, double *pdpY				// <O> 交点Ｙ
)
{
	// ベクトル
	double ldBx1 = (pdEx1 - pdSx1);
	double ldBy1 = (pdEy1 - pdSy1);
	double ldBx2 = (pdEx2 - pdSx2);
	double ldBy2 = (pdEy2 - pdSy2);
	double ldKx = (pdSx2 - pdSx1);
	double ldKy = (pdSy2 - pdSy1);
	double ldVal = ldBx2 * ldBy1 - ldBy2 * ldBx1;

	// 交点取得
	double ldP1 = (ldBx2 * ldKy - ldBy2 * ldKx) / ldVal;
	double ldP2 = (ldBx1 * ldKy - ldBy1 * ldKx) / ldVal;
	*pdpX = pdSx1 + ldBx1 * ldP1;
	*pdpY = pdSy1 + ldBy1 * ldP1;

	return 0;
}

// 集合地点 - 取得
double
fGetPos(
	int piXY					// <I> [0]:X [1]:Y
)
{
	// 座標 - ソート
	if (piXY == 0) {
		qsort(sz1Point, siPCnt, sizeof(Point), fCmpFncXu);
	}
	else {
		qsort(sz1Point, siPCnt, sizeof(Point), fCmpFncYu);
	}

	// 集合地点
	int liNo = (siPCnt - 1) / 2;
	if (piXY == 0) {
		return sz1Point[liNo].mdX;
	}
	else {
		return sz1Point[liNo].mdY;
	}
}

