public class Main {
    public static void main(String[] args) throws Exception {
        BasicScanner sc = new BasicScanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        int[] b = new int[n];
        int[] c = new int[n];
        double[][] xa = new double[n][3];
        double[][] ya = new double[n][3];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            b[i] = sc.nextInt();
            c[i] = sc.nextInt();
            xa[i][0] = (double) a[i] / b[i];
            xa[i][1] = 1;
            xa[i][2] = (double) c[i] / b[i];
            ya[i][0] = 1;
            ya[i][1] = (double) b[i] / a[i];
            ya[i][2] = (double) c[i] / a[i];
        }
        Arrays.sort(xa, (u, v) -> Double.compare(u[0], v[0]));
        Arrays.sort(ya, (u, v) -> Double.compare(u[1], v[1]));

        TreeSet<Double> set = new TreeSet<>();

        final int k = n * (n - 1) / 2;
        final int m = (k + 1) / 2;

        double l, r;

        l = -2.1e8; r = 2.1e8;
        while (true) {
            double x = (l + r) / 2;
            if (l == x || x == r) break;
            set.clear();
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                double d = xa[i][2] - x * xa[i][0];
                cnt += set.tailSet(d).size();
                set.add(d);
            }
            if (cnt < m) l = x;
            else r = x;
        }
        double x = l;

        l = -2.1e8; r = 2.1e8;
        while (true) {
            double y = (l + r) / 2;
            if (l == y || y == r) break;
            set.clear();
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                double d = ya[i][2] - y * ya[i][1];
                cnt += set.tailSet(d).size();
                set.add(d);
            }
            if (cnt < m) l = y;
            else r = y;
        }
        double y = l;

        System.out.printf("%f %f\n",x ,y);
    }
}


