import java.util.*;
import java.io.*;

class Main{
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int n=fsc.nextInt();
        double[][] lines=new double[n][3];
        PriorityQueue<Double> pqx=new PriorityQueue<>(n*(n-1)/4+1);
        PriorityQueue<Double> pqy=new PriorityQueue<>(n*(n-1)/4+1);
        for(int i=0;i<n;i++){
            lines[i][0]=fsc.nextInt();
            lines[i][1]=fsc.nextInt();
            lines[i][2]=-fsc.nextInt();
        }
        fsc.close();
        for(int i=0;i<n-1;i++){
            for(int j=i+1;j<n;j++){
                int indx=i*(n-1)-i*(i-1)/2+j-(i+1);
                double p =lines[i][0]*lines[j][1]-lines[j][0]*lines[i][1];
                double qx=lines[i][1]*lines[j][2]-lines[j][1]*lines[i][2];
                double qy=lines[j][0]*lines[i][2]-lines[i][0]*lines[j][2];
                pqx.add(qx/p);
                pqy.add(qy/p);
                if(indx>n*(n-1)/4){
                    pqx.poll();
                    pqy.poll();
                }
            }
        }
        double ax, ay;
        ax=pqx.poll();
        ay=pqy.poll();
        System.out.println(ax+" "+ay);
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(System.in);
        Out o = new Out(System.out);
        solve(s, o);
        o.flush();
        o.close();
    }

    static int n, a[], b[], c[];

    static int cnt;

    public static void solve(ExtendedScanner sc, Out out) {
        n = sc.nextInt();
        a = new int[n];
        b = new int[n];
        c = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            b[i] = sc.nextInt();
            c[i] = sc.nextInt();
        }
        int m = n * (n - 1) / 2;
        int k = (m + 1) / 2;
        cnt = 0;
        double x = x(-2.1e8, 2.1e8, k);
        cnt = 0;
        double y = y(-2.1e8, 2.1e8, k);
        out.write(x).write(' ').write(y).write('\n');
    }

    static int max = 1;

    static int[] backet = new int[10000001];

    public static double x(double l, double r, int k) {
        if (cnt++ >= max) return l;
        double blk = (r - l) / 10000000;
        Arrays.fill(backet, 0);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double x = (double) -(c[i] * b[j] - c[j] * b[i]) / (b[i] * a[j] - b[j] * a[i]);
                if (l <= x && x <= r) {
                    backet[(int) ((x - l) / blk)]++;
                }
            }
        }
        if (backet[0] >= k) return x(l, l + blk, k);
        for (int i = 1;; i++) {
            backet[i] += backet[i - 1];
            if (backet[i] >= k) return x(l + blk * i, l + blk * (i + 1), k - backet[i - 1]);
        }
    }

    public static double y(double l, double r, int k) {
        if (cnt++ >= max) return l;
        double blk = (r - l) / 10000000;
        Arrays.fill(backet, 0);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double y = (double) (c[i] * a[j] - c[j] * a[i]) / (b[i] * a[j] - b[j] * a[i]);
                if (l <= y && y <= r) {
                    backet[(int) ((y - l) / blk)]++;
                }
            }
        }
        if (backet[0] >= k) return y(l, l + blk, k);
        for (int i = 1;; i++) {
            backet[i] += backet[i - 1];
            if (backet[i] >= k) return y(l + blk * i, l + blk * (i + 1), k - backet[i - 1]);
        }
    }
}


