/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskE solver = new TaskE();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskE {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int[] a = new int[n];
			int[] b = new int[n];
			int[] c = new int[n];
			for (int i = 0; i < n; i++) {
				a[i] = in.nextInt();
				b[i] = in.nextInt();
				c[i] = -in.nextInt();
				if (a[i] < 0) {
					a[i] = -a[i];
					b[i] = -b[i];
					c[i] = -c[i];
				}
			}
			double x = findX(n, a, b, c);
			double y = findX(n, b, a, c);
			out.printf("%.15f %.15f\n", x, y);
		}

		private double findX(int n, int[] a, int[] b, int[] c) {
			final double BOUND = 1e8 + 100;
			double l = -BOUND;
			double r = +BOUND;
			long k = (long) n * (n - 1) / 2;
			k = (k - 1) / 2;
			for (int step = 0; step < 50; step++) {
				double m = 0.5 * (l + r);
				long need = k;
				long got = 0;
				for (int i = 0; i < n; i++) {
					for (int j = i + 1; j < n; j++) {
						int u = c[i] * b[j] - c[j] * b[i];
						int v = a[i] * b[j] - a[j] * b[i];
						double x = -(double) u / v;
						if (x <= m) {
							++got;
						}
						if (got > need) {
							break;
						}
					}
				}
				if (got <= need) {
					l = m;
				} else {
					r = m;
				}
			}
			return 0.5 * (l + r);
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.io.FileNotFoundException;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) throws FileNotFoundException {
		new Main().run();
	}

	class BIT {
		int n;
		long[] a;

		public BIT(int n_) {
			n = n_;
			a = new long[n + 1];
		}

		void add(int k) {
			++k;
			while (k <= n) {
				++a[k];
				k += k & -k;
			}
		}

		long sum(int k) {
			++k;
			long ret = 0;
			while (k > 0) {
				ret += a[k];
				k -= k & -k;
			}
			return ret;
		}

	}

	boolean check(double m, double[][] ps) {

		int n = ps.length;
		Arrays.sort(ps, new Comparator<double[]>() {
			@Override
			public int compare(double[] o1, double[] o2) {
				return Double.compare(o1[0] * m - o1[1], o2[0] * m - o2[1]);
			}
		});

		long tot = n * (n - 1) / 2;
		long t = (tot + 1) / 2;

		long sum = 0;
		BIT bit = new BIT(n);
		for (int i = 0; i < n; ++i) {
			sum += bit.sum((int) ps[i][2]);
			bit.add((int) ps[i][2]);
		}
		return sum >= t;

	}

	double solve(int n, double[] x, double[] y) {
		double[][] ps = new double[n][3];
		for (int i = 0; i < n; ++i) {
			ps[i][0] = x[i];
			ps[i][1] = y[i];
		}
		Arrays.sort(ps, new Comparator<double[]>() {
			@Override
			public int compare(double[] o1, double[] o2) {
				if (o1[0] != o2[0])
					return Double.compare(o1[0], o2[0]);
				else
					return Double.compare(o1[1], o2[1]);
			}
		});

		for (int i = 0; i < n; ++i) {
			ps[i][2] = i;
		}

		double ok = 1e4;
		double ng = -1e4;

		for (int t = 50; t >= 0; --t) {
			double middle = (ok + ng) / 2;
			if (check(middle, ps)) {
				ok = middle;
			} else {
				ng = middle;
			}
		}
		return ok;
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		double[] a = new double[n];
		double[] b = new double[n];
		double[] c = new double[n];
		for (int i = 0; i < n; ++i) {
			a[i] = sc.nextDouble();
			b[i] = sc.nextDouble();
			c[i] = sc.nextDouble();
		}
		double[] x = new double[n];
		double[] y = new double[n];
		for (int i = 0; i < n; ++i) {
			y[i] = c[i] / b[i];
			x[i] = a[i] / b[i];
		}
		System.out.print(String.format("%.20f", solve(n, x, y)) + " ");
		for (int i = 0; i < n; ++i) {
			y[i] = c[i] / a[i];
			x[i] = b[i] / a[i];
		}
		System.out.println(String.format("%.20f", solve(n, x, y)));
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

