            }
            Complex[] pIabc=new Complex[3];
            pIabc[0]=pI(Complex.mul(a, -1.), b, c);
            pIabc[1]=pI(a, Complex.mul(b, -1.), c);
            pIabc[2]=pI(a, b, Complex.mul(c, -1.));
