class BinaryIndexedTree {
  private final int n;
  private final int[] values;

  BinaryIndexedTree(int n) {
    this.n = n;
    this.values = new int[n + 1];
  }

  public int sum(int index) {
    int value = 0;
    while (index > 0) {
      value += values[index];
      index -= index & -index;
    }
    return value;
  }

  public void add(int index, int value) {
    while (index <= n) {
      values[index] += value;
      index += index & -index;
    }
  }
}

