    long MOD = 1_000_000_007;
    long inf = Long.MAX_VALUE;

    void solve(){
        int n = ni();
        double[][] res = new double[n][3];
        for(int i = 0; i < n; i++){
            res[i][0] = (double)ni();
            res[i][1] = (double)ni();
            res[i][2] = (double)ni();
        }
        Arrays.sort(res, new Comparator<double[]>() {
            public int compare(double[] a, double[] b) {
                return Double.compare(-a[0]/a[1], -b[0]/b[1]);
            }
        });
        double left = -1000000000;
        double right = 1000000000;
        long total = n*(n-1)/2;
        for(int i = 0; i < 100; i++){
            double mid = (left+right)/2;
            if(judge(mid,res,n)>=total/2+1) left = mid;
            else right = mid; 
        }
        double x = left;
        Arrays.sort(res, new Comparator<double[]>() {
            public int compare(double[] a, double[] b) {
                return Double.compare(-a[1]/a[0], -b[1]/b[0]);
            }
        });
        left = -100000000;
        right = 100000000;
        for(int i = 0; i < 100; i++){
            double mid = (left+right)/2;
            if(judge2(mid,res,n)>=total/2+1) left = mid;
            else right = mid; 
        }
        double y = left;
        out.println(x+" "+y);
    }

    int judge(double mid, double[][] res, int n){
        double[][] line = new double[n][2];
        for(int i = 0; i < n; i++){
            line[i][0] = i;
            line[i][1] = (res[i][2]-res[i][0]*mid)/res[i][1];
        }
        Arrays.sort(line, (a,b) -> Double.compare(a[1],b[1]));
        BIT bit = new BIT(n);
        int num = 0;
        for(int i = 0; i < n; i++){
            int cur = (int)line[i][0];
            num += bit.sum(cur+1,n);
            bit.accumlate(cur,1);
        }
        return num;
    }

    int judge2(double mid, double[][] res, int n){
        double[][] line = new double[n][2];
        for(int i = 0; i < n; i++){
            line[i][0] = i;
            line[i][1] = (res[i][2]-res[i][1]*mid)/res[i][0];
        }
        Arrays.sort(line, (a,b) -> Double.compare(a[1],b[1]));
        BIT bit = new BIT(n);
        int num = 0;
        for(int i = 0; i < n; i++){
            int cur = (int)line[i][0];
            num += bit.sum(cur+1,n);
            bit.accumlate(cur,1);
        }
        return num;
    }

    class BIT {
    private int n;
    private long[] bit;
    public BIT(int n) {
        this.n = n;
        bit = new long[n+1];
    }

    public void accumlate(int index,long num) {
        index++;
        while(index<=n) {
            bit[index] += num;
            index+=index&-index;
        }
    }

    /* [begin , end) */
    public long sum(int begin,int end) {
        return sum(end) - sum(begin);
    }

    private long sum(int i) {
        long s = 0;
        while(i>0) {
            s+=bit[i];
            i-=i&-i;
        }
        return s;
    }

    public long get(int index) {
        return sum(index,index+1);
    }

    public void set(int index,long num) {
        accumlate(index,num-(sum(index)-sum(index-1)));
    }

    public String toString() {
        long[] value = new long[n];
        for(int i=0;i<n;i++) {
            value[i] = get(i);
        }
        return Arrays.toString(value);
    }
}

