	static class TaskE {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int[] a = new int[n];
			int[] b = new int[n];
			int[] c = new int[n];
			for (int i = 0; i < n; i++) {
				a[i] = in.nextInt();
				b[i] = in.nextInt();
				c[i] = -in.nextInt();
				if (a[i] < 0) {
					a[i] = -a[i];
					b[i] = -b[i];
					c[i] = -c[i];
				}
			}
			double x = findX(n, a, b, c);
			for (int i = 0; i < n; i++) {
				int t = a[i];
				a[i] = b[i];
				b[i] = t;
			}
			double y = findX(n, a, b, c);
			out.printf("%.15f %.15f\n", x, y);
		}

		private double findX(int n, int[] a, int[] b, int[] c) {
			if (n < 2000) {
				double[] xs = new double[n * (n - 1) / 2];
				int p = 0;
				for (int i = 0; i < n; i++) {
					for (int j = i + 1; j < n; j++) {
						int u = c[i] * b[j] - c[j] * b[i];
						int v = a[i] * b[j] - a[j] * b[i];
						xs[p++] = -(double) u / v;
					}
				}
				Arrays.sort(xs);
				return xs[(xs.length - 1) / 2];
			}
			// Time limit check.
			int res = 0;
			for (int i = 0; i < n; i++) {
				for (int j = i + 1; j < n; j++) {
					int u = c[i] * b[j] - c[j] * b[i];
					int v = a[i] * b[j] - a[j] * b[i];
					if (u > v) {
						++res;
					}
				}
			}
			return res;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

