public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    // int mod = 998244353;
    long inf = Long.MAX_VALUE/2;
    int n;
    double[][] line;
    double[][] line2;
    double[][] cross;

    void solve(){
        n = ni();
        line = new double[n][3];

        cross = new double[n][2];
        for(int i = 0; i < n; i++){
            line[i][0] = nl();
            line[i][1] = nl();
            line[i][2] = nl();
        }
        Arrays.sort(line, new Comparator<double[]>() {
            public int compare(double[] a, double[] b) {
                return Double.compare(-a[0]/a[1],-b[0]/b[1]);
            }
        });
        double left = -100000000;
        double right = 100000000;
        int half = (n*(n-1)/2)/2;
        for(int i = 0; i < 200; i++){
            double mid = (right+left)/2;
            if(f(mid)>half) left = mid;
            else right = mid;
            // out.println(f(mid)+" "+mid);
        }
        out.println(left);

        line2 = new double[n][3];
        for(int i = 0; i < n; i++){
            line2[i][0] = line[i][1];
            line2[i][1] = line[i][0];
            line2[i][2] = line[i][2];
        }

        Arrays.sort(line2, new Comparator<double[]>() {
            public int compare(double[] a, double[] b) {
                return Double.compare(-a[0]/a[1],-b[0]/b[1]);
            }
        });

        left = -1000000;
        right = 1000000;
        for(int i = 0; i < 60; i++){
            double mid = (right+left)/2;
            if(f2(mid)>half) left = mid;
            else right = mid;
        }
        out.println(left);

    }

    int f(double mid){
        BIT bi = new BIT(n);
        for(int i = 0; i < n; i++){
            cross[i][0] = (-line[i][0]*mid+line[i][2])/line[i][1];
            cross[i][1] = i;
        }
        Arrays.sort(cross, new Comparator<double[]>() {
            public int compare(double[] a, double[] b) {
                if(a[0]==b[0]) return Double.compare(a[1], b[1]);
                return Double.compare(a[0], b[0]);
            }
        });
        int ret = 0;
        for(int i = 0; i < n; i++){
            int tmp = (int)cross[i][1];
            ret += bi.sum(tmp, n);
            bi.accumlate(tmp, 1);
        }


        return ret;
    }

    int f2(double mid){
        BIT bi = new BIT(n);
        for(int i = 0; i < n; i++){
            cross[i][0] = (-line2[i][0]*mid+line2[i][2])/line2[i][1];
            cross[i][1] = i;
        }
        Arrays.sort(cross, new Comparator<double[]>() {
            public int compare(double[] a, double[] b) {
                if(a[0]==b[0]) return Double.compare(a[1], b[1]);
                return Double.compare(a[0], b[0]);
            }
        });
        int ret = 0;
        for(int i = 0; i < n; i++){
            int tmp = (int)cross[i][1];
            ret += bi.sum(tmp, n);
            bi.accumlate(tmp, 1);
        }


        return ret;
    }

    class BIT {
    private int n;
    private long[] bit;
    public BIT(int n) {
        this.n = n;
        bit = new long[n+1];
    }

    public void accumlate(int index,long num) {
        index++;
        while(index<=n) {
            bit[index] += num;
            index+=index&-index;
        }
    }

    /* [begin , end) */
    public long sum(int begin,int end) {
        return sum(end) - sum(begin);
    }

    private long sum(int i) {
        long s = 0;
        while(i>0) {
            s+=bit[i];
            i-=i&-i;
        }
        return s;
    }

    public long get(int index) {
        return sum(index,index+1);
    }

    public void set(int index,long num) {
        accumlate(index,num-(sum(index)-sum(index-1)));
    }

    public String toString() {
        long[] value = new long[n];
        for(int i=0;i<n;i++) {
            value[i] = get(i);
        }
        return Arrays.toString(value);
    }
}

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(System.in);
        Out o = new Out(System.out);
        solve(s, o);
        o.flush();
        o.close();
    }

    static int n, a[], b[], c[];

    static int cnt;

    public static void solve(ExtendedScanner sc, Out out) {
        n = sc.nextInt();
        a = new int[n];
        b = new int[n];
        c = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            b[i] = sc.nextInt();
            c[i] = sc.nextInt();
        }
        int m = n * (n - 1) / 2;
        int k = (m + 1) / 2;
        cnt = 0;
        double x = x(-3e8, 3e8, k);
        cnt = 0;
        double y = y(-3e8, 3e8, k);
        out.write(x).write(' ').write(y).write('\n');
    }

    static int max = 6;

    static int[] backet = new int[25000];

    public static double x(double l, double r, int k) {
        System.out.println(r - l);
        if (cnt++ >= max) return l;
        double sq = cnt <= 2 ? Math.sqrt(r - l) : (r - l) / 1000;
        Arrays.fill(backet, 0);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double x = (double) -(c[i] * b[j] - c[j] * b[i]) / (b[i] * a[j] - b[j] * a[i]);
                if (l <= x && x <= r) {
                    backet[(int) ((x - l) / sq)]++;
                }
            }
        }
        if (backet[0] >= k) return x(l, l + sq, k);
        for (int i = 1;; i++) {
            backet[i] += backet[i - 1];
            if (backet[i] >= k) return x(l + sq * i, l + sq * (i + 1), k - backet[i - 1]);
        }
    }

    public static double y(double l, double r, int k) {
        if (cnt++ >= max) return l;
        double sq = cnt <= 2 ? Math.sqrt(r - l) : (r - l) / 1000;
        Arrays.fill(backet, 0);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double y = (double) (c[i] * a[j] - c[j] * a[i]) / (b[i] * a[j] - b[j] * a[i]);
                if (l <= y && y <= r) {
                    backet[(int) ((y - l) / sq)]++;
                }
            }
        }
        if (backet[0] >= k) return y(l, l + sq, k);
        for (int i = 1;; i++) {
            backet[i] += backet[i - 1];
            if (backet[i] >= k) return y(l + sq * i, l + sq * (i + 1), k - backet[i - 1]);
        }
    }
}


