        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        double[] A = new double[N];
        double[] B = new double[N];
        double[] C = new double[N];
        for(int i=0;i<N;i++){
            double a = re.i();
            double b = re.i();
            double c = re.i();
            A[i] = a;
            B[i] = b;
            C[i] = c;
        }
        int[] O = new int[N];
        for(int i=0;i<N;i++){
            O[i] = i;
        }
        {
            double[] X = new double[N];
            for(int i=0;i<N;i++){
                X[i] = A[i]/B[i];
            }
            Array.Sort(X,O);
            int[] O2 = new int[N];
            for(int i=0;i<N;i++){
                O2[O[i]] = i;
            }
            O = O2;
        }
        double bf = -1000000000;
        double bl = 1000000000;
        int M = (N*(N-1)/2+1)/2;
        while(bf + 0.000000001 <= bl){
            double bc = (bf+bl)/2;
            double[] Y = new double[N];
            int[] O2 = new int[N];
            for(int i=0;i<N;i++){
                Y[i] = (C[i]-A[i]*bc)/B[i];
                O2[i] = i;
            }
            Array.Sort(Y,O2);
            BIT bit = new BIT(N);
            int count = 0;
            for(int i=N-1;i>=0;i--){
                count += bit.Sum(O[O2[i]]);
                bit.Add(O[O2[i]]);
            }
            if(count >= M){
                bl = bc;
            }
            else{
                bf = bc;
            }
        }
        sb.Append((bf+bl)/2+" ");
        for(int i=0;i<N;i++){
            O[i] = i;
        }
        {
            double[] Y = new double[N];
            for(int i=0;i<N;i++){
                Y[i] = B[i]/A[i];
            }
            Array.Sort(Y,O);
            int[] O2 = new int[N];
            for(int i=0;i<N;i++){
                O2[O[i]] = i;
            }
            O = O2;
        }
