struct BIT{
    int[] A;
    public BIT(int N){
        A = new int[N+1];
    }
    public void Add(int v){
        v++;
        while(v < A.Length){
            A[v]++;
            v += v & (-v);
        }
    }
    public int Sum(int v){
        v++;
        int C = 0;
        while(v > 0){
            C += A[v];
            v -= v & (-v);
        }
        return C;
    }
}
