using System;
using System.Text;
using System.Collections.Generic;
using System.Linq;
class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        double[] A = new double[N];
        double[] C = new double[N];
        for(int i=0;i<N;i++){
            double a = re.i();
            double b = re.i();
            double c = re.i();
            A[i] = a/b;
            C[i] = c/b;
        }
        double[] X = new double[N*(N-1)/2];
        double[] Y = new double[N*(N-1)/2];
        int d = 0;
        for(int i=0;i<N;i++){
            for(int j=i+1;j<N;j++){
                double x = (C[i]-C[j])/(A[i]-A[j]);
                double y = -x*A[i] + C[i];
                X[d] = x;
                Y[d] = y;
                d++;
            }
        }
        Array.Sort(X);
        Array.Sort(Y);
        sb.Append(X[((N*(N-1)/2)-1)/2]+" "+Y[((N*(N-1)/2)-1)/2]+"\n");
    }

}
