fn solve(mut lines: Vec<(f64, f64, f64)>) -> f64 {
    let n = lines.len();
    let center = (n * (n - 1) / 2 + 1) / 2;

    let mut low = -1e9;
    lines.sort_by_key(|&(a, b, c)| F64((-a * low + c) / b));
