const INF: f64 = 1e15;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let n: usize = sc.read();
    let abc: Vec<_> = (0..n).map(|_| (sc.read(), sc.read(), sc.read())).collect();
    let bac = abc.iter().map(|&(a, b, c)| (b, a, c)).collect();

    let x = solve(abc);
    let y = solve(bac);
    println!("{} {}", x, y);
}

fn solve(mut abc: Vec<(f64, f64, f64)>) -> f64 {
    let n = abc.len();
    let total = n * (n - 1) / 2;
    abc.sort_by(|&(a1, b1, c1), &(a2, b2, c2)| {
        let k1 = (c1 - a1 * (-INF)) / b1;
        let k2 = (c2 - a2 * (-INF)) / b2;
        if k1 > k2 {
            std::cmp::Ordering::Less
        } else if k1 < k2 {
            std::cmp::Ordering::Greater
        } else {
            std::cmp::Ordering::Equal
        }
    });
    let mut abc: Vec<_> = abc
        .into_iter()
        .enumerate()
        .map(|(i, (a, b, c))| (a, b, c, i))
        .collect();

    let mut ok = INF;
    let mut ng = -INF;
    let mut p_ok = ok;
    let mut p_ng = ng;
    loop {
        let x = (ok + ng) / 2.0;
        abc.sort_by(|&(a1, b1, c1, _), &(a2, b2, c2, _)| {
            let k1 = (c1 - a1 * (x)) / b1;
            let k2 = (c2 - a2 * (x)) / b2;
            if k1 > k2 {
                std::cmp::Ordering::Less
            } else if k1 < k2 {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        });

        let mut ans: usize = 0;
        let mut bit = FenwickTree::new(n, 0);
        for i in 0..n {
            let (_, _, _, x) = abc[i];
            ans += bit.sum(x, n);
            bit.add(x, 1);
        }

        if ans * 2 >= total {
            ok = x;
        } else {
            ng = x;
        }

        if p_ok == ok && p_ng == ng {
            break;
        }
        p_ok = ok;
        p_ng = ng;
    }
    ok
}

