use std::cmp::Ordering;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let abc: Vec<(f64, f64, f64)> = (0..n).map(|_| (sc.read(), sc.read(), sc.read())).collect();
    let bac = abc.iter().map(|&(a, b, c)| (b, a, c)).collect();
    let x = solve(abc);
    let y = solve(bac);
    println!("{} {}", x, y);
}

fn solve(mut abc: Vec<(f64, f64, f64)>) -> f64 {
    let n = abc.len();
    let total = n * (n - 1) / 2;
    let count = (total + 1) / 2;

    let mut high = 1e15 as f64;
    let mut low = -1e15 as f64;
    let mut prev_high = high;
    let mut prev_low = low;

    abc.sort_by_key(|&(a, b, c)| F64((-a * low + c) / b));

    loop {
        let x = (high + low) / 2.0;
        let mut v: Vec<(F64, usize)> = abc.iter().enumerate().map(|(i, &(a, b, c))| (F64((-a * x + c) / b), i)).collect();
        v.sort();

        let mut bit = fenwick_tree::FenwickTree::new(v.len(), 0);
        let mut result = 0;
        for &(_, i) in v.iter() {
            result += i - bit.sum_one(i + 1);
            bit.add(i, 1);
        }

        if result >= count { high = x; } else { low = x; }
        if prev_high == high && prev_low == low { break; }
        prev_high = high;
        prev_low = low;
    }
    (high + low) / 2.0
}

