fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let n = sc.read();
    let mut a: Vec<f64> = vec![];
    let mut b: Vec<f64> = vec![];
    let mut c: Vec<f64> = vec![];
    for _ in 0..n {
        a.push(sc.read());
        b.push(sc.read());
        c.push(sc.read());
    }

    let x = solve(&a, &b, &c);
    let y = solve(&b, &a, &c);
    println!("{} {}", x, y);
}

fn solve(a: &[f64], b: &[f64], c: &[f64]) -> f64 {
    let n = a.len();
    let points = n * (n - 1) / 2;
    let num = (points + 1) / 2;
    let mut low = -1e15;
    let mut high = 1e15;
    let mut p_low = low;
    let mut p_high = high;

    let mut lines = (0..n)
        .map(|i| (F64((c[i] - a[i] * low) / b[i]), i))
        .collect::<Vec<_>>();
    lines.sort();

    loop {
        let x = (high + low) / 2.0;

        let mut lines = lines
            .iter()
            .map(|&(_, i)| (a[i], b[i], c[i]))
            .enumerate()
            .map(|(i, (a, b, c))| (F64((c - a * x) / b), i))
            .collect::<Vec<_>>();
        lines.sort();

        let mut bit = fenwick_tree::FenwickTree::new(n, 0);
        let mut ans = 0;
        for (_, i) in lines.into_iter().rev() {
            ans += bit.sum_one(i);
            bit.add(i, 1);
        }

        if ans >= num {
            high = x;
        } else {
            low = x;
        }

        if high == p_high && low == p_low {
            break;
        }
        p_low = low;
        p_high = high;
    }
    (high + low) / 2.0
}

