struct BIT {
    buf: Vec<usize>,
}

impl BIT {
    fn new(n: usize) -> BIT {
        BIT { buf: vec![0; n + 1] }
    }

    fn sum(&self, i: usize) -> usize {
        let mut i = i;
        let mut s = 0;
        while i > 0 {
            s += self.buf[i];
            i = i & (i - 1);
        }
        s
    }

    fn add(&mut self, i: usize, x: usize) {
        let mut i = i as i64;
        while i < self.buf.len() as i64 {
            self.buf[i as usize] += x;
            i += i & -i;
        }
    }
}

fn num_swaps(v: &Vec<usize>) -> usize {
    let mut bit = BIT::new(v.len());
    let mut ans = 0;
    for i in 0..v.len() {
        ans += i - bit.sum(v[i]);
        bit.add(v[i], 1);
    }
    ans
}

fn num_points(x: f64, lines: &Vec<(f64, f64, f64)>) -> usize {
    let mut v: Vec<_> = lines
        .iter()
        .map(|&(a, b, c)| (c - a * x) / b)
        .enumerate()
        .collect();
    v.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap());
    let order: Vec<usize> = v.iter().map(|t| t.0 + 1).collect();
    num_swaps(&order)
}

fn bin_search(target: usize, low: f64, high: f64, lines: &Vec<(f64, f64, f64)>) -> f64 {
    let mid = (low + high) / 2.0;

    let diff = high - low;

    if diff < 1e-9 || (diff / low).abs() < 1e-9 {
        return mid;
    }

    match num_points(mid, lines).cmp(&target) {
        Ordering::Less => bin_search(target, mid, high, lines),
        Ordering::Equal => bin_search(target, low, mid, lines),
        Ordering::Greater => bin_search(target, low, mid, lines),
    }
}

fn main() {
    let n: usize = util::get();
    let mut abc: Vec<(f64, f64, f64)> = (0..n)
        .map(|_| {
            let abc: Vec<i64> = util::gets();
            (abc[0] as f64, abc[1] as f64, abc[2] as f64)
        })
        .collect();

    abc.sort_by(|e1, e2| (e1.0 / e1.1).partial_cmp(&(e2.0 / e2.1)).unwrap());
    let xabc = abc.clone();
    abc = abc.into_iter().map(|(a, b, c)| (b, a, c)).collect();
    abc.sort_by(|e1, e2| (e1.0 / e1.1).partial_cmp(&(e2.0 / e2.1)).unwrap());
    let yabc = abc;

    let target = (n * (n - 1) + 3) / 4;

    println!(
        "{} {}",
        bin_search(target, -1e9, 1e9, &xabc),
        bin_search(target, -1e9, 1e9, &yabc)
    );

}

pub trait IterScan: Sized {
    type Output;
    fn scan<'a, I: Iterator<Item = &'a str>>(iter: &mut I) -> Option<Self::Output>;
}
pub trait MarkedIterScan: Sized {
    type Output;
    fn mscan<'a, I: Iterator<Item = &'a str>>(self, iter: &mut I) -> Option<Self::Output>;
}
#[derive(Debug)]
pub struct Scanner<'a> {
    iter: std::str::SplitAsciiWhitespace<'a>,
}
impl<'a> Scanner<'a> {
    #[inline]
    pub fn new(s: &'a str) -> Self {
        let iter = s.split_ascii_whitespace();
        Self { iter }
    }
    #[inline]
    pub fn scan<T: IterScan>(&mut self) -> <T as IterScan>::Output {
        T::scan(&mut self.iter).unwrap()
    }
    #[inline]
    pub fn mscan<T: MarkedIterScan>(&mut self, marker: T) -> <T as MarkedIterScan>::Output {
        marker.mscan(&mut self.iter).unwrap()
    }
    #[inline]
    pub fn scan_vec<T: IterScan>(&mut self, size: usize) -> Vec<<T as IterScan>::Output> {
        (0..size)
            .map(|_| T::scan(&mut self.iter).unwrap())
            .collect()
    }
    #[inline]
    pub fn scan_chars(&mut self) -> Vec<char> {
        self.iter.next().unwrap().chars().collect::<Vec<char>>()
    }
    #[inline]
    pub fn scan_chars_with(&mut self, base: char) -> Vec<usize> {
        self.iter
            .next()
            .unwrap()
            .chars()
            .map(|c| (c as u8 - base as u8) as usize)
            .collect::<Vec<usize>>()
    }
}
