        },
        1e10,
        -1e10,
    );
    idx.sort_by(|&i, &j| cmp(-abc[i].1, abc[i].0, -abc[j].1, abc[j].0));
    let mut z = 0;
    let y = binary_search(
        |x| {
            z += 1;
            p.sort_by(|&i, &j| {
                let (bi, ai, ci) = abc[idx[i]];
                let (bj, aj, cj) = abc[idx[j]];
                let l = aj * bi.abs() * bj.signum() - ai * bj.abs() * bi.signum();
                let r = cj * bi.abs() * bj.signum() - ci * bj.abs() * bi.signum();
                (l as f64 * x).partial_cmp(&(r as f64)).unwrap()
            });
            let mut cnt = 0;
            let mut bit = BinaryIndexedTree::new(n, AdditiveOperation::new());
            for (i, &p) in p.iter().enumerate() {
                cnt += i - bit.accumulate0(p);
                bit.update(p, 1);
            }
            cnt <= k || z >= 100
        },
        1e10,
        -1e10,
    );
    println!("{} {}", x, y);
}

