        .map(|_| (sc.read(), sc.read(), sc.read()))
        .collect::<Vec<(f64, f64, f64)>>();
    let lines_y = lines.iter().map(|&(a, b, c)| (b, a, c)).collect();
    let x = solve(lines);
    let y = solve(lines_y);
